  function applyNativeMenuSettings(type, items) {
    const defs = getNativeMenuDefaults(type);
    if (!defs.length) return Array.isArray(items) ? items.slice() : [];
    const cfg = getNativeMenuSettings(type);
    const byId = new Map();
    for (const item of (Array.isArray(items) ? items : [])) {
      if (item && item._nativeId) byId.set(item._nativeId, item);
    }
    const ordered = [];
    for (const id of cfg.order) {
      if (cfg.hidden[id] === true) continue;
      const item = byId.get(id);
      if (item) ordered.push(item);
    }
    const out = [];
    for (const item of ordered) {
      if (!item) continue;
      const clone = { ...item };
      delete clone._nativeId;
      delete clone._nativeLabel;
      out.push(clone);
    }
    return out;
  }

  function buildNativeMenuSettingsEditor() {
    const wrap = document.createElement("div");
    wrap.className = "wmeRcSettingsView";

    const sections = document.createElement("div");
    sections.className = "wmeRcSettingsView";
    wrap.appendChild(sections);

    const state = loadAllNativeMenuSettings();
    const collapsed = { map: true, segment: true, place: true };
    const groups = [
      { id: "map", label: "Map", desc: "Empty map clicks." },
      { id: "segment", label: "Segment", desc: "Selected segment actions." },
      { id: "place", label: "Place", desc: "Place-related actions." },
    ];

    function saveGroup(groupId, cfg) {
      state[groupId] = normalizeNativeMenuSettings(groupId, cfg);
      saveAllNativeMenuSettings(state);
    }

    function mountSortable(list, groupId, cfg, rerender) {
      let drag = null;
      const rows = () => Array.from(list.querySelectorAll('[data-native-id]'));

      function onMove(ev) {
        if (!drag) return;
        drag.row.style.top = `${Math.round(ev.clientY - drag.offsetY)}px`;
        const others = rows().filter(r => r !== drag.row);
        let placed = false;
        for (const row of others) {
          const rect = row.getBoundingClientRect();
          const midpoint = rect.top + (rect.height / 2);
          if (ev.clientY < midpoint) {
            if (drag.placeholder !== row.previousSibling) list.insertBefore(drag.placeholder, row);
            placed = true;
            break;
          }
        }
        if (!placed) list.appendChild(drag.placeholder);
      }

      function onUp() {
        if (!drag) return;
        try { document.removeEventListener('pointermove', onMove, true); } catch {}
        try { document.removeEventListener('pointerup', onUp, true); } catch {}
        try { document.removeEventListener('pointercancel', onUp, true); } catch {}
        try { document.body.style.userSelect = ''; } catch {}

        const otherIds = rows().filter(r => r !== drag.row).map(r => r.dataset.nativeId);
        const slot = Math.max(0, Array.from(list.children).indexOf(drag.placeholder));
        otherIds.splice(Math.min(slot, otherIds.length), 0, drag.row.dataset.nativeId);
        cfg.order = otherIds;
        saveGroup(groupId, cfg);

        drag.row.style.position = '';
        drag.row.style.left = '';
        drag.row.style.top = '';
        drag.row.style.width = '';
        drag.row.style.height = '';
        drag.row.style.zIndex = '';
        drag.row.style.pointerEvents = '';
        drag.row.style.boxShadow = '';
        drag.row.style.opacity = '';
        drag.row.style.transform = '';
        list.insertBefore(drag.row, drag.placeholder);
        if (drag.placeholder.parentNode) drag.placeholder.parentNode.removeChild(drag.placeholder);
        drag = null;
        rerender();
      }

      rows().forEach(row => {
        const handle = row.querySelector('.wmeRcNativeHandle');
        if (!handle) return;
        handle.addEventListener('pointerdown', (ev) => {
          if (ev.button != null && ev.button !== 0) return;
          ev.preventDefault();
          ev.stopPropagation();
          const rect = row.getBoundingClientRect();
          const placeholder = document.createElement('div');
          placeholder.className = 'wmeRcNativePlaceholder';
          placeholder.style.height = `${Math.round(rect.height)}px`;
          placeholder.style.borderRadius = '12px';
          placeholder.style.border = '1px dashed rgba(127,127,127,.35)';
          placeholder.style.background = 'transparent';
          list.insertBefore(placeholder, row.nextSibling);

          drag = { row, placeholder, offsetY: ev.clientY - rect.top };
          row.style.position = 'fixed';
          row.style.left = `${Math.round(rect.left)}px`;
          row.style.top = `${Math.round(rect.top)}px`;
          row.style.width = `${Math.round(rect.width)}px`;
          row.style.height = `${Math.round(rect.height)}px`;
          row.style.zIndex = '999999';
          row.style.pointerEvents = 'none';
          row.style.boxShadow = '0 12px 28px rgba(0,0,0,.24)';
          row.style.opacity = '1';
          row.style.transform = 'none';
          try { document.body.style.userSelect = 'none'; } catch {}

          document.addEventListener('pointermove', onMove, true);
          document.addEventListener('pointerup', onUp, true);
          document.addEventListener('pointercancel', onUp, true);
        });
      });
    }

    function render() {
      sections.innerHTML = "";
      for (const group of groups) {
        const cfg = state[group.id] || normalizeNativeMenuSettings(group.id, null);
        const defs = getNativeMenuDefaults(group.id);
        const orderedDefs = cfg.order.map(id => defs.find(d => d.id === id)).filter(Boolean);

        const card = document.createElement("div");
        card.className = "wmeRcSideCard wmeRcSettingsCard wmeRcNativeSectionCard";

        const head = document.createElement("div");
        head.className = 'wmeRcSettingsHeader';

        const headRow = document.createElement('div');
        headRow.className = 'wmeRcSettingsHeaderRow wmeRcNativeSectionHeaderRow';

        const mainToggle = document.createElement('button');
        mainToggle.type = 'button';
        mainToggle.className = 'wmeRcNativeSectionToggle';
        mainToggle.setAttribute('aria-expanded', collapsed[group.id] ? 'false' : 'true');
        mainToggle.setAttribute('aria-label', `${collapsed[group.id] ? 'Expand' : 'Collapse'} ${group.label}`);

        const titleWrap = document.createElement('div');
        titleWrap.className = 'wmeRcNativeSectionTitleWrap';

        const titleEl = document.createElement('div');
        titleEl.className = 'wmeRcSideTitle';
        titleEl.textContent = group.label;
        titleWrap.appendChild(titleEl);

        const countEl = document.createElement('div');
        countEl.className = 'wmeRcNativeSectionCount';
        const enabledCount = orderedDefs.filter(d => cfg.hidden[d.id] !== true).length;
        countEl.textContent = `${enabledCount}/${orderedDefs.length} enabled`;
        titleWrap.appendChild(countEl);

        mainToggle.appendChild(titleWrap);
        headRow.appendChild(mainToggle);

        const actions = document.createElement('div');
        actions.className = 'wmeRcActionsRow wmeRcNativeSectionActions';
        actions.style.marginTop = '0';

        const reset = document.createElement('button');
        reset.type = 'button';
        reset.className = 'wmeRcSideNavBtn';
        reset.textContent = 'Reset';
        reset.addEventListener('click', (ev) => {
          try { ev.preventDefault(); ev.stopPropagation(); } catch {}
          state[group.id] = normalizeNativeMenuSettings(group.id, null);
          saveAllNativeMenuSettings(state);
          render();
        });
        actions.appendChild(reset);

        const chevronButton = document.createElement('button');
        chevronButton.type = 'button';
        chevronButton.className = 'wmeRcNativeSectionChevronBtn';
        chevronButton.setAttribute('aria-expanded', collapsed[group.id] ? 'false' : 'true');
        chevronButton.setAttribute('aria-label', `${collapsed[group.id] ? 'Expand' : 'Collapse'} ${group.label}`);
        chevronButton.title = collapsed[group.id] ? 'Expand category' : 'Collapse category';
        chevronButton.innerHTML = `
          <span class="wmeRcNativeSectionChevron">
            <svg class="wmeRcNativeSectionChevronSvg" viewBox="0 0 20 20" aria-hidden="true">
              <path d="M4.47 7.97a.75.75 0 0 1 1.06 0L10 12.44l4.47-4.47a.75.75 0 1 1 1.06 1.06l-5 5a.75.75 0 0 1-1.06 0l-5-5a.75.75 0 0 1 0-1.06Z"/>
            </svg>
          </span>
        `;
        actions.appendChild(chevronButton);

        headRow.appendChild(actions);
        head.appendChild(headRow);

        const sub = document.createElement('div');
        sub.className = 'wmeRcSideSub';
        sub.textContent = group.desc;
        head.appendChild(sub);

        const toggleSection = (ev) => {
          try { ev?.preventDefault(); ev?.stopPropagation(); } catch {}
          collapsed[group.id] = !collapsed[group.id];
          render();
        };

        mainToggle.addEventListener('click', toggleSection);
        chevronButton.addEventListener('click', toggleSection);

        card.appendChild(head);

        const list = document.createElement('div');
        list.className = 'wmeRcSettingsBody wmeRcNativeSectionBody' + (collapsed[group.id] ? ' is-collapsed' : '');

        orderedDefs.forEach((def) => {
          const row = document.createElement('div');
          row.dataset.nativeId = def.id;
          row.className = 'wmeRcNativeActionRow' + (cfg.hidden[def.id] === true ? ' is-disabled' : '');

          const left = document.createElement('div');
          left.className = 'wmeRcNativeActionLeft';

          const chk = document.createElement('input');
          chk.type = 'checkbox';
          chk.checked = cfg.hidden[def.id] !== true;
          try { chk.style.display = 'none'; } catch {}

          const selBox = document.createElement('div');
          selBox.className = 'wmeRcPinSelectBox' + (chk.checked ? ' on' : '');
          selBox.innerHTML = `<span class="wmeRcI">${ICONS.check}</span>`;

          const meta = document.createElement('div');
          meta.className = 'wmeRcNativeActionMeta';

          const title = document.createElement('div');
          title.className = 'wmeRcSettingTitle';
          title.textContent = def.label;
          meta.appendChild(title);


          const syncNativeChk = () => {
            try { selBox.classList.toggle('on', !!chk.checked); } catch {}
            try { row.classList.toggle('is-disabled', !chk.checked); } catch {}
          };

          const applyNativeChk = () => {
            cfg.hidden[def.id] = !chk.checked;
            state[group.id] = normalizeNativeMenuSettings(group.id, cfg);
            saveAllNativeMenuSettings(state);
            syncNativeChk();
          };

          chk.addEventListener('change', applyNativeChk);
          selBox.addEventListener('click', (ev) => {
            try { ev.preventDefault(); ev.stopPropagation(); } catch {}
            chk.checked = !chk.checked;
            applyNativeChk();
          });
          row.addEventListener('click', (ev) => {
            if (ev.target && ev.target.closest && ev.target.closest('.wmeRcNativeHandle')) return;
            chk.checked = !chk.checked;
            applyNativeChk();
          });

          left.appendChild(chk);
          left.appendChild(selBox);
          left.appendChild(meta);

          const handle = document.createElement('button');
          handle.type = 'button';
          handle.className = 'wmeRcNativeHandle';
          handle.innerHTML = `<span class="wmeRcI">${ICONS.drag || '≡'}</span>`;
          handle.title = 'Drag to reorder';
          if (!ICONS.drag) handle.textContent = '≡';

          row.appendChild(left);
          row.appendChild(handle);
          list.appendChild(row);
        });

        card.appendChild(list);
        sections.appendChild(card);
        if (!collapsed[group.id]) mountSortable(list, group.id, cfg, render);
      }
    }

    render();
    return wrap;
  }



  function isRcIosToggleDisabled(btn) {
    if (!btn) return false;
    try {
      return !!(
        btn.disabled ||
        btn.getAttribute('aria-disabled') === 'true' ||
        btn.classList.contains('is-disabled') ||
        btn.closest?.('.is-disabled,[aria-disabled="true"]')
      );
    } catch {
      return !!btn.disabled;
    }
  }

  function syncRcIosToggleAccent(btn) {
    if (!btn) return;
    try {
      const isDisabled = isRcIosToggleDisabled(btn);
      const isOn = btn.classList.contains('is-on') || btn.getAttribute('aria-pressed') === 'true';

      if (isDisabled) {
        btn.style.setProperty(
          'background',
          'var(--wmeRcCompactBorderStrong, rgba(120,120,128,.32))',
          'important'
        );
        btn.style.setProperty(
          'background-color',
          'var(--wmeRcCompactBorderStrong, rgba(120,120,128,.32))',
          'important'
        );
        btn.style.setProperty('background-image', 'none', 'important');
        btn.style.setProperty(
          'border-color',
          'var(--wmeRcCompactBorder, rgba(120,120,128,.24))',
          'important'
        );
        btn.style.setProperty('filter', 'none', 'important');
        btn.style.setProperty('opacity', '.55', 'important');
        btn.style.setProperty('transform', 'none', 'important');
        btn.style.setProperty('box-shadow', 'none', 'important');
        btn.style.setProperty('cursor', 'default', 'important');
        btn.setAttribute('data-rc-disabled-toggle', '1');
        return;
      }

      btn.removeAttribute('data-rc-disabled-toggle');
      btn.style.removeProperty('cursor');

      if (isOn) {
        btn.style.setProperty('background', '#0099ff', 'important');
        btn.style.setProperty('background-color', '#0099ff', 'important');
        btn.style.setProperty('background-image', 'none', 'important');
        btn.style.setProperty('border-color', '#0099ff', 'important');
        btn.style.setProperty('filter', 'none', 'important');
        btn.style.setProperty('opacity', '1', 'important');
        btn.style.setProperty('transform', 'none', 'important');
        btn.style.setProperty('box-shadow', 'none', 'important');
      } else {
        btn.style.removeProperty('background');
        btn.style.removeProperty('background-color');
        btn.style.removeProperty('background-image');
        btn.style.removeProperty('border-color');
        btn.style.removeProperty('filter');
        btn.style.removeProperty('opacity');
        btn.style.removeProperty('transform');
        btn.style.removeProperty('box-shadow');
      }
    } catch {}
  }

  const rcToggleLocalObservers = new WeakMap();

  function ensureRcToggleLocalObserver(btn) {
    if (!btn || rcToggleLocalObservers.has(btn) || typeof MutationObserver === 'undefined') return;
    try {
      const observer = new MutationObserver(() => {
        syncRcIosToggleAccent(btn);
      });
      observer.observe(btn, {
        attributes: true,
        attributeFilter: ['disabled', 'aria-disabled']
      });
      rcToggleLocalObservers.set(btn, observer);
    } catch {}
  }

  function syncAllRcToggleAccents(root = document) {
    try {
      root.querySelectorAll?.('button.wmeRcIosToggle').forEach((btn) => {
        ensureRcToggleLocalObserver(btn);
        syncRcIosToggleAccent(btn);
      });
    } catch {}
  }

  function runRcToggleCallbackAfterPaint(callback) {
    if (typeof callback !== 'function') return;

    const run = () => {
      setTimeout(() => {
        try {
          const result = callback();
          if (result && typeof result.catch === 'function') {
            result.catch(() => {});
          }
        } catch {}
      }, 0);
    };

    try {
      if (document.visibilityState === 'visible' && typeof requestAnimationFrame === 'function') {
        requestAnimationFrame(run);
      } else {
        run();
      }
    } catch {
      run();
    }
  }

  function createIosToggle(isOn, onToggle) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'wmeRcIosToggle' + (isOn ? ' is-on' : '');
    btn.setAttribute('aria-pressed', isOn ? 'true' : 'false');
    ensureRcToggleLocalObserver(btn);
    syncRcIosToggleAccent(btn);

    btn.addEventListener('click', (event) => {
      if (isRcIosToggleDisabled(btn)) {
        try { event.preventDefault(); event.stopPropagation(); } catch {}
        return;
      }

      const next = !btn.classList.contains('is-on');

      // Update the visible state synchronously, before any storage, network,
      // panel refresh or theme work can block the main thread.
      btn.classList.toggle('is-on', next);
      btn.setAttribute('aria-pressed', next ? 'true' : 'false');
      syncRcIosToggleAccent(btn);

      runRcToggleCallbackAfterPaint(() => onToggle?.(next, btn));
    });

    return btn;
  }

  let rcOptionInfoTooltip = null;
  let rcOptionInfoTooltipAnchor = null;
  let rcOptionInfoTooltipEventsBound = false;

  function hideRcOptionInfoTooltip() {
    rcOptionInfoTooltipAnchor = null;
    if (!rcOptionInfoTooltip) return;
    const tooltip = rcOptionInfoTooltip;
    rcOptionInfoTooltip = null;
    try { tooltip.classList.remove('is-visible'); } catch {}
    setTimeout(() => { try { tooltip.remove(); } catch {} }, 90);
  }

  function positionRcOptionInfoTooltip() {
    if (!rcOptionInfoTooltip || !rcOptionInfoTooltipAnchor) return;
    try {
      const anchorRect = rcOptionInfoTooltipAnchor.getBoundingClientRect();
      const tooltipRect = rcOptionInfoTooltip.getBoundingClientRect();
      const pad = 8;
      const vw = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
      const vh = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
      let left = anchorRect.left + (anchorRect.width / 2) - (tooltipRect.width / 2);
      left = Math.max(pad, Math.min(left, vw - pad - tooltipRect.width));
      let top = anchorRect.top - tooltipRect.height - 8;
      if (top < pad) top = anchorRect.bottom + 8;
      top = Math.max(pad, Math.min(top, vh - pad - tooltipRect.height));
      rcOptionInfoTooltip.style.left = `${Math.round(left)}px`;
      rcOptionInfoTooltip.style.top = `${Math.round(top)}px`;
    } catch {}
  }

  function isRcLightThemeForElement(anchor) {
    const explicitTheme = (el) => {
      if (!el) return "";
      try {
        const values = [
          el.getAttribute?.("wz-theme"),
          el.getAttribute?.("data-theme"),
          el.getAttribute?.("theme")
        ].map((value) => String(value || "").toLowerCase());
        if (values.includes("light")) return "light";
        if (values.includes("dark")) return "dark";
        if (el.classList?.contains("theme-light") || el.classList?.contains("wmeRcLight") || el.classList?.contains("light-theme")) return "light";
        if (el.classList?.contains("theme-dark") || el.classList?.contains("wmeRcDark") || el.classList?.contains("dark-theme")) return "dark";
      } catch {}
      return "";
    };

    try {
      let current = anchor?.closest?.(
        '.wmeRcModal,.wmeRcSideWrap,.wmeRcUserscriptControlPanel,.wmeRcDriveSettingsModal,.theme-light,.theme-dark,.wmeRcLight,.wmeRcDark'
      ) || anchor;
      let depth = 0;
      while (current && depth++ < 8) {
        const explicit = explicitTheme(current);
        if (explicit) return explicit === "light";
        try {
          const rgb = parseRgbColorForRc(getComputedStyle(current).backgroundColor);
          if (rgb && (rgb.a == null || rgb.a > 0.12)) {
            const luminance = (0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b) / 255;
            return luminance > 0.58;
          }
        } catch {}
        current = current.parentElement;
      }
    } catch {}

    try {
      for (const root of [document.documentElement, document.body]) {
        const explicit = explicitTheme(root);
        if (explicit) return explicit === "light";
      }
    } catch {}

    try { return detectAutoRcTheme() === "light"; } catch {}
    return false;
  }

  function showRcOptionInfoTooltip(anchor, text) {
    const message = String(text || '').trim();
    if (!anchor || !message) return;
    hideRcOptionInfoTooltip();

    const tooltip = document.createElement('div');
    tooltip.className = 'wmeRcPinSetInfoTooltip wmeRcOptionInfoTooltip windows-design';
    tooltip.textContent = message;
    tooltip.setAttribute('role', 'tooltip');

    try {
      const light = isRcLightThemeForElement(anchor);
      tooltip.classList.toggle('theme-light', light);
      tooltip.classList.toggle('theme-dark', !light);
      tooltip.dataset.rcTheme = light ? 'light' : 'dark';
    } catch {}

    rcOptionInfoTooltip = tooltip;
    rcOptionInfoTooltipAnchor = anchor;
    (document.body || document.documentElement).appendChild(tooltip);
    positionRcOptionInfoTooltip();
    requestAnimationFrame(() => {
      positionRcOptionInfoTooltip();
      try { tooltip.classList.add('is-visible'); } catch {}
    });

    if (!rcOptionInfoTooltipEventsBound) {
      rcOptionInfoTooltipEventsBound = true;
      window.addEventListener('resize', positionRcOptionInfoTooltip, true);
      window.addEventListener('scroll', positionRcOptionInfoTooltip, true);
      document.addEventListener('pointerdown', (ev) => {
        if (!rcOptionInfoTooltipAnchor) return;
        if (ev.target === rcOptionInfoTooltipAnchor || rcOptionInfoTooltipAnchor.contains?.(ev.target)) return;
        hideRcOptionInfoTooltip();
      }, true);
      document.addEventListener('keydown', (ev) => {
        if (ev.key === 'Escape') hideRcOptionInfoTooltip();
      }, true);
    }
  }

  function createRcOptionInfoButton(hint, { inline = false } = {}) {
    const message = String(hint || '').trim();
    if (!message) return null;

    const info = document.createElement(inline ? 'span' : 'button');
    if (!inline) info.type = 'button';
    else {
      info.tabIndex = 0;
      info.setAttribute('role', 'button');
    }

    info.className = 'wmeRcPinSetInfoBtn wmeRcOptionInfoBtn';
    info.textContent = '?';
    info.setAttribute('aria-label', message);
    info.title = '';

    const show = () => showRcOptionInfoTooltip(info, message);
    const stop = (ev) => {
      try { ev.preventDefault(); ev.stopPropagation(); } catch {}
    };

    info.addEventListener('mouseenter', show);
    info.addEventListener('mouseleave', hideRcOptionInfoTooltip);
    info.addEventListener('focus', show);
    info.addEventListener('blur', hideRcOptionInfoTooltip);
    info.addEventListener('click', stop);
    info.addEventListener('keydown', (ev) => {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      stop(ev);
      show();
    });
    return info;
  }

  function createRcOptionTitleRow(title, titleClassName, hint, { inlineInfo = false } = {}) {
    const row = document.createElement('div');
    row.className = 'wmeRcOptionTitleRow';

    const titleEl = document.createElement('div');
    titleEl.className = titleClassName;
    titleEl.textContent = title;
    row.appendChild(titleEl);

    const info = createRcOptionInfoButton(hint, { inline: inlineInfo });
    if (info) row.appendChild(info);
    return row;
  }


  /* -----------------------------------------------------------------------
   * RC Friends — Firebase Authentication + Firestore
   * -------------------------------------------------------------------- */

  let friendsFirebaseApp = null;
  let friendsAuth = null;
  let friendsDb = null;
  let friendsAuthUser = null;
  let friendsProfile = null;
  let friendsIncomingRequests = [];
  let friendsOutgoingRequests = [];
  let friendsAccepted = [];
  let friendsIncomingShares = [];
  let friendsListeners = [];
  let friendsInitPromise = null;
  let friendsConnectPromise = null;
  let friendsAuthTransitioning = false;
  let friendsAuthError = "";
  let friendsAuthErrorCode = "";
  let friendsFastOutgoingPollTimer = null;
  let friendsFastOutgoingPollUntil = 0;
  let friendsFastOutgoingPollRunning = false;
  let friendsQuotaNoticeShown = false;
  let friendsQuotaResumeTimer = null;
  let friendsQuotaStrikeCount = 0;
  let friendsNotificationDragging = false;
  let friendsDerivedGeneration = 0;
  let friendsDerivedRefreshTimer = null;
  let friendsRequestFallbackTimer = null;
  let friendsRequestFallbackRunning = false;
  let friendsUsesNativeFirebase = false;
  let friendsNotificationQueue = [];
  const friendsActiveNotifications = new Map();
  const friendsPinShareNotificationItems = new Map();
  const friendsPinShareSelectedIds = new Set();
  const friendsPinShareKnownIds = new Set();
  const friendsPinShareSelectedSenderKeys = new Set();
  const friendsPinShareKnownSenderKeys = new Set();
  let friendsPinShareNotification = null;
  let friendsNotificationPositionTimer = null;
  const friendsUiSubscribers = new Set();
  const friendsProfileCache = new Map();
  const FRIENDS_MUTATION_GUARD_MS = 12000;
  const friendsRequestUpsertGuards = new Map();
  const friendsRequestStatusGuards = new Map();
  const friendsRequestDeleteGuards = new Map();
  const friendsShareStatusGuards = new Map();

  let friendsRestCompat = null;
  let friendsRestCompatBindingKey = "";
  let friendsActiveWmeBindingKey = "";
  let friendsIdentityWatcherTimer = null;
  let friendsIdentityResetPromise = null;
  let friendsMissingIdentityChecks = 0;
  let friendsIdentityGeneration = 0;

  let friendsRealtimeBridge = null;
  let friendsRealtimeInstalled = false;
  let friendsRealtimeBackendReady = false;
  let friendsRealtimeActive = false;
  let friendsRealtimeVersion = "";
  let friendsRealtimeBindingKey = "";
  let friendsRealtimeConfigureTimer = null;
  let friendsRealtimeSignalPollTimer = null;
  let friendsRealtimeSignalPollRunning = false;
  let friendsRealtimeSignalLastNonce = "";
  let friendsRealtimeSignalTargetId = "";
  let friendsRealtimeHealthTimer = null;

  function makeFriendsRealtimeError(message, code = "friends/realtime-extension-error") {
    const error = new Error(String(message || "Friends realtime extension error."));
    error.code = String(code || "friends/realtime-extension-error");
    return error;
  }

  let friendsRealtimeRefreshRetryTimer = null;

  function currentFriendsRealtimeTargetId(identity = readCurrentWmeIdentity()) {
    return String(
      friendsProfile?.wmeUserId ||
      identity?.userId ||
      friendsProfile?.uid ||
      ""
    ).trim();
  }

  async function pollFriendsRealtimeSignal({ forceRefresh = false } = {}) {
    if (friendsRealtimeSignalPollRunning || document.hidden || !friendsDb) return false;
    const targetId = currentFriendsRealtimeTargetId();
    if (!targetId) return false;

    friendsRealtimeSignalPollRunning = true;
    try {
      const snapshot = await friendsDb
        .collection(FRIENDS_REALTIME_SIGNAL_COLLECTION)
        .doc(friendsRealtimeSignalDocId(targetId))
        .get();
      const data = snapshot?.exists ? (snapshot.data?.() || {}) : {};
      const nonce = String(data?.nonce || "");
      const targetChanged = friendsRealtimeSignalTargetId !== targetId;
      const nonceChanged = !!nonce && !!friendsRealtimeSignalLastNonce && nonce !== friendsRealtimeSignalLastNonce;

      friendsRealtimeSignalTargetId = targetId;
      if (nonce) friendsRealtimeSignalLastNonce = nonce;
      if (forceRefresh || targetChanged || nonceChanged) triggerFriendsRealtimeRefresh();
      return true;
    } catch (error) {
      try { console.warn(`${SCRIPT_NAME}: Friends realtime fallback check failed`, error); } catch {}
      return false;
    } finally {
      friendsRealtimeSignalPollRunning = false;
    }
  }

  function updateFriendsRealtimeSignalFallback() {
    if (friendsRealtimeSignalPollTimer) {
      clearInterval(friendsRealtimeSignalPollTimer);
      friendsRealtimeSignalPollTimer = null;
    }
    if (friendsRealtimeActive) return;

    pollFriendsRealtimeSignal({ forceRefresh: false }).catch(() => {});
    friendsRealtimeSignalPollTimer = setInterval(() => {
      if (friendsRealtimeActive || document.hidden) return;
      pollFriendsRealtimeSignal().catch(() => {});
    }, FRIENDS_REALTIME_SIGNAL_FALLBACK_MS);
  }

  function ensureFriendsRealtimeHealthMonitor() {
    if (friendsRealtimeHealthTimer) return;
    friendsRealtimeHealthTimer = setInterval(() => {
      if (document.hidden) return;
      const identity = readCurrentWmeIdentity();
      configureFriendsRealtimeExtension(identity, { force: true })
        .then(() => updateFriendsRealtimeSignalFallback())
        .catch(() => {
          friendsRealtimeActive = false;
          friendsRealtimeBindingKey = "";
          updateFriendsRealtimeSignalFallback();
        });
    }, FRIENDS_REALTIME_HEALTHCHECK_MS);
  }

  function triggerFriendsRealtimeRefresh() {
    const refresh = () => {
      try { friendsDb?.refreshAllQueries?.(); } catch {}
    };

    // Refresh immediately when the extension reports a Firestore change, then
    // repeat once after the write has fully settled. This is event-driven and
    // does not introduce background polling.
    refresh();
    if (friendsRealtimeRefreshRetryTimer) {
      clearTimeout(friendsRealtimeRefreshRetryTimer);
    }
    friendsRealtimeRefreshRetryTimer = setTimeout(() => {
      friendsRealtimeRefreshRetryTimer = null;
      refresh();
    }, 1400);
  }

  function scheduleFriendsRealtimeConfigure(delay = 120) {
    if (friendsRealtimeConfigureTimer) clearTimeout(friendsRealtimeConfigureTimer);
    friendsRealtimeConfigureTimer = setTimeout(() => {
      friendsRealtimeConfigureTimer = null;
      configureFriendsRealtimeExtension(readCurrentWmeIdentity()).catch(() => {});
    }, Math.max(0, Number(delay) || 0));
  }

  function createFriendsRealtimeBridge() {
    if (friendsRealtimeBridge) return friendsRealtimeBridge;

    const pending = new Map();
    let sequence = 0;

    const handleEnvelope = (data) => {
      if (!data || data.channel !== FRIENDS_REALTIME_CHANNEL || data.direction !== "from-extension") return;

      if (data.kind === "content-ready") {
        friendsRealtimeInstalled = true;
        friendsRealtimeVersion = String(data.version || friendsRealtimeVersion || "");
        return;
      }
      if (data.kind === "backend-ready") {
        friendsRealtimeInstalled = true;
        friendsRealtimeBackendReady = true;
        friendsRealtimeVersion = String(data.version || data.payload?.extensionVersion || friendsRealtimeVersion || "");
        scheduleFriendsRealtimeConfigure();
        return;
      }
      if (data.kind === "backend-error" || data.kind === "disconnected") {
        friendsRealtimeInstalled = true;
        friendsRealtimeBackendReady = false;
        friendsRealtimeActive = false;
        friendsRealtimeBindingKey = "";
        updateFriendsRealtimeSignalFallback();
        return;
      }

      const message = data.message || {};
      if (message.kind === "event") {
        const eventName = String(message.event || "");
        if (eventName === "realtime-ready") {
          friendsRealtimeActive = true;
          updateFriendsRealtimeSignalFallback();
          triggerFriendsRealtimeRefresh();
        } else if (eventName === "realtime-change") {
          friendsRealtimeActive = true;
          updateFriendsRealtimeSignalFallback();
          triggerFriendsRealtimeRefresh();
        } else if (eventName === "realtime-error") {
          friendsRealtimeActive = false;
          updateFriendsRealtimeSignalFallback();
          try { console.warn(`${SCRIPT_NAME}: Friends realtime listener error`, message.payload || {}); } catch {}
        }
        return;
      }
      if (message.kind !== "response") return;

      const requestId = String(message.requestId || "");
      const entry = pending.get(requestId);
      if (!entry) return;
      pending.delete(requestId);
      try { clearTimeout(entry.timer); } catch {}
      if (message.ok) entry.resolve(message.payload || {});
      else entry.reject(makeFriendsRealtimeError(message.error?.message, message.error?.code));
    };

    window.addEventListener("message", (event) => {
      if (event.source && event.source !== window) return;
      handleEnvelope(event.data);
    }, false);
    document.addEventListener(FRIENDS_REALTIME_RESPONSE_EVENT, (event) => {
      try {
        handleEnvelope(typeof event.detail === "string" ? JSON.parse(event.detail) : event.detail);
      } catch {}
    }, false);

    const request = (action, payload = {}, timeoutMs = 10000) => new Promise((resolve, reject) => {
      const requestId = `${Date.now().toString(36)}:${(++sequence).toString(36)}:${Math.random().toString(36).slice(2, 8)}`;
      const timer = setTimeout(() => {
        pending.delete(requestId);
        reject(makeFriendsRealtimeError(
          action === "ping"
            ? "WME Friends realtime extension is not installed or not responding."
            : "The Friends realtime extension request timed out.",
          action === "ping" ? "friends/realtime-extension-required" : "friends/realtime-extension-timeout"
        ));
      }, Math.max(800, Number(timeoutMs) || 10000));
      pending.set(requestId, { resolve, reject, timer });

      const envelope = {
        channel: FRIENDS_REALTIME_CHANNEL,
        direction: "to-extension",
        message: { requestId, action, payload }
      };
      const hasDomBridge = !!document.documentElement?.getAttribute?.(FRIENDS_REALTIME_MARKER_ATTR);
      if (hasDomBridge) {
        try {
          document.dispatchEvent(new CustomEvent(FRIENDS_REALTIME_REQUEST_EVENT, {
            detail: JSON.stringify(envelope)
          }));
        } catch {}
      } else {
        try { window.postMessage(envelope, "*"); } catch {}
      }
    });

    friendsRealtimeBridge = { request };
    return friendsRealtimeBridge;
  }

  async function configureFriendsRealtimeExtension(identity = readCurrentWmeIdentity(), options = {}) {
    const force = !!options?.force;
    const normalizedUsername = normalizeFriendsUsername(identity?.username || "");
    const bindingKey = String(
      identity?.bindingKey ||
      (identity?.userId ? `wme-id:${identity.userId}` : "")
    );
    const signalTargetId = currentFriendsRealtimeTargetId(identity);
    const configureKey = signalTargetId ? `${bindingKey}::${signalTargetId}` : "";
    if (!bindingKey || !normalizedUsername || !signalTargetId) return false;
    if (!force && friendsRealtimeActive && friendsRealtimeBindingKey === configureKey) return true;

    const root = document.documentElement;
    const markerVersion = String(root?.getAttribute?.(FRIENDS_REALTIME_MARKER_ATTR) || "").trim();
    const markerBackend = String(root?.getAttribute?.(FRIENDS_REALTIME_BACKEND_ATTR) || "").trim();
    if (markerVersion) {
      friendsRealtimeInstalled = true;
      friendsRealtimeVersion = markerVersion;
      if (markerBackend === "ready") friendsRealtimeBackendReady = true;
    }

    const bridge = createFriendsRealtimeBridge();
    const ping = await bridge.request("ping", {}, 3500);
    friendsRealtimeInstalled = true;
    friendsRealtimeBackendReady = true;
    friendsRealtimeVersion = String(ping?.extensionVersion || friendsRealtimeVersion || "");

    const result = await bridge.request("configureIdentity", {
      wmeUsername: String(identity?.username || "").trim(),
      wmeUsernameNormalized: normalizedUsername,
      wmeUserId: signalTargetId,
      signalTargetId,
      wmeBindingKey: bindingKey,
      // Kept for extension v1.0.0 compatibility. It now intentionally carries
      // the canonical WME ID rather than a Firebase anonymous UID.
      friendsUid: signalTargetId
    }, 15000);
    friendsRealtimeBindingKey = configureKey;
    friendsRealtimeActive = result?.active !== false;
    updateFriendsRealtimeSignalFallback();
    ensureFriendsRealtimeHealthMonitor();
    if (friendsRealtimeActive) triggerFriendsRealtimeRefresh();
    return friendsRealtimeActive;
  }

  function friendsRealtimeSignalDocId(uid) {
    return encodeURIComponent(String(uid || "").trim());
  }

  async function signalFriendsRealtimeChange(targetUid, eventType = "friends-change") {
    const uid = String(targetUid || "").trim();
    if (!uid || !friendsDb) return false;

    try {
      await friendsDb.collection(FRIENDS_REALTIME_SIGNAL_COLLECTION)
        .doc(friendsRealtimeSignalDocId(uid))
        .set({
          targetUid: uid,
          eventType: String(eventType || "friends-change").slice(0, 48),
          nonce: `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`,
          updatedAt: friendsServerTimestamp()
        }, { merge: true });
      return true;
    } catch (error) {
      try { console.warn(`${SCRIPT_NAME}: Could not send Friends realtime signal`, error); } catch {}
      return false;
    }
  }

  function friendsOtherRequestUid(request, ownUid = friendsOwnWmeId()) {
    const me = String(ownUid || "");
    const fromUid = String(request?.fromUid || "");
    const toUid = String(request?.toUid || "");
    if (fromUid && fromUid !== me) return fromUid;
    if (toUid && toUid !== me) return toUid;
    return "";
  }

  function friendsGmRequest({ method = "GET", url, headers = {}, body = null, timeout = 30000 }) {
    return new Promise((resolve, reject) => {
      let settled = false;
      const fail = (message, code = "friends/network-request-failed", details = null) => {
        if (settled) return;
        settled = true;
        const error = new Error(message || "Firebase request failed.");
        error.code = code;
        error.details = details;
        reject(error);
      };

      try {
        GM_xmlhttpRequest({
          method,
          url,
          headers,
          data: body == null
            ? undefined
            : (typeof body === "string" ? body : JSON.stringify(body)),
          timeout,
          anonymous: false,
          onload: (response) => {
            if (settled) return;
            let parsed = null;
            try {
              parsed = response.responseText ? JSON.parse(response.responseText) : null;
            } catch {}

            if (response.status >= 200 && response.status < 300) {
              settled = true;
              resolve(parsed);
              return;
            }

            const serverMessage =
              parsed?.error?.message ||
              parsed?.error?.status ||
              parsed?.message ||
              `HTTP ${response.status}`;
            const normalizedCode = String(serverMessage || "")
              .trim()
              .toLowerCase()
              .replace(/[^a-z0-9]+/g, "-")
              .replace(/^-+|-+$/g, "");
            fail(
              String(serverMessage || "Firebase request failed."),
              normalizedCode ? `firebase/${normalizedCode}` : "friends/http-error",
              { status: response.status, response: parsed }
            );
          },
          onerror: () => fail("Firebase could not be reached.", "friends/network-request-failed"),
          ontimeout: () => fail("Firebase request timed out.", "friends/network-timeout"),
          onabort: () => fail("Firebase request was cancelled.", "friends/request-aborted")
        });
      } catch (error) {
        fail(error?.message || "Firebase request failed.", "friends/network-request-failed", error);
      }
    });
  }

  function friendsRestAuthStorageKey(identity = readCurrentWmeIdentity()) {
    const bindingKey = String(identity?.bindingKey || "").trim();
    if (!bindingKey) return "";
    return `${FRIENDS_WME_AUTH_PREFIX}:${encodeURIComponent(bindingKey)}`;
  }

  function friendsReadRestAuth(identity = readCurrentWmeIdentity()) {
    try {
      const storageKey = friendsRestAuthStorageKey(identity);
      if (!storageKey) return null;
      const raw = GM_getValue(storageKey, "");
      if (!raw) return null;
      const value = typeof raw === "string" ? JSON.parse(raw) : raw;
      if (!value || typeof value !== "object") return null;
      if (
        value.wmeBindingKey &&
        String(value.wmeBindingKey) !== String(identity?.bindingKey || "")
      ) return null;
      return value;
    } catch {
      return null;
    }
  }

  function friendsWriteRestAuth(value, identity = readCurrentWmeIdentity()) {
    try {
      const storageKey = friendsRestAuthStorageKey(identity);
      if (!storageKey) return;
      const storedValue = value ? {
        ...value,
        wmeBindingKey: String(identity?.bindingKey || ""),
        wmeUserId: String(identity?.userId || ""),
        wmeUsernameNormalized: normalizeFriendsUsername(identity?.username || "")
      } : null;
      GM_setValue(storageKey, storedValue ? JSON.stringify(storedValue) : "");
    } catch {}
  }

  function clearLegacyFriendsAuthOnce() {
    try {
      if (GM_getValue(FRIENDS_LEGACY_AUTH_CLEARED_KEY, "") === "1") return;
      GM_setValue(FRIENDS_REST_AUTH_KEY, "");
      GM_setValue(FRIENDS_LEGACY_AUTH_CLEARED_KEY, "1");
    } catch {}
  }

  function createFriendsRestCompat(identity = readCurrentWmeIdentity()) {
    const bindingKey = String(identity?.bindingKey || "").trim();
    if (!bindingKey) {
      throw makeFriendsError("WME identity is not available yet.", "friends/wme-identity-missing");
    }
    if (friendsRestCompat && friendsRestCompatBindingKey === bindingKey) {
      return friendsRestCompat;
    }

    friendsRestCompatBindingKey = bindingKey;
    const config = FRIENDS_FIREBASE_CONFIG;
    const projectId = encodeURIComponent(config.projectId);
    const databaseRoot =
      `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents`;

    let authState = friendsReadRestAuth(identity);
    let authUser = null;
    const authListeners = new Set();
    const queryRefreshers = new Set();
    const apps = [];

    const makeUser = (state) => {
      if (!state?.localId) return null;
      return {
        uid: String(state.localId),
        isAnonymous: true,
        providerId: "anonymous",
        async getIdToken(forceRefresh = false) {
          const current = await ensureAuthToken(forceRefresh);
          return current.idToken;
        }
      };
    };

    authUser = makeUser(authState);

    const notifyAuth = () => {
      authUser = makeUser(authState);
      for (const listener of Array.from(authListeners)) {
        try { listener(authUser); } catch {}
      }
    };

    const saveAuthResponse = (payload, previous = null) => {
      const expiresSeconds = Math.max(60, Number(payload?.expiresIn || payload?.expires_in || 3600));
      authState = {
        localId: String(payload?.localId || payload?.user_id || previous?.localId || ""),
        idToken: String(payload?.idToken || payload?.id_token || ""),
        refreshToken: String(payload?.refreshToken || payload?.refresh_token || previous?.refreshToken || ""),
        expiresAt: Date.now() + expiresSeconds * 1000 - 60000,
        providerId: "anonymous",
        isAnonymous: true
      };
      if (!authState.localId || !authState.idToken || !authState.refreshToken) {
        throw new Error("Firebase returned incomplete authentication data.");
      }
      friendsWriteRestAuth(authState, identity);
      notifyAuth();
      return authState;
    };

    const refreshAuthToken = async () => {
      if (!authState?.refreshToken) throw new Error("Friends is not connected.");
      const body = new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: authState.refreshToken
      }).toString();

      const payload = await friendsGmRequest({
        method: "POST",
        url: `https://securetoken.googleapis.com/v1/token?key=${encodeURIComponent(config.apiKey)}`,
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body
      });
      return saveAuthResponse(payload, authState);
    };

    const ensureAuthToken = async (forceRefresh = false) => {
      if (!authState?.localId) throw new Error("Friends is not connected.");
      if (
        forceRefresh ||
        !authState.idToken ||
        !Number.isFinite(Number(authState.expiresAt)) ||
        Number(authState.expiresAt) <= Date.now()
      ) {
        return refreshAuthToken();
      }
      return authState;
    };

    const signInAnonymously = async () => {
      const payload = await friendsGmRequest({
        method: "POST",
        url:
          `https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=` +
          encodeURIComponent(config.apiKey),
        headers: { "Content-Type": "application/json" },
        body: { returnSecureToken: true }
      });
      saveAuthResponse(payload, null);
      return { user: authUser };
    };

    const auth = {
      get currentUser() {
        return authUser;
      },
      setPersistence() {
        return Promise.resolve();
      },
      onAuthStateChanged(callback) {
        authListeners.add(callback);
        queueMicrotask(() => {
          try { callback(authUser); } catch {}
        });
        return () => authListeners.delete(callback);
      },
      signInAnonymously,
      async signOut() {
        authState = null;
        friendsWriteRestAuth(null, identity);
        notifyAuth();
      }
    };

    function encodeFirestoreValue(value) {
      if (value && value.__friendsServerTimestamp === true) {
        return { timestampValue: new Date().toISOString() };
      }
      if (value instanceof Date) return { timestampValue: value.toISOString() };
      if (value === null || value === undefined) return { nullValue: null };
      if (typeof value === "boolean") return { booleanValue: value };
      if (typeof value === "number") {
        return Number.isInteger(value)
          ? { integerValue: String(value) }
          : { doubleValue: value };
      }
      if (typeof value === "string") return { stringValue: value };
      if (Array.isArray(value)) {
        return { arrayValue: { values: value.map(encodeFirestoreValue) } };
      }
      if (typeof value === "object") {
        const fields = {};
        for (const [key, child] of Object.entries(value)) {
          if (child === undefined) continue;
          fields[key] = encodeFirestoreValue(child);
        }
        return { mapValue: { fields } };
      }
      return { stringValue: String(value) };
    }

    function decodeFirestoreValue(value) {
      if (!value || typeof value !== "object") return null;
      if ("nullValue" in value) return null;
      if ("booleanValue" in value) return !!value.booleanValue;
      if ("integerValue" in value) return Number(value.integerValue);
      if ("doubleValue" in value) return Number(value.doubleValue);
      if ("timestampValue" in value) return new Date(value.timestampValue);
      if ("stringValue" in value) return String(value.stringValue);
      if ("arrayValue" in value) {
        return (value.arrayValue?.values || []).map(decodeFirestoreValue);
      }
      if ("mapValue" in value) return decodeFirestoreFields(value.mapValue?.fields || {});
      return null;
    }

    function encodeFirestoreFields(data) {
      const fields = {};
      for (const [key, value] of Object.entries(data || {})) {
        if (value === undefined) continue;
        fields[key] = encodeFirestoreValue(value);
      }
      return fields;
    }

    function decodeFirestoreFields(fields) {
      const data = {};
      for (const [key, value] of Object.entries(fields || {})) {
        data[key] = decodeFirestoreValue(value);
      }
      return data;
    }

    function encodePath(path) {
      return String(path || "")
        .split("/")
        .filter(Boolean)
        .map((segment) => encodeURIComponent(segment))
        .join("/");
    }

    function documentIdFromName(name) {
      const parts = String(name || "").split("/");
      return decodeURIComponent(parts[parts.length - 1] || "");
    }

    function makeDocumentSnapshot(path, document = null) {
      const id = document ? documentIdFromName(document.name) : String(path).split("/").pop();
      const data = document ? decodeFirestoreFields(document.fields || {}) : null;
      return {
        id,
        exists: !!document,
        data() {
          return data;
        }
      };
    }

    async function firestoreRequest({ method = "GET", suffix = "", body = null, query = "" }) {
      const quotaBackoffUntil = getFriendsQuotaBackoffUntil();
      if (quotaBackoffUntil > Date.now()) {
        const error = new Error("Friends is temporarily paused while the shared Firebase quota cools down.");
        error.code = "friends/quota-backoff";
        error.details = { status: 429, backoffUntil: quotaBackoffUntil };
        throw error;
      }

      const token = await ensureAuthToken(false);
      const separator = query ? `?${query}` : "";
      try {
        return await friendsGmRequest({
          method,
          url: `${databaseRoot}${suffix}${separator}`,
          headers: {
            "Authorization": `Bearer ${token.idToken}`,
            "Content-Type": "application/json"
          },
          body
        });
      } catch (error) {
        const message = String(error?.message || "");
        if (/UNAUTHENTICATED|INVALID_ID_TOKEN|TOKEN_EXPIRED/i.test(message)) {
          const refreshed = await ensureAuthToken(true);
          return friendsGmRequest({
            method,
            url: `${databaseRoot}${suffix}${separator}`,
            headers: {
              "Authorization": `Bearer ${refreshed.idToken}`,
              "Content-Type": "application/json"
            },
            body
          });
        }
        throw error;
      }
    }

    let refreshAllQueriesTimer = null;
    const refreshAllQueries = () => {
      // Coalesce bursts of writes (especially sending several selected pins)
      // into one refresh instead of re-running every query after each write.
      if (refreshAllQueriesTimer) clearTimeout(refreshAllQueriesTimer);
      refreshAllQueriesTimer = setTimeout(() => {
        refreshAllQueriesTimer = null;
        if (getFriendsQuotaBackoffUntil() > Date.now()) return;
        for (const refresh of Array.from(queryRefreshers)) {
          try { refresh(); } catch {}
        }
      }, 750);
    };

    class RestDocumentReference {
      constructor(path) {
        this.path = String(path || "").replace(/^\/+|\/+$/g, "");
        this.id = this.path.split("/").pop() || "";
      }

      async get() {
        try {
          const document = await firestoreRequest({
            suffix: `/${encodePath(this.path)}`
          });
          return makeDocumentSnapshot(this.path, document);
        } catch (error) {
          const message = String(error?.message || "");
          const status = Number(error?.details?.status || 0);
          const serverStatus = String(
            error?.details?.response?.error?.status ||
            error?.details?.response?.status ||
            ""
          );

          // A missing Firestore document is normal during first-time profile
          // registration and exact username lookup. Return exists=false just
          // like the Firebase SDK instead of surfacing it as an error.
          if (
            status === 404 ||
            serverStatus === "NOT_FOUND" ||
            /\bnot[\s_-]*found\b|HTTP\s*404/i.test(message)
          ) {
            return makeDocumentSnapshot(this.path, null);
          }
          throw error;
        }
      }

      async set(data) {
        await firestoreRequest({
          method: "PATCH",
          suffix: `/${encodePath(this.path)}`,
          body: { fields: encodeFirestoreFields(data) }
        });
        refreshAllQueries();
      }

      async update(data) {
        const keys = Object.keys(data || {});
        const params = new URLSearchParams();
        for (const key of keys) params.append("updateMask.fieldPaths", key);
        await firestoreRequest({
          method: "PATCH",
          suffix: `/${encodePath(this.path)}`,
          query: params.toString(),
          body: { fields: encodeFirestoreFields(data) }
        });
        refreshAllQueries();
      }

      async delete() {
        await firestoreRequest({
          method: "DELETE",
          suffix: `/${encodePath(this.path)}`
        });
        refreshAllQueries();
      }
    }

    class RestQuery {
      constructor(collectionPath, field = "", op = "==", value = null) {
        this.collectionPath = collectionPath;
        this.field = field;
        this.op = op;
        this.value = value;
      }

      async get() {
        const collectionParts = this.collectionPath.split("/").filter(Boolean);
        const collectionId = collectionParts.pop();
        const parentPath = collectionParts.join("/");
        const structuredQuery = {
          from: [{ collectionId }]
        };

        if (this.field) {
          structuredQuery.where = {
            fieldFilter: {
              field: { fieldPath: this.field },
              op: this.op === "==" ? "EQUAL" : "EQUAL",
              value: encodeFirestoreValue(this.value)
            }
          };
        }

        const response = await firestoreRequest({
          method: "POST",
          suffix: `${parentPath ? `/${encodePath(parentPath)}` : ""}:runQuery`,
          body: { structuredQuery }
        });

        const documents = (Array.isArray(response) ? response : [])
          .map((entry) => entry?.document)
          .filter(Boolean);

        return {
          docs: documents.map((document) =>
            makeDocumentSnapshot(`${this.collectionPath}/${documentIdFromName(document.name)}`, document)
          )
        };
      }

      onSnapshot(onNext, onError) {
        let stopped = false;
        let running = false;
        let rerunRequested = false;
        let timer = null;

        const refresh = async () => {
          if (stopped) return;
          if (running) {
            // A realtime event can arrive while the REST query is still in
            // flight. Remember it instead of dropping the only refresh signal.
            rerunRequested = true;
            return;
          }
          if (getFriendsQuotaBackoffUntil() > Date.now()) return;
          running = true;
          try {
            const snapshot = await this.get();
            if (!stopped) onNext(snapshot);
          } catch (error) {
            if (!stopped && onError) onError(error);
          } finally {
            running = false;
            if (!stopped && rerunRequested) {
              rerunRequested = false;
              queueMicrotask(() => refresh());
            }
          }
        };

        queryRefreshers.add(refresh);
        refresh();

        timer = setInterval(() => {
          if (document.hidden || friendsRealtimeActive) return;
          refresh();
        }, FRIENDS_POLL_INTERVAL_MS);

        return () => {
          stopped = true;
          if (timer) clearInterval(timer);
          queryRefreshers.delete(refresh);
        };
      }
    }

    if (!window.__wmeRcFriendsFocusRefreshBound) {
      window.__wmeRcFriendsFocusRefreshBound = true;
      let lastFallbackFocusRefresh = 0;
      const healRealtime = () => {
        scheduleFriendsRealtimeConfigure(0);
        if (!friendsRealtimeActive) pollFriendsRealtimeSignal({ forceRefresh: true }).catch(() => {});
      };
      window.addEventListener("focus", () => {
        healRealtime();
        if (friendsRealtimeActive) return;
        if (getFriendsQuotaBackoffUntil() > Date.now()) return;
        if (Date.now() - lastFallbackFocusRefresh < FRIENDS_POLL_INTERVAL_MS) return;
        lastFallbackFocusRefresh = Date.now();
        for (const refresh of Array.from(queryRefreshers)) {
          try { refresh(); } catch {}
        }
      }, true);
      document.addEventListener("visibilitychange", () => {
        if (!document.hidden) healRealtime();
      }, true);
      window.addEventListener("pageshow", healRealtime, true);
    }

    class RestCollectionReference {
      constructor(path) {
        this.path = String(path || "").replace(/^\/+|\/+$/g, "");
      }

      doc(id = "") {
        const documentId = String(id || "").trim() ||
          `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`;
        return new RestDocumentReference(`${this.path}/${documentId}`);
      }

      where(field, op, value) {
        return new RestQuery(this.path, field, op, value);
      }

      get() {
        return new RestQuery(this.path).get();
      }
    }

    const db = {
      refreshAllQueries,
      collection(path) {
        return new RestCollectionReference(path);
      },
      batch() {
        const writes = [];
        return {
          delete(reference) {
            const path = String(reference?.path || "").replace(/^\/+|\/+$/g, "");
            if (!path) return;
            writes.push({
              delete: `projects/${config.projectId}/databases/(default)/documents/${path}`
            });
          },
          async commit() {
            if (!writes.length) return;
            await firestoreRequest({
              method: "POST",
              suffix: ":commit",
              body: { writes }
            });
            refreshAllQueries();
          }
        };
      },
      async runTransaction(callback) {
        const writes = [];
        const tx = {
          get(reference) {
            return reference.get();
          },
          set(reference, data) {
            writes.push(() => reference.set(data));
          },
          delete(reference) {
            writes.push(() => reference.delete());
          }
        };
        const result = await callback(tx);
        for (const write of writes) await write();
        return result;
      }
    };

    const app = {
      name: FRIENDS_FIREBASE_APP_NAME,
      auth() {
        return auth;
      },
      firestore() {
        return db;
      }
    };
    apps.push(app);

    const authFactory = () => auth;
    authFactory.Auth = { Persistence: { LOCAL: "local" } };

    const firestoreFactory = () => db;
    firestoreFactory.FieldValue = {
      serverTimestamp() {
        return { __friendsServerTimestamp: true };
      }
    };

    friendsRestCompat = {
      apps,
      initializeApp() {
        return app;
      },
      auth: authFactory,
      firestore: firestoreFactory
    };
    return friendsRestCompat;
  }

  function getFirebaseCompatGlobal() {
    return createFriendsRestCompat(readCurrentWmeIdentity());
  }

  function normalizeFriendsUsername(value) {
    try {
      return String(value || "")
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .trim()
        .toLowerCase();
    } catch {
      return String(value || "").trim().toLowerCase();
    }
  }

  function friendsUsernameDocKey(value) {
    return encodeURIComponent(normalizeFriendsUsername(value)).replace(/\//g, "%2F");
  }

  function readCurrentWmeUsername() {
    const values = [];
    const add = (value) => {
      const text = String(value || "").trim();
      if (text && !values.includes(text)) values.push(text);
    };

    try {
      const user = UW?.W?.loginManager?.user;
      add(user?.getUserName?.());
      add(user?.getUsername?.());
      add(user?.userName);
      add(user?.username);
      add(user?.name);
      add(user?.attributes?.userName);
      add(user?.attributes?.username);
      add(user?.attributes?.name);
    } catch {}

    try {
      const info = sdk?.State?.userInfo || sdk?.UserSession?.getUserInfo?.() || sdk?.WmeState?.getUserInfo?.();
      add(info?.userName);
      add(info?.username);
      add(info?.name);
    } catch {}

    return values[0] || "";
  }

  function normalizeWmeAvatarUrl(value) {
    if (value && typeof value === "object") {
      value = value.url || value.src || value.href || value.imageUrl || value.avatarUrl || "";
    }
    if (typeof value !== "string") return "";
    let text = value.trim();
    if (!text || text === "[object Object]") return "";
    if (text.startsWith("//")) text = `${location.protocol}${text}`;
    try {
      const url = new URL(text, location.href);
      if (!/^https?:$/i.test(url.protocol)) return "";
      const normalized = url.href;
      return normalized.length <= 2048 ? normalized : "";
    } catch {
      return "";
    }
  }

  function improveWmeAvatarUrl(value, preferredSize = 256) {
    const normalized = normalizeWmeAvatarUrl(value);
    if (!normalized) return "";

    const size = Math.max(96, Math.min(512, Number(preferredSize) || 256));
    try {
      const url = new URL(normalized);
      const host = String(url.hostname || "").toLowerCase();
      const isGoogleImageHost =
        host.endsWith("googleusercontent.com") ||
        host.endsWith("ggpht.com") ||
        host.endsWith("google.com");

      // WME profile photos are commonly served by Google image hosts with a
      // trailing size transform such as =s32-c. Request a larger source so the
      // browser is not stretching a tiny thumbnail inside the Friends panel.
      if (isGoogleImageHost) {
        const upgradedHref = url.href.replace(
          /=s\d+(?:-c)?(?:-[a-z0-9-]+)?(?=\?|#|$)/i,
          `=s${size}-c`
        );
        if (upgradedHref !== url.href) return upgradedHref;

        url.pathname = url.pathname
          .replace(/\/s\d+(?:-c)?\//i, `/s${size}-c/`)
          .replace(/\/w\d+-h\d+(?:-c)?\//i, `/w${size}-h${size}-c/`);
      }

      // Only rewrite dimensions that the source URL already exposes. This
      // avoids inventing parameters on signed or non-resizable avatar URLs.
      for (const key of ["sz", "size", "width", "height", "w", "h"]) {
        if (url.searchParams.has(key)) url.searchParams.set(key, String(size));
      }

      const upgraded = url.href;
      return upgraded.length <= 2048 ? upgraded : normalized;
    } catch {
      return normalized;
    }
  }

  function readCurrentWmeAvatarUrl() {
    const candidates = [];
    const add = (value) => {
      const url = improveWmeAvatarUrl(value);
      if (url && !candidates.includes(url)) candidates.push(url);
    };
    const addSrcset = (value) => {
      const entries = String(value || "")
        .split(",")
        .map((entry) => entry.trim())
        .filter(Boolean)
        .map((entry) => {
          const match = entry.match(/^(.*?)(?:\s+(\d+(?:\.\d+)?)(w|x))?$/i);
          return {
            url: match?.[1]?.trim() || "",
            score: Number(match?.[2] || 1) * (match?.[3]?.toLowerCase() === "x" ? 1000 : 1)
          };
        })
        .sort((a, b) => b.score - a.score);
      if (entries[0]?.url) add(entries[0].url);
    };
    const inspectObject = (obj) => {
      if (!obj) return;
      for (const key of [
        "wmeAvatarUrl", "avatarUrl", "avatarURL", "avatar", "photoURL",
        "photoUrl", "picture", "profileImage", "profileImageUrl", "imageUrl", "imageURL"
      ]) {
        try { add(obj?.[key]); } catch {}
        try { add(obj?.attributes?.[key]); } catch {}
      }
      for (const method of [
        "getAvatarUrl", "getAvatarURL", "getAvatar", "getPhotoUrl",
        "getPhotoURL", "getPicture", "getProfileImageUrl"
      ]) {
        try {
          if (typeof obj?.[method] === "function") add(obj[method]());
        } catch {}
      }
    };

    try { inspectObject(UW?.W?.loginManager?.user); } catch {}
    try {
      inspectObject(
        sdk?.State?.userInfo ||
        sdk?.UserSession?.getUserInfo?.() ||
        sdk?.WmeState?.getUserInfo?.()
      );
    } catch {}

    // WME changes its header markup periodically, so use several narrow,
    // user-oriented selectors and only accept regular HTTP(S) images.
    try {
      const selectors = [
        "wz-user-menu img",
        "wz-avatar img",
        "wz-header img[alt*='avatar' i]",
        "wz-header img[alt*='profile' i]",
        "[data-testid*='user' i] img",
        "[data-testid*='profile' i] img",
        "[class*='user-menu' i] img",
        "[class*='user-profile' i] img",
        "[class*='user-avatar' i] img",
        "img[src*='avatar' i]"
      ];
      for (const selector of selectors) {
        for (const image of document.querySelectorAll(selector)) {
          addSrcset(image.getAttribute("srcset"));
          add(image.currentSrc || image.src || image.getAttribute("src"));
        }
      }
    } catch {}

    return candidates[0] || "";
  }

  function readCurrentWmeIdentity() {
    const username = readCurrentWmeUsername();
    const normalizedUsername = normalizeFriendsUsername(username);
    const ids = [];
    const addId = (value) => {
      const text = String(value ?? "").trim();
      if (!text || text === "undefined" || text === "null" || text === "[object Object]") return;
      if (!ids.includes(text)) ids.push(text);
    };

    try {
      const user = UW?.W?.loginManager?.user;
      addId(user?.getID?.());
      addId(user?.getId?.());
      addId(user?.id);
      addId(user?.userID);
      addId(user?.userId);
      addId(user?.attributes?.id);
      addId(user?.attributes?.userID);
      addId(user?.attributes?.userId);
    } catch {}

    try {
      const info = sdk?.State?.userInfo || sdk?.UserSession?.getUserInfo?.() || sdk?.WmeState?.getUserInfo?.();
      addId(info?.id);
      addId(info?.userID);
      addId(info?.userId);
    } catch {}

    const userId = ids[0] || "";
    return {
      username,
      normalizedUsername,
      userId,
      bindingKey: userId ? `wme-id:${userId}` : (normalizedUsername ? `wme-user:${normalizedUsername}` : "")
    };
  }

  function friendsCanonicalWmeId(identity = readCurrentWmeIdentity()) {
    return String(identity?.userId || "").trim();
  }

  function friendsOwnWmeId() {
    return String(
      friendsProfile?.wmeUserId ||
      friendsCanonicalWmeId() ||
      friendsProfile?.uid ||
      ""
    ).trim();
  }

  function makeFriendsError(message, code) {
    const error = new Error(String(message || "Friends error."));
    error.code = String(code || "friends/error");
    return error;
  }


  function friendsFieldValue() {
    const fb = getFirebaseCompatGlobal();
    return fb?.firestore?.FieldValue || null;
  }

  function friendsServerTimestamp() {
    const FieldValue = friendsFieldValue();
    return FieldValue?.serverTimestamp?.() || new Date();
  }

  function getStoredFriendSeen(key) {
    try {
      const value = JSON.parse(localStorage.getItem(key) || "[]");
      return new Set(Array.isArray(value) ? value.map(String) : []);
    } catch {
      return new Set();
    }
  }

  function markFriendSeen(key, id) {
    try {
      const seen = getStoredFriendSeen(key);
      seen.add(String(id));
      localStorage.setItem(key, JSON.stringify(Array.from(seen).slice(-250)));
    } catch {}
  }

  function getFriendsStateSnapshot() {
    const identity = readCurrentWmeIdentity();
    return {
      ready: !!friendsDb && !!friendsAuth,
      connected: !!friendsAuthUser,
      anonymous: !!friendsAuthUser,
      wmeLinked: !!friendsAuthUser && !!identity.bindingKey,
      authError: String(friendsAuthError || ""),
      authErrorCode: String(friendsAuthErrorCode || ""),
      user: friendsAuthUser,
      profile: friendsProfile,
      incomingRequests: friendsIncomingRequests.slice(),
      outgoingRequests: friendsOutgoingRequests.slice(),
      friends: friendsAccepted.slice(),
      incomingShares: friendsIncomingShares.slice()
    };
  }

  function friendsUiStableValue(value, seen = new WeakSet()) {
    if (value == null) return value;
    if (value instanceof Date) return value.toISOString();

    const type = typeof value;
    if (type === "function" || type === "undefined") return undefined;
    if (type !== "object") return value;
    if (seen.has(value)) return "[Circular]";
    seen.add(value);

    if (Array.isArray(value)) {
      return value.map((item) => friendsUiStableValue(item, seen));
    }

    const normalized = {};
    for (const key of Object.keys(value).sort()) {
      const child = friendsUiStableValue(value[key], seen);
      if (child !== undefined) normalized[key] = child;
    }
    return normalized;
  }

  function getFriendsUiFingerprint(snapshot) {
    try {
      return JSON.stringify(friendsUiStableValue({
        ready: !!snapshot?.ready,
        connected: !!snapshot?.connected,
        anonymous: !!snapshot?.anonymous,
        authError: String(snapshot?.authError || ""),
        authErrorCode: String(snapshot?.authErrorCode || ""),
        userUid: String(snapshot?.user?.uid || ""),
        profile: snapshot?.profile || null,
        incomingRequests: snapshot?.incomingRequests || [],
        outgoingRequests: snapshot?.outgoingRequests || [],
        friends: snapshot?.friends || [],
        incomingShares: snapshot?.incomingShares || []
      }));
    } catch {
      return `${Date.now()}:${Math.random()}`;
    }
  }

  function notifyFriendsUi() {
    const snapshot = getFriendsStateSnapshot();
    const fingerprint = getFriendsUiFingerprint(snapshot);
    for (const entry of Array.from(friendsUiSubscribers)) {
      try {
        if (!entry?.owner?.isConnected) {
          friendsUiSubscribers.delete(entry);
          continue;
        }
        if (entry.lastFingerprint === fingerprint) continue;
        entry.lastFingerprint = fingerprint;
        entry.callback(snapshot);
      } catch {}
    }
  }

  function subscribeFriendsUi(owner, callback) {
    const snapshot = getFriendsStateSnapshot();
    const entry = {
      owner,
      callback,
      lastFingerprint: getFriendsUiFingerprint(snapshot)
    };
    friendsUiSubscribers.add(entry);
    try { callback(snapshot); } catch {}
    return () => friendsUiSubscribers.delete(entry);
  }

  function stopFriendsListeners(clearState = true) {
    stopFastOutgoingRequestPoll();
    if (friendsDerivedRefreshTimer) {
      try { clearTimeout(friendsDerivedRefreshTimer); } catch {}
      friendsDerivedRefreshTimer = null;
    }
    if (friendsRequestFallbackTimer) {
      try { clearTimeout(friendsRequestFallbackTimer); } catch {}
      friendsRequestFallbackTimer = null;
    }
    friendsRequestFallbackRunning = false;
    while (friendsListeners.length) {
      try { friendsListeners.pop()(); } catch {}
    }
    if (clearState) {
      friendsIncomingRequests = [];
      friendsOutgoingRequests = [];
      friendsAccepted = [];
      friendsIncomingShares = [];
      notifyFriendsUi();
    }
  }

  function isFriendsQuotaError(error) {
    const code = String(error?.code || "").toLowerCase();
    const message = String(error?.message || error || "").toLowerCase();
    const status = Number(error?.details?.status || error?.status || 0);
    const serverStatus = String(
      error?.details?.response?.error?.status ||
      error?.details?.response?.status ||
      ""
    ).toLowerCase();
    return (
      status === 429 ||
      code.includes("429") ||
      code.includes("resource-exhausted") ||
      code.includes("resource_exhausted") ||
      code.includes("quota-exceeded") ||
      code.includes("quota_exceeded") ||
      code.includes("quota-backoff") ||
      serverStatus.includes("resource_exhausted") ||
      serverStatus.includes("quota") ||
      message.includes("http 429") ||
      message.includes("quota exceeded") ||
      message.includes("resource exhausted") ||
      message.includes("resource-exhausted") ||
      message.includes("temporarily paused while the shared firebase quota")
    );
  }

  function getFriendsQuotaBackoffUntil() {
    try {
      const value = Number(localStorage.getItem(FRIENDS_QUOTA_BACKOFF_KEY) || 0);
      return Number.isFinite(value) ? value : 0;
    } catch {
      return 0;
    }
  }

  function setFriendsQuotaBackoff(durationMs = FRIENDS_QUOTA_BACKOFF_MS) {
    const requested = Math.max(60_000, Number(durationMs) || FRIENDS_QUOTA_BACKOFF_MS);
    const until = Date.now() + Math.min(FRIENDS_QUOTA_BACKOFF_MAX_MS, requested);
    try { localStorage.setItem(FRIENDS_QUOTA_BACKOFF_KEY, String(until)); } catch {}
    return until;
  }

  function clearFriendsQuotaBackoff() {
    try { localStorage.removeItem(FRIENDS_QUOTA_BACKOFF_KEY); } catch {}
    friendsQuotaNoticeShown = false;
    friendsQuotaStrikeCount = 0;
    if (friendsQuotaResumeTimer) {
      try { clearTimeout(friendsQuotaResumeTimer); } catch {}
      friendsQuotaResumeTimer = null;
    }
  }

  function scheduleFriendsQuotaResume(until = getFriendsQuotaBackoffUntil()) {
    if (friendsQuotaResumeTimer) {
      try { clearTimeout(friendsQuotaResumeTimer); } catch {}
      friendsQuotaResumeTimer = null;
    }

    const delay = Math.max(1000, Number(until || 0) - Date.now() + 250);
    friendsQuotaResumeTimer = setTimeout(() => {
      friendsQuotaResumeTimer = null;
      const activeUntil = getFriendsQuotaBackoffUntil();
      if (activeUntil > Date.now()) {
        scheduleFriendsQuotaResume(activeUntil);
        return;
      }
      clearFriendsQuotaBackoff();
      if (friendsAuthUser && friendsDb) {
        try { startFriendsRealtimeListeners(); } catch {}
      }
    }, Math.min(delay, 0x7fffffff));
  }

  function notifyFriendsQuotaExceeded(error = null) {
    const currentUntil = getFriendsQuotaBackoffUntil();
    const alreadyCoolingDown = currentUntil > Date.now();
    let until = currentUntil;

    // A request made during an existing cooldown must not extend the cooldown.
    // This also makes simultaneous 429 responses idempotent instead of turning
    // one quota event into several increasingly long backoff periods.
    if (!alreadyCoolingDown) {
      friendsQuotaStrikeCount = Math.min(6, friendsQuotaStrikeCount + 1);
      const duration = Math.min(
        FRIENDS_QUOTA_BACKOFF_MAX_MS,
        FRIENDS_QUOTA_BACKOFF_MS * Math.pow(2, Math.max(0, friendsQuotaStrikeCount - 1))
      );
      until = setFriendsQuotaBackoff(duration);
    }

    // Stop every polling listener immediately but keep the last successful UI state.
    try { stopFriendsListeners(false); } catch {}
    scheduleFriendsQuotaResume(until || (Date.now() + FRIENDS_QUOTA_BACKOFF_MS));

    if (!friendsQuotaNoticeShown) {
      friendsQuotaNoticeShown = true;
      try {
        toast("Friends paused temporarily: the shared Firebase quota was exceeded.");
      } catch {}
      if (error && String(error?.code || "") !== "friends/quota-backoff") {
        try { console.warn(`${SCRIPT_NAME}: Firebase Friends quota exceeded; sync paused`, error); } catch {}
      }
    }
  }

  function readCachedFriendsProfile(authUid, normalizedUsername = "") {
    try {
      const raw = localStorage.getItem(FRIENDS_LAST_PROFILE_KEY);
      if (!raw) return null;

      const cached = JSON.parse(raw);
      if (!cached || String(cached.authUid || "") !== String(authUid || "")) return null;

      const normalized = normalizeFriendsUsername(
        cached.wmeUsernameNormalized || cached.wmeUsername || ""
      );
      if (
        normalizedUsername &&
        normalized &&
        normalized !== normalizeFriendsUsername(normalizedUsername)
      ) {
        return null;
      }

      return {
        uid: String(cached.uid || cached.wmeUserId || ""),
        authUid: String(cached.authUid || ""),
        wmeUsername: String(cached.wmeUsername || "").trim(),
        wmeUsernameNormalized: normalized,
        wmeUserId: String(cached.wmeUserId || cached.uid || ""),
        wmeAvatarUrl: normalizeWmeAvatarUrl(cached.wmeAvatarUrl),
        wmeRank: Number.isFinite(Number(cached.wmeRank)) ? Math.max(0, Math.trunc(Number(cached.wmeRank))) : null,
        wmeBindingKey: String(cached.wmeBindingKey || ""),
        bindingVersion: Number(cached.bindingVersion || 0) || 0,
        verifiedAt: Number(cached.verifiedAt || 0) || 0
      };
    } catch {
      return null;
    }
  }

  function saveCachedFriendsProfile(profile, verifiedAt = Date.now()) {
    if (!profile?.uid || !profile?.authUid) return;
    try {
      localStorage.setItem(FRIENDS_LAST_PROFILE_KEY, JSON.stringify({
        uid: String(profile.uid || profile.wmeUserId || ""),
        authUid: String(profile.authUid || ""),
        wmeUsername: String(profile.wmeUsername || "").trim(),
        wmeUsernameNormalized: normalizeFriendsUsername(
          profile.wmeUsernameNormalized || profile.wmeUsername || ""
        ),
        wmeUserId: String(profile.wmeUserId || profile.uid || ""),
        wmeAvatarUrl: normalizeWmeAvatarUrl(profile.wmeAvatarUrl),
        wmeRank: friendsProfileRawRank(profile),
        wmeBindingKey: String(profile.wmeBindingKey || ""),
        bindingVersion: FRIENDS_AUTH_BINDING_VERSION,
        verifiedAt: Number(verifiedAt) || Date.now()
      }));
    } catch {}
  }

  function useCachedFriendsProfile(profile) {
    if (!profile?.uid) return null;
    friendsProfile = {
      id: String(profile.uid),
      uid: String(profile.uid),
      authUid: String(profile.authUid || friendsAuthUser?.uid || ""),
      wmeUsername: String(profile.wmeUsername || "").trim(),
      wmeUsernameNormalized: normalizeFriendsUsername(
        profile.wmeUsernameNormalized || profile.wmeUsername || ""
      ),
      wmeUserId: String(profile.wmeUserId || profile.uid || ""),
      wmeAvatarUrl: normalizeWmeAvatarUrl(profile.wmeAvatarUrl),
      wmeRank: friendsProfileRawRank(profile),
      wmeBindingKey: String(profile.wmeBindingKey || ""),
      authProvider: "wme-anonymous",
      accountMode: "wme-id-direct"
    };
    friendsProfileCache.set(String(profile.uid), friendsProfile);
    notifyFriendsUi();
    return friendsProfile;
  }

  function friendsRequestStatusRank(status) {
    const value = String(status || "").toLowerCase();
    if (value === "accepted") return 3;
    if (value === "pending") return 2;
    if (value === "declined") return 1;
    return 0;
  }

  async function initFriendsFirebase() {
    if (friendsInitPromise) return friendsInitPromise;

    friendsInitPromise = (async () => {
      const identity = await waitForWmeIdentity();
      const wmeUsername = identity.username;
      identity.username = wmeUsername || identity.username;
      identity.normalizedUsername = normalizeFriendsUsername(identity.username);
      identity.bindingKey = identity.userId
        ? `wme-id:${identity.userId}`
        : (identity.normalizedUsername ? `wme-user:${identity.normalizedUsername}` : "");

      if (!identity.bindingKey) {
        throw makeFriendsError(
          "Log in to WME before using Friends.",
          "friends/wme-identity-missing"
        );
      }

      clearLegacyFriendsAuthOnce();
      friendsActiveWmeBindingKey = identity.bindingKey;
      const initBindingKey = identity.bindingKey;
      const initGeneration = ++friendsIdentityGeneration;
      const fb = createFriendsRestCompat(identity);
      const app = fb.initializeApp(FRIENDS_FIREBASE_CONFIG, FRIENDS_FIREBASE_APP_NAME);

      friendsFirebaseApp = app;
      friendsAuth = app.auth();
      friendsDb = app.firestore();
      friendsUsesNativeFirebase = false;
      friendsRealtimeActive = false;
      friendsRealtimeBindingKey = "";
      friendsRealtimeSignalLastNonce = "";
      friendsRealtimeSignalTargetId = "";
      updateFriendsRealtimeSignalFallback();
      ensureFriendsRealtimeHealthMonitor();
      configureFriendsRealtimeExtension(identity)
        .then(() => updateFriendsRealtimeSignalFallback())
        .catch(() => updateFriendsRealtimeSignalFallback());

      try { await friendsAuth.setPersistence?.("local"); } catch {}

      friendsAuth.onAuthStateChanged(async (user) => {
        if (
          initGeneration !== friendsIdentityGeneration ||
          initBindingKey !== friendsActiveWmeBindingKey
        ) return;
        friendsAuthUser = user || null;
        friendsProfile = null;
        friendsAuthError = "";
        friendsAuthErrorCode = "";
        stopFriendsListeners();

        if (!friendsAuthUser || friendsAuthTransitioning) {
          notifyFriendsUi();
          return;
        }

        try {
          await ensureFriendsProfile();
          if (
            initGeneration !== friendsIdentityGeneration ||
            initBindingKey !== friendsActiveWmeBindingKey
          ) return;
          scheduleFriendsRealtimeConfigure(0);
          startFriendsRealtimeListeners();
          cleanupFriendsHistoricalData().catch(() => {});
        } catch (error) {
          friendsAuthError = String(error?.message || "Friends could not initialize.");
          friendsAuthErrorCode = String(error?.code || "");
          console.error(`${SCRIPT_NAME}: Friends profile initialization failed`, error);
        }
        notifyFriendsUi();
      });

      if (!friendsAuth.currentUser) {
        await friendsAuth.signInAnonymously();
      } else {
        friendsAuthUser = friendsAuth.currentUser;
      }

      startFriendsWmeIdentityWatcher();
      notifyFriendsUi();
      return { app: friendsFirebaseApp, auth: friendsAuth, db: friendsDb };
    })().catch((error) => {
      friendsInitPromise = null;
      friendsAuthError = String(error?.message || "Friends could not initialize.");
      friendsAuthErrorCode = String(error?.code || "");
      notifyFriendsUi();
      throw error;
    });

    return friendsInitPromise;
  }

  function friendsTimeout(promise, timeoutMs, message) {
    let timer = null;
    return Promise.race([
      promise,
      new Promise((_, reject) => {
        timer = setTimeout(() => {
          const error = new Error(message || "The operation timed out.");
          error.code = "friends/popup-timeout";
          reject(error);
        }, timeoutMs);
      })
    ]).finally(() => {
      if (timer) clearTimeout(timer);
    });
  }

  function hasFriendsWmeAccountMismatch(code = friendsAuthErrorCode, message = friendsAuthError) {
    const normalizedCode = String(code || "").toLowerCase();
    const normalizedMessage = String(message || "").toLowerCase();
    return (
      normalizedCode.includes("wme-account-mismatch") ||
      (normalizedMessage.includes("friends is linked to") &&
        normalizedMessage.includes("wme is currently signed in as"))
    );
  }

  function clearFriendsLocalBindingCache() {
    try { localStorage.removeItem(FRIENDS_LAST_PROFILE_KEY); } catch {}
    try { friendsProfileCache.clear(); } catch {}
    friendsProfile = null;
  }

  async function cleanupFriendsHistoricalData() {
    const user = friendsAuthUser;
    if (!user || !friendsDb) return;
    const uid = friendsOwnWmeId();
    if (!uid) return;

    let completed = {};
    try {
      const raw = localStorage.getItem(FRIENDS_DATA_MAINTENANCE_KEY);
      completed = raw ? JSON.parse(raw) : {};
    } catch {}
    if (completed && completed[uid] === 1) return;

    try {
      const [sentRequests, receivedRequests, sentShares, receivedShares] = await Promise.all([
        friendsDb.collection("friendRequests").where("fromUid", "==", uid).get(),
        friendsDb.collection("friendRequests").where("toUid", "==", uid).get(),
        friendsDb.collection("pinShares").where("fromUid", "==", uid).get(),
        friendsDb.collection("pinShares").where("toUid", "==", uid).get()
      ]);

      const requestDocs = new Map();
      for (const snapshot of [sentRequests, receivedRequests]) {
        for (const doc of snapshot?.docs || []) requestDocs.set(String(doc.id), doc);
      }
      const shareDocs = new Map();
      for (const snapshot of [sentShares, receivedShares]) {
        for (const doc of snapshot?.docs || []) shareDocs.set(String(doc.id), doc);
      }

      const deletions = [];
      for (const doc of requestDocs.values()) {
        const status = String(doc.data()?.status || "pending").toLowerCase();
        if (status === "declined") {
          deletions.push(friendsDb.collection("friendRequests").doc(String(doc.id)).delete());
        }
      }
      for (const doc of shareDocs.values()) {
        const status = String(doc.data()?.status || "pending").toLowerCase();
        if (status !== "pending") {
          deletions.push(friendsDb.collection("pinShares").doc(String(doc.id)).delete());
        }
      }
      if (deletions.length) await Promise.allSettled(deletions);

      completed = completed && typeof completed === "object" ? completed : {};
      completed[uid] = 1;
      try { localStorage.setItem(FRIENDS_DATA_MAINTENANCE_KEY, JSON.stringify(completed)); } catch {}
    } catch (error) {
      if (isFriendsQuotaError(error)) notifyFriendsQuotaExceeded(error);
    }
  }

  function connectFriendsAccount() {
    if (friendsConnectPromise) return friendsConnectPromise;

    friendsConnectPromise = (async () => {
      try {
        await initFriendsFirebase();
        if (!friendsAuth.currentUser) await friendsAuth.signInAnonymously();
        friendsAuthUser = friendsAuth.currentUser;
        if (!friendsAuthUser) throw new Error("Firebase returned no Friends session.");
        friendsAuthError = "";
        friendsAuthErrorCode = "";
        await ensureFriendsProfile();
        startFriendsRealtimeListeners();
        return friendsAuthUser;
      } catch (error) {
        friendsAuthError = String(error?.message || "Could not connect Friends.");
        friendsAuthErrorCode = String(error?.code || "friends/connect-failed");
        console.error(`${SCRIPT_NAME}: Friends connection failed`, error);
        toast(friendsAuthError);
        throw error;
      } finally {
        friendsConnectPromise = null;
        notifyFriendsUi();
      }
    })();

    return friendsConnectPromise;
  }

  async function disconnectFriendsAccount() {
    friendsAuthTransitioning = true;
    try {
      stopFriendsListeners();
      try { await friendsAuth?.signOut?.(); } catch {}
      friendsAuthUser = null;
      friendsProfile = null;
      friendsIncomingRequests = [];
      friendsOutgoingRequests = [];
      friendsAccepted = [];
      friendsIncomingShares = [];
      clearFriendsLocalBindingCache();
      friendsInitPromise = null;
      friendsRestCompat = null;
      friendsRestCompatBindingKey = "";
      toast("Friends local session reset for this WME account.");
    } finally {
      friendsAuthTransitioning = false;
      notifyFriendsUi();
    }
  }

  async function resetFriendsRuntimeForWmeIdentity(nextIdentity) {
    if (friendsIdentityResetPromise) return friendsIdentityResetPromise;
    friendsIdentityResetPromise = (async () => {
      friendsAuthTransitioning = true;
      friendsIdentityGeneration += 1;
      try {
        stopFriendsListeners();
        friendsFirebaseApp = null;
        friendsAuth = null;
        friendsDb = null;
        friendsAuthUser = null;
        friendsProfile = null;
        friendsIncomingRequests = [];
        friendsOutgoingRequests = [];
        friendsAccepted = [];
        friendsIncomingShares = [];
        friendsInitPromise = null;
        friendsConnectPromise = null;
        friendsRestCompat = null;
        friendsRestCompatBindingKey = "";
        friendsActiveWmeBindingKey = String(nextIdentity?.bindingKey || "");
        friendsMissingIdentityChecks = 0;
        clearFriendsLocalBindingCache();
      } finally {
        friendsAuthTransitioning = false;
        notifyFriendsUi();
      }
      if (nextIdentity?.bindingKey) await initFriendsFirebase();
    })().finally(() => {
      friendsIdentityResetPromise = null;
    });
    return friendsIdentityResetPromise;
  }

  function startFriendsWmeIdentityWatcher() {
    if (friendsIdentityWatcherTimer) return;
    friendsIdentityWatcherTimer = setInterval(() => {
      const identity = readCurrentWmeIdentity();
      const nextBindingKey = String(identity.bindingKey || "");

      if (!nextBindingKey) {
        friendsMissingIdentityChecks += 1;
        if (friendsMissingIdentityChecks < 3 || !friendsActiveWmeBindingKey) return;
      } else {
        friendsMissingIdentityChecks = 0;
        if (nextBindingKey === friendsActiveWmeBindingKey) return;
      }

      resetFriendsRuntimeForWmeIdentity(identity).catch((error) => {
        console.error(`${SCRIPT_NAME}: Could not switch Friends WME identity`, error);
      });
    }, FRIENDS_WME_IDENTITY_CHECK_MS);
  }

  async function waitForWmeIdentity(maxWaitMs = 16000) {
    const started = Date.now();
    let identity = readCurrentWmeIdentity();
    while (Date.now() - started < maxWaitMs) {
      if (identity.userId && identity.username) return identity;
      if (identity.username && Date.now() - started >= 3000) return identity;
      await new Promise((resolve) => setTimeout(resolve, 300));
      identity = readCurrentWmeIdentity();
    }
    return identity;
  }

  function readCurrentWmeRankRaw() {
    try {
      const user = UW?.W?.loginManager?.user;
      if (typeof user?.getRank === "function") {
        const value = Number(user.getRank());
        if (Number.isFinite(value)) return Math.max(0, Math.trunc(value));
      }

      const candidates = [
        user?.rank,
        user?.attributes?.rank,
        UW?.W?.user?.rank,
        UW?.W?.app?.user?.rank,
        sdk?.UserSession?.getUserInfo?.()?.rank,
        sdk?.WmeState?.getUserInfo?.()?.rank
      ];

      for (const candidate of candidates) {
        const value = Number(candidate);
        if (Number.isFinite(value)) return Math.max(0, Math.trunc(value));
      }
    } catch {}
    return null;
  }

  function friendsProfileRawRank(profile) {
    const candidates = [
      profile?.wmeRank,
      profile?.editorRank,
      profile?.rank
    ];

    for (const candidate of candidates) {
      const value = Number(candidate);
      if (Number.isFinite(value)) return Math.max(0, Math.trunc(value));
    }

    // Compatibility with any profile that may already contain a displayed level.
    const storedLevel = Number(profile?.wmeLevel);
    if (Number.isFinite(storedLevel)) {
      return Math.max(0, Math.trunc(storedLevel) - 1);
    }

    return null;
  }

  function friendsProfileLevelLabel(_profile) {
    return "";
  }

  async function waitForWmeUsername(maxWaitMs = 16000) {
    const started = Date.now();
    let username = readCurrentWmeUsername();
    while (!username && Date.now() - started < maxWaitMs) {
      await new Promise((resolve) => setTimeout(resolve, 400));
      username = readCurrentWmeUsername();
    }
    return username;
  }

  async function ensureFriendsProfile() {
    await initFriendsFirebase();
    const user = friendsAuth.currentUser;
    if (!user) throw new Error("Friends is not connected.");

    const identity = await waitForWmeIdentity();
    const wmeUsername = String(identity?.username || await waitForWmeUsername() || "").trim();
    const wmeUserId = friendsCanonicalWmeId(identity);
    if (!wmeUsername || !wmeUserId) {
      throw makeFriendsError(
        "The numeric WME user ID could not be detected. Reload WME after signing in.",
        "friends/wme-identity-missing"
      );
    }

    identity.username = wmeUsername;
    identity.normalizedUsername = normalizeFriendsUsername(wmeUsername);
    identity.bindingKey = `wme-id:${wmeUserId}`;
    if (friendsActiveWmeBindingKey && identity.bindingKey !== friendsActiveWmeBindingKey) {
      throw makeFriendsError(
        "The WME account changed while Friends was loading.",
        "friends/wme-account-changed"
      );
    }

    const normalized = identity.normalizedUsername;
    const cached = readCachedFriendsProfile(user.uid, normalized);
    const backoffUntil = getFriendsQuotaBackoffUntil();
    const cacheIsFresh =
      cached &&
      cached.verifiedAt > 0 &&
      Number(cached.bindingVersion || 0) >= FRIENDS_AUTH_BINDING_VERSION &&
      String(cached.wmeUserId || cached.uid || "") === wmeUserId &&
      String(cached.wmeBindingKey || "") === identity.bindingKey &&
      Date.now() - cached.verifiedAt < FRIENDS_PROFILE_VERIFY_INTERVAL_MS;

    if (cached && (cacheIsFresh || Date.now() < backoffUntil)) {
      return useCachedFriendsProfile(cached);
    }

    const bindingRef = friendsDb.collection("authBindings").doc(String(user.uid));
    const userRef = friendsDb.collection("users").doc(wmeUserId);

    try {
      // Firebase UID is only an authorization credential. The numeric WME ID
      // is the stable Friends identity and document ID.
      await bindingRef.set({
        authUid: String(user.uid),
        wmeUserId,
        wmeUsername,
        wmeUsernameNormalized: normalized,
        wmeBindingKey: identity.bindingKey,
        updatedAt: friendsServerTimestamp()
      });

      const userSnap = await userRef.get();
      const existing = userSnap.exists ? userSnap.data() || {} : null;
      const wmeAvatarUrl =
        readCurrentWmeAvatarUrl() ||
        improveWmeAvatarUrl(existing?.wmeAvatarUrl);
      await userRef.set({
        uid: wmeUserId,
        authUid: String(user.uid),
        wmeUsername,
        wmeUsernameNormalized: normalized,
        wmeUserId,
        wmeAvatarUrl,
        wmeBindingKey: identity.bindingKey,
        authProvider: "wme-anonymous",
        accountMode: "wme-id-direct",
        active: true,
        bindingVersion: FRIENDS_AUTH_BINDING_VERSION,
        createdAt: existing?.createdAt || friendsServerTimestamp(),
        updatedAt: friendsServerTimestamp()
      });

      const profile = {
        id: wmeUserId,
        uid: wmeUserId,
        authUid: String(user.uid),
        wmeUsername,
        wmeUsernameNormalized: normalized,
        wmeUserId,
        wmeAvatarUrl,
        wmeBindingKey: identity.bindingKey,
        authProvider: "wme-anonymous",
        accountMode: "wme-id-direct"
      };

      clearFriendsQuotaBackoff();
      saveCachedFriendsProfile(profile);
      return useCachedFriendsProfile(profile);
    } catch (error) {
      if (isFriendsQuotaError(error)) {
        notifyFriendsQuotaExceeded(error);
        if (cached) return useCachedFriendsProfile(cached);
      }

      const message = String(error?.message || "");
      const code = String(error?.code || "");
      if (/missing or insufficient permissions|permission[_ -]?denied/i.test(`${message} ${code}`)) {
        throw makeFriendsError(
          "Firestore blocked the WME-ID Friends profile. Publish the v1.3 Friends rules and reload WME.",
          "friends/firestore-rules-required"
        );
      }
      throw error;
    }
  }

  function friendsPairRequestId(uidA, uidB) {
    return `friend_${[String(uidA), String(uidB)].sort().join("__")}`;
  }

  function isFriendRequestBetween(request, uidA, uidB) {
    const fromUid = String(request?.fromUid || "");
    const toUid = String(request?.toUid || "");
    const a = String(uidA || "");
    const b = String(uidB || "");
    return (
      (fromUid === a && toUid === b) ||
      (fromUid === b && toUid === a)
    );
  }

  async function findExistingFriendRequestBetween(uidA, uidB) {
    const cached = [...friendsIncomingRequests, ...friendsOutgoingRequests]
      .find((request) => isFriendRequestBetween(request, uidA, uidB));
    if (cached) return cached;

    const meUid = String(uidA || "");
    if (!meUid) return null;

    try {
      const [sentSnapshot, receivedSnapshot] = await Promise.all([
        friendsDb.collection("friendRequests").where("fromUid", "==", meUid).get(),
        friendsDb.collection("friendRequests").where("toUid", "==", meUid).get()
      ]);

      const all = [
        ...mapFriendsSnapshot(sentSnapshot),
        ...mapFriendsSnapshot(receivedSnapshot)
      ];
      return all.find((request) => isFriendRequestBetween(request, uidA, uidB)) || null;
    } catch (error) {
      if (isFriendsQuotaError(error)) notifyFriendsQuotaExceeded(error);
      else console.warn(`${SCRIPT_NAME}: Could not check existing friend requests`, error);
      return cached || null;
    }
  }

  async function findFriendsUserByUsername(username) {
    await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    const normalized = normalizeFriendsUsername(username);
    if (!normalized) throw new Error("Enter a WME username.");

    const timestampMs = (value) => {
      if (value instanceof Date) return value.getTime();
      if (value?.toDate instanceof Function) {
        try { return value.toDate().getTime(); } catch {}
      }
      const parsed = Date.parse(String(value || ""));
      return Number.isFinite(parsed) ? parsed : 0;
    };

    const normalizeProfile = (data, fallbackUsername = username) => {
      if (!data || typeof data !== "object") return null;

      const wmeUserId = String(
        data.wmeUserId ||
        data.uid ||
        data.id ||
        ""
      ).trim();

      if (!wmeUserId) return null;

      return {
        ...data,
        id: wmeUserId,
        uid: wmeUserId,
        wmeUserId,
        wmeUsername: String(
          data.wmeUsername ||
          fallbackUsername ||
          "WME editor"
        ).trim(),
        wmeUsernameNormalized: normalizeFriendsUsername(
          data.wmeUsernameNormalized ||
          data.wmeUsername ||
          fallbackUsername
        ),
        wmeAvatarUrl: normalizeWmeAvatarUrl(data.wmeAvatarUrl),
        active: data.active !== false,
        accountMode: String(data.accountMode || "wme-id-direct")
      };
    };

    const usernameMatches = (value) =>
      normalizeFriendsUsername(value || "") === normalized;

    const ownProfile =
      usernameMatches(friendsProfile?.wmeUsername)
        ? normalizeProfile(friendsProfile, username)
        : null;

    if (ownProfile) {
      friendsProfileCache.set(ownProfile.uid, ownProfile);
      return ownProfile;
    }

    // Existing relationships are the strongest source of truth. An accepted
    // friend must never be reported as not having RC Functions simply because
    // their public username index is missing, stale, or delayed.
    const relationship = [
      ...friendsAccepted,
      ...friendsIncomingRequests,
      ...friendsOutgoingRequests
    ].find((item) => {
      const usernames = [
        item?.wmeUsername,
        item?.profile?.wmeUsername,
        item?.fromUsername,
        item?.toUsername,
        item?.fromProfile?.wmeUsername,
        item?.toProfile?.wmeUsername
      ];
      return usernames.some(usernameMatches);
    }) || null;

    if (relationship) {
      const ownUid = friendsOwnWmeId();
      const fromUid = String(relationship?.fromUid || "").trim();
      const toUid = String(relationship?.toUid || "").trim();

      const relationshipUid = String(
        relationship?.uid ||
        relationship?.wmeUserId ||
        (
          fromUid === ownUid
            ? toUid
            : fromUid
        ) ||
        ""
      ).trim();

      const isFromSide = fromUid && fromUid === relationshipUid;
      const embeddedProfile =
        relationship?.profile ||
        (isFromSide ? relationship?.fromProfile : relationship?.toProfile) ||
        {};

      let directProfile = null;

      if (relationshipUid) {
        directProfile =
          friendsProfileCache.get(relationshipUid) ||
          null;

        if (!directProfile) {
          try {
            const directSnap = await friendsDb
              .collection("users")
              .doc(relationshipUid)
              .get();

            if (directSnap.exists) {
              directProfile = {
                id: String(directSnap.id || relationshipUid),
                ...(directSnap.data() || {})
              };
            }
          } catch {
            // The relationship itself still proves that this editor uses
            // Friends. Profile details are optional for rendering/search.
          }
        }
      }

      const relationshipProfile = normalizeProfile({
        ...(embeddedProfile || {}),
        ...(directProfile || {}),
        id: relationshipUid,
        uid: relationshipUid,
        wmeUserId: relationshipUid,
        wmeUsername:
          directProfile?.wmeUsername ||
          embeddedProfile?.wmeUsername ||
          relationship?.wmeUsername ||
          (isFromSide
            ? relationship?.fromUsername
            : relationship?.toUsername) ||
          username,
        wmeUsernameNormalized: normalized,
        wmeAvatarUrl:
          directProfile?.wmeAvatarUrl ||
          embeddedProfile?.wmeAvatarUrl ||
          relationship?.wmeAvatarUrl ||
          (isFromSide
            ? relationship?.fromAvatarUrl
            : relationship?.toAvatarUrl) ||
          "",
        active: true,
        accountMode: "wme-id-direct",
        relationshipFallback: true
      }, username);

      if (relationshipProfile) {
        friendsProfileCache.set(
          relationshipProfile.uid,
          relationshipProfile
        );
        return relationshipProfile;
      }
    }

    // Also search profiles already loaded during the current session before
    // spending another Firestore query.
    for (const cachedProfile of friendsProfileCache.values()) {
      if (!usernameMatches(
        cachedProfile?.wmeUsernameNormalized ||
        cachedProfile?.wmeUsername
      )) {
        continue;
      }

      const profile = normalizeProfile(cachedProfile, username);
      if (profile) return profile;
    }

    // Public username lookup is only needed for editors who are not already
    // represented by a local friendship/request/profile.
    const snapshot = await friendsDb.collection("users")
      .where("wmeUsernameNormalized", "==", normalized)
      .get();

    const candidates = (snapshot?.docs || [])
      .map((doc) => ({
        id: String(doc.id || ""),
        ...(doc.data() || {})
      }))
      .map((profile) => normalizeProfile(profile, username))
      .filter((profile) =>
        profile &&
        profile.uid &&
        profile.active !== false &&
        String(profile.accountMode || "") === "wme-id-direct" &&
        usernameMatches(
          profile.wmeUsernameNormalized ||
          profile.wmeUsername
        )
      )
      .sort(
        (a, b) =>
          timestampMs(b.updatedAt || b.createdAt) -
          timestampMs(a.updatedAt || a.createdAt)
      );

    const profile = candidates[0] || null;
    if (!profile) return null;

    friendsProfileCache.set(profile.uid, profile);
    return profile;
  }

  async function sendFriendRequest(username, knownTarget = null) {
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();

    const meUid = friendsOwnWmeId();
    if (!friendsAuth.currentUser || !meUid) throw new Error("Friends is not connected.");

    const target = knownTarget || await findFriendsUserByUsername(username);
    if (!target) throw new Error("No Friends user was found with that WME username.");

    const targetUid = String(target.wmeUserId || target.uid || target.id || "").trim();
    if (!targetUid) throw new Error("The selected WME editor has no valid WME user ID.");
    if (targetUid === meUid) throw new Error("You cannot add yourself.");

    const requestId = friendsPairRequestId(meUid, targetUid);
    const ref = friendsDb.collection("friendRequests").doc(requestId);

    const existing = await findExistingFriendRequestBetween(meUid, targetUid);
    if (existing?.status === "accepted") throw new Error("This user is already your friend.");
    if (existing?.status === "pending") {
      if (String(existing.fromUid || "") === meUid) {
        throw new Error("A friend request is already pending.");
      }
      throw new Error("This editor already sent you a friend request.");
    }
    if (existing?.status === "declined" && existing?.id) {
      try { await friendsDb.collection("friendRequests").doc(String(existing.id)).delete(); } catch {}
    }

    const requestData = {
      fromUid: meUid,
      toUid: targetUid,
      fromAuthUid: String(friendsAuth.currentUser?.uid || friendsProfile?.authUid || ""),
      toAuthUid: String(target.authUid || ""),
      fromUsername: String(friendsProfile?.wmeUsername || readCurrentWmeUsername() || "WME editor"),
      fromUsernameNormalized: normalizeFriendsUsername(friendsProfile?.wmeUsername || readCurrentWmeUsername()),
      fromAvatarUrl: normalizeWmeAvatarUrl(
        friendsProfile?.wmeAvatarUrl ||
        readCurrentWmeAvatarUrl()
      ),
      toUsername: String(target.wmeUsername || username || "WME editor"),
      toUsernameNormalized: normalizeFriendsUsername(target.wmeUsernameNormalized || target.wmeUsername || username),
      toAvatarUrl: normalizeWmeAvatarUrl(target.wmeAvatarUrl),
      status: "pending",
      createdAt: friendsServerTimestamp(),
      updatedAt: friendsServerTimestamp()
    };

    const confirmed = {
      id: requestId,
      ...requestData,
      toProfile: {
        ...target,
        id: targetUid,
        uid: targetUid,
        wmeUserId: targetUid,
        wmeUsername: target.wmeUsername || username,
        wmeUsernameNormalized:
          target.wmeUsernameNormalized || normalizeFriendsUsername(username)
      }
    };

    try {
      await ref.set(requestData);
    } catch (error) {
      const message = String(error?.message || "");
      if (/missing or insufficient permissions|permission[_ -]?denied/i.test(message)) {
        throw new Error("Firebase blocked the friend request. Publish the v1.4.1 Friends rules and reload WME.");
      }
      throw error;
    }

    // Only show Pending after Firestore confirms that the request exists.
    setFriendsRequestUpsertGuard(confirmed, FRIENDS_MUTATION_GUARD_MS);
    friendsProfileCache.set(targetUid, confirmed.toProfile);
    friendsOutgoingRequests = [
      ...friendsOutgoingRequests.filter((request) => String(request.id) !== requestId),
      confirmed
    ];
    notifyFriendsUi();

    await signalFriendsRealtimeChange(targetUid, "friend-request");
    toast(`Friend request sent to ${target.wmeUsername || username}`);
  }

  async function updateFriendRequestStatus(requestId, status) {
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");
    if (!["accepted", "declined"].includes(status)) {
      throw new Error("Invalid friend request status.");
    }

    const previousIncoming = friendsIncomingRequests.slice();
    const previousOutgoing = friendsOutgoingRequests.slice();
    const affectedRequest = [...previousIncoming, ...previousOutgoing]
      .find((request) => String(request?.id || "") === String(requestId)) || null;
    const otherUid = friendsOtherRequestUid(affectedRequest);

    const applyStatus = (request) => (
      String(request?.id) === String(requestId)
        ? { ...request, status, updatedAt: new Date() }
        : request
    );

    // Hide Pending and its matching notification immediately, before the network request completes.
    dismissFriendsNotification("friend-request", requestId);
    setFriendsRequestStatusGuard(requestId, status, 30000);
    friendsIncomingRequests = friendsIncomingRequests.map(applyStatus);
    friendsOutgoingRequests = friendsOutgoingRequests.map(applyStatus);
    notifyFriendsUi();
    refreshFriendsDerivedState().catch(() => {});

    try {
      if (status === "declined") {
        await friendsDb.collection("friendRequests").doc(String(requestId)).delete();
        setFriendsRequestDeleteGuard(requestId, FRIENDS_MUTATION_GUARD_MS);
      } else {
        await friendsDb.collection("friendRequests").doc(String(requestId)).update({
          status,
          updatedAt: friendsServerTimestamp()
        });
        setFriendsRequestStatusGuard(requestId, status, FRIENDS_MUTATION_GUARD_MS);
      }
    } catch (error) {
      clearFriendsRequestMutationGuards(requestId);
      friendsIncomingRequests = previousIncoming;
      friendsOutgoingRequests = previousOutgoing;
      notifyFriendsUi();

      const message = String(error?.message || "");
      if (/missing or insufficient permissions|permission[_ -]?denied/i.test(message)) {
        throw new Error(
          "Firestore blocked accepting this request. Publish the included firestore.rules file, then reload WME."
        );
      }
      throw error;
    }

    if (otherUid) void signalFriendsRealtimeChange(otherUid, `friend-request-${status}`);
    toast(status === "accepted" ? "Friend request accepted" : "Friend request declined");
  }

  async function removeFriendByRequestId(requestId) {
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    const previousIncoming = friendsIncomingRequests.slice();
    const previousOutgoing = friendsOutgoingRequests.slice();
    const previousAccepted = friendsAccepted.slice();
    const affectedRequest = [...previousIncoming, ...previousOutgoing]
      .find((request) => String(request?.id || "") === String(requestId)) || null;
    const acceptedFriend = previousAccepted
      .find((friend) => String(friend?.requestId || "") === String(requestId)) || null;
    const otherUid = friendsOtherRequestUid(affectedRequest) || String(acceptedFriend?.uid || "");

    setFriendsRequestDeleteGuard(requestId, 30000);
    friendsIncomingRequests = friendsIncomingRequests.filter(
      (request) => String(request.id) !== String(requestId)
    );
    friendsOutgoingRequests = friendsOutgoingRequests.filter(
      (request) => String(request.id) !== String(requestId)
    );
    friendsAccepted = friendsAccepted.filter(
      (friend) => String(friend.requestId) !== String(requestId)
    );
    notifyFriendsUi();

    try {
      await friendsDb.collection("friendRequests").doc(String(requestId)).delete();
      setFriendsRequestDeleteGuard(requestId, FRIENDS_MUTATION_GUARD_MS);
    } catch (error) {
      clearFriendsRequestMutationGuards(requestId);
      friendsIncomingRequests = previousIncoming;
      friendsOutgoingRequests = previousOutgoing;
      friendsAccepted = previousAccepted;
      notifyFriendsUi();
      throw error;
    }

    if (otherUid) void signalFriendsRealtimeChange(otherUid, "friend-removed");
    toast("Friend removed");
  }

  async function loadFriendsUserProfiles(uids) {
    const unique = Array.from(new Set((uids || []).map(String).filter(Boolean)));
    const result = new Map();
    const missing = [];

    for (const uid of unique) {
      const cached = friendsProfileCache.get(uid);
      if (cached) result.set(uid, cached);
      else missing.push(uid);
    }

    await Promise.all(missing.map(async (uid) => {
      try {
        const snap = await friendsDb.collection("users").doc(uid).get();
        if (snap.exists) {
          const raw = snap.data() || {};
          const canonicalUid = String(raw.wmeUserId || raw.uid || snap.id || uid);
          const profile = { ...raw, id: canonicalUid, uid: canonicalUid, wmeUserId: canonicalUid };
          friendsProfileCache.set(uid, profile);
          result.set(uid, profile);
        }
      } catch {}
    }));

    const aliases = Array.from(result.entries())
      .map(([legacyUid, profile]) => ({
        legacyUid,
        canonicalUid: String(profile?.migratedToUid || "")
      }))
      .filter((entry) => entry.canonicalUid && entry.canonicalUid !== entry.legacyUid);

    await Promise.all(aliases.map(async ({ legacyUid, canonicalUid }) => {
      try {
        let canonical = friendsProfileCache.get(canonicalUid) || null;
        if (!canonical) {
          const snap = await friendsDb.collection("users").doc(canonicalUid).get();
          if (snap.exists) canonical = { id: snap.id, ...snap.data() };
        }
        if (!canonical) return;
        const resolved = {
          ...canonical,
          id: canonicalUid,
          uid: canonicalUid,
          legacyUid,
          migratedFromUid: legacyUid
        };
        friendsProfileCache.set(canonicalUid, resolved);
        friendsProfileCache.set(legacyUid, resolved);
        result.set(legacyUid, resolved);
        result.set(canonicalUid, resolved);
      } catch {}
    }));

    return result;
  }

  function friendsEmbeddedRequestProfile(request, side) {
    const prefix = side === "from" ? "from" : "to";
    const uid = String(request?.[`${prefix}Uid`] || "");
    const wmeUsername = String(request?.[`${prefix}Username`] || "").trim();
    if (!uid && !wmeUsername) return null;
    return {
      id: uid,
      uid,
      authUid: String(request?.[`${prefix}AuthUid`] || ""),
      wmeUsername,
      wmeUsernameNormalized: normalizeFriendsUsername(
        request?.[`${prefix}UsernameNormalized`] || wmeUsername
      ),
      wmeAvatarUrl: normalizeWmeAvatarUrl(
        request?.[`${prefix}AvatarUrl`] ||
        request?.[`${prefix}Profile`]?.wmeAvatarUrl ||
        ""
      )
    };
  }

  async function refreshFriendsDerivedState() {
    const generation = ++friendsDerivedGeneration;
    const meUid = friendsOwnWmeId();
    if (!meUid) return;

    const all = [...friendsIncomingRequests, ...friendsOutgoingRequests];
    const acceptedRequests = all.filter((request) => request.status === "accepted");
    const incomingPending = friendsIncomingRequests.filter((request) => request.status === "pending");
    const outgoingPending = friendsOutgoingRequests.filter((request) => request.status === "pending");
    const sharePending = friendsIncomingShares.filter((share) => share.status === "pending");

    const profileUids = new Set();
    for (const request of [...acceptedRequests, ...incomingPending, ...outgoingPending]) {
      profileUids.add(request.fromUid === meUid ? request.toUid : request.fromUid);
    }
    for (const share of sharePending) profileUids.add(share.fromUid);

    const profiles = await loadFriendsUserProfiles(Array.from(profileUids));
    if (generation !== friendsDerivedGeneration || !friendsAuthUser) return;

    const acceptedMap = new Map();
    for (const request of acceptedRequests) {
      const legacyOtherUid = request.fromUid === meUid ? request.toUid : request.fromUid;
      if (!legacyOtherUid) continue;
      const embeddedProfile = request.fromUid === meUid
        ? friendsEmbeddedRequestProfile(request, "to")
        : friendsEmbeddedRequestProfile(request, "from");
      const requestProfile =
        request.fromUid === meUid ? request.toProfile : request.fromProfile;
      const profile =
        profiles.get(legacyOtherUid) ||
        requestProfile ||
        embeddedProfile ||
        friendsProfileCache.get(String(legacyOtherUid)) ||
        {};
      const otherUid = String(profile.uid || profile.id || legacyOtherUid);
      if (!otherUid) continue;
      const existingFriend = friendsAccepted.find(
        (friend) => String(friend.uid) === String(otherUid)
      );
      const existingEntry = acceptedMap.get(otherUid);
      if (existingEntry && friendsRequestStatusRank(existingEntry.status) >= friendsRequestStatusRank(request.status)) continue;

      const otherAuthUid = String(
        profile.authUid ||
        (request.fromUid === meUid ? request.toAuthUid : request.fromAuthUid) ||
        ""
      );

      acceptedMap.set(otherUid, {
        uid: otherUid,
        authUid: otherAuthUid,
        legacyUid: legacyOtherUid !== otherUid ? legacyOtherUid : "",
        requestId: request.id,
        status: request.status,
        wmeUsername:
          profile.wmeUsername ||
          existingFriend?.wmeUsername ||
          requestProfile?.wmeUsername ||
          embeddedProfile?.wmeUsername ||
          "WME editor",
        wmeAvatarUrl: normalizeWmeAvatarUrl(
          profile.wmeAvatarUrl ||
          existingFriend?.wmeAvatarUrl ||
          requestProfile?.wmeAvatarUrl ||
          embeddedProfile?.wmeAvatarUrl ||
          ""
        ),
        profile: {
          ...(embeddedProfile || {}),
          ...(requestProfile || {}),
          ...(profile || {}),
          wmeAvatarUrl: normalizeWmeAvatarUrl(
            profile.wmeAvatarUrl ||
            requestProfile?.wmeAvatarUrl ||
            embeddedProfile?.wmeAvatarUrl ||
            existingFriend?.wmeAvatarUrl ||
            ""
          )
        }
      });
    }

    friendsAccepted = Array.from(acceptedMap.values()).sort((a, b) =>
      String(a.wmeUsername).localeCompare(String(b.wmeUsername), undefined, { sensitivity: "base" })
    );

    friendsIncomingRequests = friendsIncomingRequests.map((request) => {
      const otherUid = String(request.fromUid || "");
      const profile =
        profiles.get(otherUid) ||
        request.fromProfile ||
        friendsEmbeddedRequestProfile(request, "from") ||
        friendsProfileCache.get(otherUid) ||
        null;
      return { ...request, fromProfile: profile };
    });

    friendsOutgoingRequests = friendsOutgoingRequests.map((request) => {
      const otherUid = String(request.toUid || "");
      const profile =
        profiles.get(otherUid) ||
        request.toProfile ||
        friendsEmbeddedRequestProfile(request, "to") ||
        friendsProfileCache.get(otherUid) ||
        null;
      return { ...request, toProfile: profile };
    });

    friendsIncomingShares = friendsIncomingShares.map((share) => {
      const otherUid = String(share.fromUid || "");
      const profile =
        profiles.get(otherUid) ||
        share.fromProfile ||
        (share.fromUsername ? {
          id: otherUid,
          uid: otherUid,
          wmeUsername: String(share.fromUsername),
          wmeUsernameNormalized: normalizeFriendsUsername(share.fromUsernameNormalized || share.fromUsername)
        } : null) ||
        friendsProfileCache.get(otherUid) ||
        null;
      return { ...share, fromProfile: profile };
    });

    notifyFriendsUi();
    enqueueUnseenFriendsNotifications();
  }

  function stopFastOutgoingRequestPoll() {
    if (friendsFastOutgoingPollTimer) {
      clearTimeout(friendsFastOutgoingPollTimer);
      friendsFastOutgoingPollTimer = null;
    }
    friendsFastOutgoingPollUntil = 0;
    friendsFastOutgoingPollRunning = false;
  }

  function startFastOutgoingRequestPoll() {
    // Disabled intentionally. The userscript-safe Friends transport refreshes
    // after real writes and at a conservative interval; the previous 750 ms loop
    // consumed a large number of reads and could exhaust the Firebase quota.
    stopFastOutgoingRequestPoll();
  }

  function pruneFriendsRequestMutationGuards() {
    const now = Date.now();
    for (const store of [
      friendsRequestUpsertGuards,
      friendsRequestStatusGuards,
      friendsRequestDeleteGuards
    ]) {
      for (const [id, guard] of Array.from(store.entries())) {
        if (!guard || Number(guard.expiresAt || 0) <= now) store.delete(id);
      }
    }
  }

  function setFriendsRequestUpsertGuard(request, durationMs = FRIENDS_MUTATION_GUARD_MS) {
    const id = String(request?.id || "");
    if (!id) return;
    friendsRequestDeleteGuards.delete(id);
    friendsRequestUpsertGuards.set(id, {
      request: { ...request },
      expiresAt: Date.now() + Math.max(1000, Number(durationMs) || FRIENDS_MUTATION_GUARD_MS)
    });
  }

  function setFriendsRequestStatusGuard(requestId, status, durationMs = FRIENDS_MUTATION_GUARD_MS) {
    const id = String(requestId || "");
    if (!id) return;
    friendsRequestDeleteGuards.delete(id);
    friendsRequestStatusGuards.set(id, {
      status: String(status || ""),
      expiresAt: Date.now() + Math.max(1000, Number(durationMs) || FRIENDS_MUTATION_GUARD_MS)
    });
  }

  function setFriendsRequestDeleteGuard(requestId, durationMs = FRIENDS_MUTATION_GUARD_MS) {
    const id = String(requestId || "");
    if (!id) return;
    friendsRequestUpsertGuards.delete(id);
    friendsRequestStatusGuards.delete(id);
    friendsRequestDeleteGuards.set(id, {
      expiresAt: Date.now() + Math.max(1000, Number(durationMs) || FRIENDS_MUTATION_GUARD_MS)
    });
  }

  function clearFriendsRequestMutationGuards(requestId) {
    const id = String(requestId || "");
    if (!id) return;
    friendsRequestUpsertGuards.delete(id);
    friendsRequestStatusGuards.delete(id);
    friendsRequestDeleteGuards.delete(id);
  }

  function pruneFriendsShareMutationGuards() {
    const now = Date.now();
    for (const [id, guard] of Array.from(friendsShareStatusGuards.entries())) {
      if (!guard || Number(guard.expiresAt || 0) <= now) friendsShareStatusGuards.delete(id);
    }
  }

  function setFriendsShareStatusGuard(shareId, status, durationMs = FRIENDS_MUTATION_GUARD_MS) {
    const id = String(shareId || "");
    if (!id) return;
    friendsShareStatusGuards.set(id, {
      status: String(status || ""),
      expiresAt: Date.now() + Math.max(1000, Number(durationMs) || FRIENDS_MUTATION_GUARD_MS)
    });
  }

  function clearFriendsShareStatusGuard(shareId) {
    const id = String(shareId || "");
    if (id) friendsShareStatusGuards.delete(id);
  }

  function mapFriendsShareSnapshot(snapshot, previous = []) {
    pruneFriendsShareMutationGuards();
    return mapFriendsSnapshot(snapshot, previous).map((share) => {
      const guard = friendsShareStatusGuards.get(String(share?.id || ""));
      return guard ? { ...share, status: guard.status } : share;
    });
  }

  function friendRequestMatchesDirection(request, direction) {
    const me = friendsOwnWmeId();
    if (!me || !request) return false;
    if (direction === "incoming") return String(request.toUid || "") === me;
    if (direction === "outgoing") return String(request.fromUid || "") === me;
    return true;
  }

  function mapFriendRequestSnapshot(snapshot, previous = [], direction = "") {
    pruneFriendsRequestMutationGuards();

    const previousById = new Map(
      (previous || []).map((item) => [String(item?.id || ""), item])
    );
    const mergedById = new Map();

    for (const item of mapFriendsSnapshot(snapshot, previous)) {
      const id = String(item?.id || "");
      if (!id || friendsRequestDeleteGuards.has(id)) continue;
      const statusGuard = friendsRequestStatusGuards.get(id);
      mergedById.set(id, statusGuard ? { ...item, status: statusGuard.status } : item);
    }

    // Keep local status changes visible while a stale query still omits or
    // returns the previous version of the document.
    for (const [id, guard] of friendsRequestStatusGuards.entries()) {
      if (friendsRequestDeleteGuards.has(id) || mergedById.has(id)) continue;
      const old = previousById.get(id);
      if (!old || !friendRequestMatchesDirection(old, direction)) continue;
      mergedById.set(id, { ...old, status: guard.status });
    }

    // Keep newly-created requests visible until Firestore queries have caught up.
    for (const [id, guard] of friendsRequestUpsertGuards.entries()) {
      if (friendsRequestDeleteGuards.has(id)) continue;
      const optimistic = guard?.request;
      if (!optimistic || !friendRequestMatchesDirection(optimistic, direction)) continue;
      const existing = mergedById.get(id);
      mergedById.set(id, existing
        ? { ...optimistic, ...existing, fromProfile: existing.fromProfile || optimistic.fromProfile || null, toProfile: existing.toProfile || optimistic.toProfile || null }
        : { ...optimistic });
    }

    return Array.from(mergedById.values()).sort((a, b) =>
      String(a?.id || "").localeCompare(String(b?.id || ""))
    );
  }

  function mapFriendsSnapshot(snapshot, previous = []) {
    const previousById = new Map(
      (previous || []).map((item) => [String(item?.id || ""), item])
    );

    return snapshot.docs.map((doc) => {
      const old = previousById.get(String(doc.id)) || {};
      return {
        ...old,
        id: doc.id,
        ...doc.data(),
        fromProfile: old.fromProfile || null,
        toProfile: old.toProfile || null
      };
    });
  }

  function scheduleFriendsDerivedRefresh() {
    if (friendsDerivedRefreshTimer) return;
    friendsDerivedRefreshTimer = setTimeout(() => {
      friendsDerivedRefreshTimer = null;
      refreshFriendsDerivedState().catch(() => {});
    }, 60);
  }

  async function refreshFriendRequestsOnce({ preserveOnEmpty = false } = {}) {
    if (friendsRequestFallbackRunning || !friendsDb || !friendsAuthUser) return false;

    const ownUid = friendsOwnWmeId();
    if (!ownUid) return false;

    friendsRequestFallbackRunning = true;
    try {
      const [incomingSnapshot, outgoingSnapshot] = await Promise.all([
        friendsDb.collection("friendRequests").where("toUid", "==", ownUid).get(),
        friendsDb.collection("friendRequests").where("fromUid", "==", ownUid).get()
      ]);

      const nextIncoming = mapFriendRequestSnapshot(
        incomingSnapshot,
        friendsIncomingRequests,
        "incoming"
      );
      const nextOutgoing = mapFriendRequestSnapshot(
        outgoingSnapshot,
        friendsOutgoingRequests,
        "outgoing"
      );

      // A temporary empty listener/query result must not erase an already-known
      // accepted friendship. This is especially important while Firestore is
      // reconnecting or when the extension was reloaded with WME still open.
      const hasKnownAccepted = [...friendsIncomingRequests, ...friendsOutgoingRequests]
        .some((request) => String(request?.status || "") === "accepted");
      const hasNextAccepted = [...nextIncoming, ...nextOutgoing]
        .some((request) => String(request?.status || "") === "accepted");

      if (!(preserveOnEmpty && hasKnownAccepted && !hasNextAccepted)) {
        friendsIncomingRequests = nextIncoming;
        friendsOutgoingRequests = nextOutgoing;
      }

      await refreshFriendsDerivedState();
      return true;
    } catch (error) {
      if (isFriendsQuotaError(error)) notifyFriendsQuotaExceeded(error);
      else console.warn(`${SCRIPT_NAME}: Friends list fallback refresh failed`, error);
      return false;
    } finally {
      friendsRequestFallbackRunning = false;
    }
  }

  function scheduleFriendRequestsFallbackRefresh(delayMs = 45000) {
    if (friendsRequestFallbackTimer) {
      try { clearTimeout(friendsRequestFallbackTimer); } catch {}
    }

    friendsRequestFallbackTimer = setTimeout(async () => {
      friendsRequestFallbackTimer = null;
      if (!friendsAuthUser || !friendsDb) return;
      await refreshFriendRequestsOnce({ preserveOnEmpty: true });
      scheduleFriendRequestsFallbackRefresh(45000);
    }, Math.max(1000, Number(delayMs) || 45000));
  }

  function startFriendsRealtimeListeners() {
    stopFriendsListeners(false);
    const ownUid = friendsOwnWmeId();
    if (!friendsAuthUser || !ownUid || !friendsDb) return;

    const backoffUntil = getFriendsQuotaBackoffUntil();
    if (backoffUntil > Date.now()) {
      scheduleFriendsQuotaResume(backoffUntil);
      return;
    }

    const handleListenerError = (label, error) => {
      if (isFriendsQuotaError(error)) {
        notifyFriendsQuotaExceeded(error);
      } else {
        console.error(`${SCRIPT_NAME}: ${label} failed`, error);
      }

      // The one-shot queries use the same data model as username search and
      // recover the list when a realtime listener silently fails or reconnects.
      void refreshFriendRequestsOnce({ preserveOnEmpty: true });
      scheduleFriendRequestsFallbackRefresh(12000);
    };

    // Populate accepted friends immediately instead of waiting exclusively for
    // realtime snapshots. Profile lookup failure must never hide the friendship.
    void refreshFriendRequestsOnce({ preserveOnEmpty: true });
    scheduleFriendRequestsFallbackRefresh(45000);

    const incomingUnsub = friendsDb.collection("friendRequests")
      .where("toUid", "==", ownUid)
      .onSnapshot((snapshot) => {
        const next = mapFriendRequestSnapshot(snapshot, friendsIncomingRequests, "incoming");
        const keepAccepted = friendsIncomingRequests.filter((request) =>
          String(request?.status || "") === "accepted" &&
          !next.some((item) => String(item?.id || "") === String(request?.id || ""))
        );
        friendsIncomingRequests = [...next, ...keepAccepted];
        scheduleFriendsDerivedRefresh();
      }, (error) => handleListenerError("incoming Friends listener", error));

    const outgoingUnsub = friendsDb.collection("friendRequests")
      .where("fromUid", "==", ownUid)
      .onSnapshot((snapshot) => {
        const next = mapFriendRequestSnapshot(snapshot, friendsOutgoingRequests, "outgoing");
        const keepAccepted = friendsOutgoingRequests.filter((request) =>
          String(request?.status || "") === "accepted" &&
          !next.some((item) => String(item?.id || "") === String(request?.id || ""))
        );
        friendsOutgoingRequests = [...next, ...keepAccepted];
        scheduleFriendsDerivedRefresh();
      }, (error) => handleListenerError("outgoing Friends listener", error));

    const sharesUnsub = friendsDb.collection("pinShares")
      .where("toUid", "==", ownUid)
      .onSnapshot((snapshot) => {
        friendsIncomingShares = mapFriendsShareSnapshot(snapshot, friendsIncomingShares);
        scheduleFriendsDerivedRefresh();
      }, (error) => handleListenerError("incoming pin listener", error));

    friendsListeners.push(incomingUnsub, outgoingUnsub, sharesUnsub);
  }

  function getAcceptedFriends() {
    return friendsAccepted.slice();
  }

  function getFriendRequestByUid(uid) {
    return friendsAccepted.find((friend) => String(friend.uid) === String(uid)) || null;
  }

  async function sendPinPayloadToFriend(pin, friendUid, options = {}) {
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    const meUid = friendsOwnWmeId();
    if (!friendsAuth.currentUser || !meUid) throw new Error("Friends is not connected.");

    const friend = getFriendRequestByUid(friendUid);
    if (!friend) throw new Error("This user is not an accepted friend.");
    if (!pin || !Number.isFinite(Number(pin.lat)) || !Number.isFinite(Number(pin.lon))) {
      throw new Error("This pin has invalid coordinates.");
    }

    const shareRef = friendsDb.collection("pinShares").doc();
    const explicitFolderName = options?.folderName == null ? null : String(options.folderName || "");
    const folderName = explicitFolderName != null
      ? explicitFolderName
      : (normalizeGroupId(pin.groupId) === "default"
          ? ""
          : String(getGroupName(normalizeGroupId(pin.groupId)) || ""));

    try {
      await shareRef.set({
      fromUid: meUid,
      toUid: friend.uid,
      fromAuthUid: String(
        friendsAuth.currentUser?.uid ||
        friendsProfile?.authUid ||
        ""
      ),
      toAuthUid: String(
        friend?.profile?.authUid ||
        friend?.authUid ||
        ""
      ),
      fromUsername: String(friendsProfile?.wmeUsername || readCurrentWmeUsername() || "WME editor"),
      fromUsernameNormalized: normalizeFriendsUsername(friendsProfile?.wmeUsername || readCurrentWmeUsername()),
      toUsername: String(friend.wmeUsername || "WME editor"),
      toUsernameNormalized: normalizeFriendsUsername(friend.wmeUsername || ""),
      friendRequestId: friend.requestId,
      status: "pending",
      createdAt: friendsServerTimestamp(),
      respondedAt: null,
      pin: {
        name: String(pin.name || "Shared pin").slice(0, PIN_NAME_MAX),
        note: String(pin.note || "").slice(0, 100),
        lat: Number(pin.lat),
        lon: Number(pin.lon),
        color: normalizePinColor(pin.color),
        folderName: String(folderName || "").slice(0, 40)
      }
      });
    } catch (error) {
      const message = String(error?.message || "");
      const normalizedError =
        /missing or insufficient permissions|permission[_ -]?denied/i.test(message)
          ? new Error(
              "Firestore blocked pin delivery. Publish the included firestore.rules file, then reload WME."
            )
          : error;

      if (!options?.silent) {
        showPinSendNotification({
          sent: 0,
          failed: 1,
          recipient: friend.wmeUsername,
          error: normalizedError
        });
      }
      throw normalizedError;
    }

    void signalFriendsRealtimeChange(friend.uid, "pin-share");
    if (!options?.silent) {
      showPinSendNotification({
        sent: 1,
        failed: 0,
        recipient: friend.wmeUsername
      });
    }
    return { shareId: String(shareRef.id || ""), friend };
  }

  async function sendPinToFriend(pinId, friendUid, options = {}) {
    const pin = loadPins().find((entry) => String(entry?.id) === String(pinId));
    if (!pin) throw new Error("This pin no longer exists.");
    return sendPinPayloadToFriend(pin, friendUid, options);
  }

  function resolveSharedPinGroup(folderName) {
    const name = String(folderName || "").trim();
    if (!name) return "default";

    const existing = loadPinGroups().find((group) =>
      String(group?.name || "").trim().toLowerCase() === name.toLowerCase()
    );
    if (existing) return normalizeGroupId(existing.id);

    return createPinGroup(name, "");
  }

  async function acceptSharedPin(share, options = {}) {
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    const shared = share?.pin || {};
    if (!Number.isFinite(Number(shared.lat)) || !Number.isFinite(Number(shared.lon))) {
      throw new Error("The shared pin coordinates are invalid.");
    }

    const shareId = String(share?.id || "");
    const previousShares = friendsIncomingShares.slice();
    const previousPins = loadPins();
    const previousGroups = loadPinGroups();
    const pins = previousPins.slice();
    const name = makeUniquePinName(String(shared.name || "Shared pin"), null);
    const id = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    const groupId = resolveSharedPinGroup(shared.folderName);

    pins.push({
      id,
      name,
      color: normalizePinColor(shared.color),
      mapSymbol: "default",
      groupId,
      lon: Number(shared.lon),
      lat: Number(shared.lat),
      zoom: null,
      createdAt: Date.now(),
      reminderAt: null,
      reminderDone: false,
      reminderType: null,
      reminderUnit: null,
      reminderValue: null,
      reminderNote: "",
      note: String(shared.note || "").slice(0, 100),
      hideOnMap: false
    });

    // Apply locally before the Firestore request, so the row and notification disappear instantly.
    savePins(pins);
    setFriendsShareStatusGuard(shareId, "accepted", 30000);
    friendsIncomingShares = friendsIncomingShares.map((entry) =>
      String(entry?.id || "") === shareId
        ? { ...entry, status: "accepted", respondedAt: new Date() }
        : entry
    );
    dismissFriendsNotification("pin-share", shareId);
    notifyFriendsUi();
    try { renderPinsPanel(true); } catch {}
    try { renderPinsMarkers(true); } catch {}
    try { revealPinInMapPinsPanel(id, { scroll: true }); } catch {}

    try {
      await friendsDb.collection("pinShares").doc(shareId).delete();
      setFriendsShareStatusGuard(shareId, "accepted", FRIENDS_MUTATION_GUARD_MS);
    } catch (error) {
      clearFriendsShareStatusGuard(shareId);
      friendsIncomingShares = previousShares;
      savePinGroups(previousGroups);
      savePins(previousPins);
      notifyFriendsUi();
      try { renderPinsPanel(true); } catch {}
      try { renderPinsMarkers(true); } catch {}
      enqueueFriendsNotification({ type: "pin-share", id: shareId, data: share });
      throw error;
    }

    if (share?.fromUid) void signalFriendsRealtimeChange(share.fromUid, "pin-share-accepted");
    if (!options?.silent) toast("Shared pin added");
  }

  async function declineSharedPin(shareId, options = {}) {
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    const id = String(shareId || "");
    const previousShares = friendsIncomingShares.slice();
    const previousShare = previousShares.find((entry) => String(entry?.id || "") === id) || null;

    // Apply locally before the Firestore request, so the row and notification disappear instantly.
    setFriendsShareStatusGuard(id, "declined", 30000);
    friendsIncomingShares = friendsIncomingShares.map((entry) =>
      String(entry?.id || "") === id
        ? { ...entry, status: "declined", respondedAt: new Date() }
        : entry
    );
    dismissFriendsNotification("pin-share", id);
    notifyFriendsUi();

    try {
      await friendsDb.collection("pinShares").doc(id).delete();
      setFriendsShareStatusGuard(id, "declined", FRIENDS_MUTATION_GUARD_MS);
    } catch (error) {
      clearFriendsShareStatusGuard(id);
      friendsIncomingShares = previousShares;
      notifyFriendsUi();
      if (previousShare) enqueueFriendsNotification({ type: "pin-share", id, data: previousShare });
      throw error;
    }

    if (previousShare?.fromUid) void signalFriendsRealtimeChange(previousShare.fromUid, "pin-share-declined");
    if (!options?.silent) toast("Shared pin declined");
  }

  function friendsNotificationKey(type, id) {
    return `${String(type || "notification")}::${String(id || "")}`;
  }

  function dismissFriendsNotification(type, id) {
    const notificationType = String(type || "");
    const notificationId = String(id || "");
    const key = friendsNotificationKey(notificationType, notificationId);

    friendsNotificationQueue = friendsNotificationQueue.filter(
      (item) => friendsNotificationKey(item?.type, item?.id) !== key
    );

    if (notificationType === "pin-share") {
      friendsPinShareNotificationItems.delete(notificationId);
      friendsPinShareSelectedIds.delete(notificationId);
      friendsPinShareKnownIds.delete(notificationId);
      syncFriendsPinShareSenderFilter(getSortedPendingFriendsPinShares());
      const legacyActive = friendsActiveNotifications.get(key);
      if (legacyActive?.close) {
        friendsActiveNotifications.delete(key);
        legacyActive.close();
      }
      renderFriendsPinShareNotification();
      return;
    }

    const active = friendsActiveNotifications.get(key);
    if (active?.close) {
      friendsActiveNotifications.delete(key);
      active.close();
    }
  }

  function enqueueFriendsNotification(item) {
    if (!item?.id) return;
    const type = String(item.type || "");
    const id = String(item.id || "");

    if (type === "pin-share") {
      if (String(item?.data?.status || "pending") !== "pending") return;
      const previous = friendsPinShareNotificationItems.get(id) || {};
      friendsPinShareNotificationItems.set(id, { ...previous, ...item.data, id });
      renderFriendsPinShareNotification();
      return;
    }

    const key = friendsNotificationKey(type, id);
    if (
      friendsActiveNotifications.has(key) ||
      friendsNotificationQueue.some((queued) => friendsNotificationKey(queued?.type, queued?.id) === key)
    ) return;
    friendsNotificationQueue.push(item);
    processFriendsNotificationQueue();
  }

  function enqueueUnseenFriendsNotifications() {
    if (!friendsAuthUser) return;

    const seenRequests = getStoredFriendSeen(FRIENDS_SEEN_REQUESTS_KEY);
    for (const request of friendsIncomingRequests) {
      if (request.status !== "pending" || seenRequests.has(String(request.id))) continue;
      markFriendSeen(FRIENDS_SEEN_REQUESTS_KEY, request.id);
      enqueueFriendsNotification({ type: "friend-request", id: request.id, data: request });
    }

    const seenShares = getStoredFriendSeen(FRIENDS_SEEN_SHARES_KEY);
    for (const share of friendsIncomingShares) {
      if (share.status !== "pending" || seenShares.has(String(share.id))) continue;
      markFriendSeen(FRIENDS_SEEN_SHARES_KEY, share.id);
      enqueueFriendsNotification({ type: "pin-share", id: share.id, data: share });
    }

    if (friendsPinShareNotificationItems.size) {
      const pendingIds = new Set(
        friendsIncomingShares
          .filter((share) => String(share?.status || "") === "pending")
          .map((share) => String(share?.id || ""))
          .filter(Boolean)
      );
      let changed = false;
      for (const id of Array.from(friendsPinShareNotificationItems.keys())) {
        if (pendingIds.has(id)) continue;
        friendsPinShareNotificationItems.delete(id);
        friendsPinShareSelectedIds.delete(id);
        friendsPinShareKnownIds.delete(id);
        changed = true;
      }
      if (changed) renderFriendsPinShareNotification();
    }
  }

  function readFriendsNotificationPosition() {
    try {
      const value = JSON.parse(localStorage.getItem(FRIENDS_NOTIFICATION_POS_KEY) || "null");
      if (!value || !Number.isFinite(Number(value.left)) || !Number.isFinite(Number(value.top))) return null;
      return { left: Number(value.left), top: Number(value.top) };
    } catch {
      return null;
    }
  }

  function saveFriendsNotificationPosition(left, top) {
    try {
      localStorage.setItem(FRIENDS_NOTIFICATION_POS_KEY, JSON.stringify({
        left: Math.round(Number(left) || 0),
        top: Math.round(Number(top) || 0)
      }));
    } catch {}
  }

  function clearFriendsNotificationPosition() {
    try { localStorage.removeItem(FRIENDS_NOTIFICATION_POS_KEY); } catch {}
  }

  function updateFriendsNotificationStackPosition() {
    const stack = document.getElementById("wmeRcFriendsNotificationStack");
    if (!stack || !stack.childElementCount || friendsNotificationDragging) return;

    const vw = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
    const vh = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
    const pad = vw <= 700 ? 10 : 12;
    const saved = readFriendsNotificationPosition();

    if (saved) {
      const width = Math.max(250, stack.offsetWidth || 330);
      const height = Math.max(60, stack.offsetHeight || 90);
      const left = Math.max(pad, Math.min(saved.left, vw - width - pad));
      const top = Math.max(pad, Math.min(saved.top, vh - height - pad));
      stack.style.left = `${Math.round(left)}px`;
      stack.style.top = `${Math.round(top)}px`;
      stack.style.right = "auto";
      stack.style.bottom = "auto";
      return;
    }

    // Default position requested for the Pin received card. It remains draggable,
    // and a dragged position continues to take priority over these offsets.
    const edgeRight = vw <= 700 ? 22 : 92;
    const preferredBottom = vw <= 700 ? 18 : 66;
    const height = Math.max(60, stack.offsetHeight || 90);
    const maxBottom = Math.max(pad, vh - height - pad);
    const bottom = Math.max(pad, Math.min(preferredBottom, maxBottom));

    stack.style.right = `${edgeRight}px`;
    stack.style.bottom = `${bottom}px`;
    stack.style.left = "auto";
    stack.style.top = "auto";
  }

  function scheduleFriendsNotificationPositionUpdate() {
    requestAnimationFrame(updateFriendsNotificationStackPosition);
  }

  function startFriendsNotificationPositionWatcher() {
    if (friendsNotificationPositionTimer) return;
    friendsNotificationPositionTimer = setInterval(() => {
      const stack = document.getElementById("wmeRcFriendsNotificationStack");
      if (!stack?.childElementCount) {
        clearInterval(friendsNotificationPositionTimer);
        friendsNotificationPositionTimer = null;
        return;
      }
      updateFriendsNotificationStackPosition();
    }, 900);
  }

  function ensureFriendsNotificationStack() {
    ensureFriendsStyles();
    let stack = document.getElementById("wmeRcFriendsNotificationStack");
    if (stack) return stack;

    stack = document.createElement("div");
    stack.id = "wmeRcFriendsNotificationStack";
    stack.className = "wmeRcFriendsNotificationStack";
    stack.setAttribute("aria-live", "polite");
    stack.setAttribute("aria-atomic", "false");
    (document.body || document.documentElement).appendChild(stack);
    if (!window.__wmeRcFriendsNotificationResizeBound) {
      window.__wmeRcFriendsNotificationResizeBound = true;
      window.addEventListener("resize", scheduleFriendsNotificationPositionUpdate, true);
    }
    return stack;
  }

  function bindFriendsNotificationDrag(card, header) {
    if (!card || !header) return;
    header.title = "Drag to move. Double-click to reset position.";

    header.addEventListener("dblclick", (event) => {
      try {
        if (event.target?.closest?.("button")) return;
        event.preventDefault();
        event.stopPropagation();
      } catch {}
      clearFriendsNotificationPosition();
      updateFriendsNotificationStackPosition();
    });

    header.addEventListener("pointerdown", (event) => {
      try {
        if (event.button != null && event.button !== 0) return;
        if (event.target?.closest?.("button")) return;
      } catch {}

      const stack = card.closest(".wmeRcFriendsNotificationStack");
      if (!stack) return;
      const rect = stack.getBoundingClientRect();
      const startX = Number(event.clientX || 0);
      const startY = Number(event.clientY || 0);
      const startLeft = rect.left;
      const startTop = rect.top;
      const pointerId = event.pointerId;
      let moved = false;

      stack.style.left = `${Math.round(startLeft)}px`;
      stack.style.top = `${Math.round(startTop)}px`;
      stack.style.right = "auto";
      stack.style.bottom = "auto";
      stack.classList.add("is-dragging");
      friendsNotificationDragging = true;
      try { header.setPointerCapture?.(pointerId); } catch {}
      try { event.preventDefault(); event.stopPropagation(); } catch {}

      const onMove = (moveEvent) => {
        if (pointerId != null && moveEvent.pointerId != null && moveEvent.pointerId !== pointerId) return;
        const dx = Number(moveEvent.clientX || 0) - startX;
        const dy = Number(moveEvent.clientY || 0) - startY;
        if (Math.abs(dx) > 2 || Math.abs(dy) > 2) moved = true;
        const vw = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
        const vh = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
        const pad = 10;
        const width = Math.max(250, stack.offsetWidth || rect.width || 330);
        const height = Math.max(60, stack.offsetHeight || rect.height || 90);
        const left = Math.max(pad, Math.min(startLeft + dx, vw - width - pad));
        const top = Math.max(pad, Math.min(startTop + dy, vh - height - pad));
        stack.style.left = `${Math.round(left)}px`;
        stack.style.top = `${Math.round(top)}px`;
        try { moveEvent.preventDefault(); moveEvent.stopPropagation(); } catch {}
      };

      const onEnd = (upEvent) => {
        if (pointerId != null && upEvent?.pointerId != null && upEvent.pointerId !== pointerId) return;
        try { window.removeEventListener("pointermove", onMove, true); } catch {}
        try { window.removeEventListener("pointerup", onEnd, true); } catch {}
        try { window.removeEventListener("pointercancel", onEnd, true); } catch {}
        try { header.releasePointerCapture?.(pointerId); } catch {}
        stack.classList.remove("is-dragging");
        friendsNotificationDragging = false;
        if (moved) {
          const nextRect = stack.getBoundingClientRect();
          saveFriendsNotificationPosition(nextRect.left, nextRect.top);
        }
      };

      window.addEventListener("pointermove", onMove, true);
      window.addEventListener("pointerup", onEnd, true);
      window.addEventListener("pointercancel", onEnd, true);
    }, true);
  }

  function applyFriendsSideNotificationWmeTheme(card, paletteInput = null, editorColorsInput = null) {
    if (!card) return;
    try {
      const palette = paletteInput || getWindowsCompactPalette(detectAutoRcTheme());
      const editorColors = editorColorsInput || getEditorSurfaceColors(!!palette.isLight);
      const isLight = !!palette.isLight;
      const background = editorColors.bgDefault || palette.bg || (isLight ? "#ffffff" : "#202020");
      const surface = editorColors.bgElevated || palette.surface || background;
      const surfaceAlt = editorColors.bgSecondary || palette.surface2 || surface;
      const foreground = editorColors.contentDefault || palette.fg || (isLight ? "#202124" : "#f3f3f3");
      const muted = editorColors.contentMuted || palette.muted || (isLight ? "#5f6368" : "#b7babf");
      const border = editorColors.borderDefault || palette.border || (isLight ? "rgba(0,0,0,.13)" : "rgba(255,255,255,.14)");
      const listBackground = isLight ? "#e8ebef" : "#23282e";
      const listRowBackground = isLight ? "#f6f7f8" : "#282e34";
      const scrollbarTrack = isLight ? "rgba(0,0,0,.035)" : "rgba(255,255,255,.035)";
      const scrollbarThumb = isLight ? "rgba(52,60,68,.34)" : "rgba(224,229,234,.28)";
      const scrollbarThumbHover = isLight ? "rgba(52,60,68,.48)" : "rgba(224,229,234,.42)";

      card.classList.remove("theme-light", "theme-dark");
      card.classList.add(isLight ? "theme-light" : "theme-dark");
      card.style.setProperty("--wmeRcFriendsNoticeBg", background);
      card.style.setProperty("--wmeRcFriendsNoticeSurface", surface);
      card.style.setProperty("--wmeRcFriendsNoticeSurfaceAlt", surfaceAlt);
      card.style.setProperty("--wmeRcFriendsNoticeFg", foreground);
      card.style.setProperty("--wmeRcFriendsNoticeMuted", muted);
      card.style.setProperty("--wmeRcFriendsNoticeBorder", border);
      card.style.setProperty("--wmeRcFriendsNoticeListBg", listBackground);
      card.style.setProperty("--wmeRcFriendsNoticeListRowBg", listRowBackground);
      card.style.setProperty("--wmeRcFriendsNoticeScrollbarTrack", scrollbarTrack);
      card.style.setProperty("--wmeRcFriendsNoticeScrollbarThumb", scrollbarThumb);
      card.style.setProperty("--wmeRcFriendsNoticeScrollbarThumbHover", scrollbarThumbHover);
      card.style.setProperty("background", "var(--wmeRcFriendsNoticeBg, var(--background_default, #202020))", "important");
      card.style.setProperty("color", "var(--wmeRcFriendsNoticeFg, var(--content_default, #f3f3f3))", "important");
      card.style.setProperty("-webkit-text-fill-color", "var(--wmeRcFriendsNoticeFg, var(--content_default, #f3f3f3))", "important");
      card.style.setProperty("border-color", "var(--wmeRcFriendsNoticeBorder, var(--separator_default, rgba(255,255,255,.14)))", "important");
    } catch {}
  }

  function friendsNotificationInitials(name) {
    const parts = String(name || "WME")
      .trim()
      .split(/[\s_.-]+/)
      .filter(Boolean);
    if (!parts.length) return "W";
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return `${parts[0][0] || ""}${parts[parts.length - 1][0] || ""}`.toUpperCase();
  }

  function renderFriendsNotificationAvatar(container, avatarUrl, name, fallbackIcon = "") {
    if (!container) return;
    container.replaceChildren();
    container.classList.remove("has-avatar");

    const originalUrl = normalizeWmeAvatarUrl(avatarUrl);
    const improvedUrl = improveWmeAvatarUrl(originalUrl);
    const showFallback = () => {
      container.classList.remove("has-avatar");
      if (fallbackIcon) {
        container.innerHTML = `<span class="wmeRcI">${fallbackIcon}</span>`;
      } else {
        container.textContent = friendsNotificationInitials(name);
      }
    };

    if (!improvedUrl) {
      showFallback();
      return;
    }

    container.classList.add("has-avatar");
    const image = document.createElement("img");
    image.className = "wmeRcFriendsSideNotificationAvatarImg";
    image.alt = "";
    image.loading = "eager";
    image.decoding = "async";
    image.src = improvedUrl;
    let retriedOriginal = false;
    image.addEventListener("error", () => {
      if (!retriedOriginal && originalUrl && originalUrl !== improvedUrl) {
        retriedOriginal = true;
        image.src = originalUrl;
        return;
      }
      showFallback();
    });
    container.appendChild(image);
  }

  function showFriendsSideNotification(config = {}) {
    const stack = ensureFriendsNotificationStack();
    const card = document.createElement("section");
    const notificationVariant = String(config.variant || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_-]+/g, "-")
      .replace(/^-+|-+$/g, "");
    card.className = "wmeRcFriendsSideNotification" +
      (notificationVariant ? ` is-${notificationVariant}` : "");
    applyFriendsSideNotificationWmeTheme(card);
    card.setAttribute(
      "role",
      String(config.role || (notificationVariant === "friend-request" ? "alert" : "status"))
    );

    let currentConfig = { ...config };
    let closed = false;
    let senderFilterOpen = false;
    const collapsedGroups = new Set();

    const header = document.createElement("div");
    header.className = "wmeRcFriendsSideNotificationHeader";

    const heading = document.createElement("div");
    heading.className = "wmeRcFriendsSideNotificationHeading";

    const icon = document.createElement("span");
    icon.className = "wmeRcFriendsSideNotificationIcon";

    const title = document.createElement("strong");

    heading.appendChild(icon);
    heading.appendChild(title);

    const closeButton = document.createElement("button");
    closeButton.type = "button";
    closeButton.className = "wmeRcFriendsSideNotificationClose";
    closeButton.setAttribute("aria-label", "Dismiss notification");
    closeButton.title = "Dismiss";
    closeButton.innerHTML = `
      <svg viewBox="0 0 20 20" aria-hidden="true">
        <path d="M5.28 4.22a.75.75 0 0 0-1.06 1.06L8.94 10l-4.72 4.72a.75.75 0 1 0 1.06 1.06L10 11.06l4.72 4.72a.75.75 0 1 0 1.06-1.06L11.06 10l4.72-4.72a.75.75 0 0 0-1.06-1.06L10 8.94 5.28 4.22Z"/>
      </svg>
    `;

    header.appendChild(heading);
    header.appendChild(closeButton);
    bindFriendsNotificationDrag(card, header);

    const content = document.createElement("div");
    content.className = "wmeRcFriendsSideNotificationContent";

    const actionsWrap = document.createElement("div");
    actionsWrap.className = "wmeRcFriendsSideNotificationActions";

    let handleSenderFilterOutsidePointer = null;

    const finish = () => {
      if (closed) return;
      closed = true;
      if (handleSenderFilterOutsidePointer) {
        try { document.removeEventListener("pointerdown", handleSenderFilterOutsidePointer, true); } catch {}
      }
      try { currentConfig.onBeforeClose?.(); } catch {}
      card.classList.remove("is-visible");
      setTimeout(() => {
        try { card.remove(); } catch {}
        try { currentConfig.onClose?.(); } catch {}
        scheduleFriendsNotificationPositionUpdate();
      }, 220);
    };

    const appendTextBlock = (className, value) => {
      if (value == null || value === "") return;
      const element = document.createElement("div");
      element.className = className;
      element.textContent = String(value);
      content.appendChild(element);
    };

    const renderContent = () => {
      const previousList = content.querySelector(".wmeRcFriendsSideNotificationList");
      const previousListScrollTop = Number(previousList?.scrollTop || 0);
      const previousSenderMenu = content.querySelector(".wmeRcFriendsSideNotificationSenderMenu");
      const previousSenderMenuScrollTop = Number(previousSenderMenu?.scrollTop || 0);
      const restoreScrollTop = (element, value) => {
        if (!element || !Number.isFinite(value) || value <= 0) return;
        const apply = () => {
          const max = Math.max(0, Number(element.scrollHeight || 0) - Number(element.clientHeight || 0));
          element.scrollTop = Math.min(value, max);
        };
        apply();
        requestAnimationFrame(apply);
      };

      content.replaceChildren();
      appendTextBlock("wmeRcFriendsSideNotificationMessage", currentConfig.message);
      appendTextBlock("wmeRcFriendsSideNotificationMeta", currentConfig.meta);
      appendTextBlock("wmeRcFriendsSideNotificationDetail", currentConfig.detail);

      const senderFilter = currentConfig.senderFilter && typeof currentConfig.senderFilter === "object"
        ? currentConfig.senderFilter
        : null;
      const chips = Array.isArray(currentConfig.chips) ? currentConfig.chips.filter(Boolean) : [];
      if (senderFilter || chips.length) {
        const chipsWrap = document.createElement("div");
        chipsWrap.className = "wmeRcFriendsSideNotificationChips";

        if (senderFilter) {
          const filterWrap = document.createElement("div");
          filterWrap.className = "wmeRcFriendsSideNotificationSenderFilterWrap";

          const senderChip = document.createElement("button");
          senderChip.type = "button";
          senderChip.className = "wmeRcFriendsSideNotificationChip is-sender-filter" +
            (senderFilterOpen ? " is-open" : "");
          senderChip.innerHTML = `<span>${escapeHtml(String(senderFilter.label || "Senders"))}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m6.3 7.5 3.7 3.7 3.7-3.7"/></svg>`;
          senderChip.addEventListener("click", (event) => {
            try { event.preventDefault(); event.stopPropagation(); } catch {}
            senderFilterOpen = !senderFilterOpen;
            renderContent();
          });
          filterWrap.appendChild(senderChip);

          if (senderFilterOpen) {
            const selectedKeys = new Set(
              Array.isArray(senderFilter.selectedKeys) ? senderFilter.selectedKeys.map(String) : []
            );
            const menu = document.createElement("div");
            menu.className = "wmeRcFriendsSideNotificationSenderMenu";
            menu.addEventListener("wheel", (event) => {
              try { event.stopPropagation(); } catch {}
            }, { passive: true, capture: true });

            for (const sender of Array.isArray(senderFilter.senders) ? senderFilter.senders : []) {
              const key = String(sender?.key || "");
              const selected = selectedKeys.has(key);
              const option = document.createElement("button");
              option.type = "button";
              option.className = "wmeRcFriendsSideNotificationSenderOption" +
                (selected ? " is-selected" : "");

              const senderAvatar = document.createElement("span");
              senderAvatar.className = "wmeRcFriendsSideNotificationListAvatar";
              renderFriendsNotificationAvatar(
                senderAvatar,
                sender?.avatarUrl,
                sender?.avatarName || sender?.username || "WME user"
              );
              option.appendChild(senderAvatar);

              const senderCopy = document.createElement("span");
              senderCopy.className = "wmeRcFriendsSideNotificationSenderCopy";
              const senderName = document.createElement("strong");
              senderName.textContent = String(sender?.username || "A friend");
              const senderMeta = document.createElement("small");
              const count = Number(sender?.count || 0);
              senderMeta.textContent = `${count} pin${count === 1 ? "" : "s"}`;
              senderCopy.appendChild(senderName);
              senderCopy.appendChild(senderMeta);
              option.appendChild(senderCopy);

              const senderCheck = document.createElement("span");
              senderCheck.className = "wmeRcFriendsSideNotificationSenderCheck" +
                (selected ? " is-selected" : "");
              if (selected) {
                senderCheck.innerHTML = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5.1 10.4 2.55 2.55L14.9 5.7"/></svg>';
              }
              option.appendChild(senderCheck);
              option.addEventListener("click", (event) => {
                try { event.preventDefault(); event.stopPropagation(); } catch {}
                senderFilter.onToggle?.(key);
              });
              menu.appendChild(option);
            }
            filterWrap.appendChild(menu);
            restoreScrollTop(menu, previousSenderMenuScrollTop);
          }

          chipsWrap.appendChild(filterWrap);
        }

        for (const chipValue of chips) {
          const chip = document.createElement("span");
          chip.className = "wmeRcFriendsSideNotificationChip";
          chip.textContent = String(chipValue);
          chipsWrap.appendChild(chip);
        }
        content.appendChild(chipsWrap);
      }

      const listItems = Array.isArray(currentConfig.list) ? currentConfig.list : [];
      if (!listItems.length && currentConfig.listEmptyMessage) {
        const empty = document.createElement("div");
        empty.className = "wmeRcFriendsSideNotificationListEmpty";
        empty.textContent = String(currentConfig.listEmptyMessage);
        content.appendChild(empty);
      }
      if (listItems.length) {
        const list = document.createElement("div");
        list.className = "wmeRcFriendsSideNotificationList" +
          (listItems.some((item) => item?.selectable) ? " is-review-list" : "");
        list.addEventListener("wheel", (event) => {
          try { event.stopPropagation(); } catch {}
        }, { passive: true, capture: true });
        list.addEventListener("touchmove", (event) => {
          try { event.stopPropagation(); } catch {}
        }, { passive: true, capture: true });

        for (const item of listItems) {
          const row = document.createElement("div");
          row.className = "wmeRcFriendsSideNotificationListRow" +
            (item?.selectable ? " is-selectable" : "") +
            (item?.selected ? " is-selected" : "");

          const rowAvatar = document.createElement("span");
          rowAvatar.className = "wmeRcFriendsSideNotificationListAvatar";
          renderFriendsNotificationAvatar(
            rowAvatar,
            item?.avatarUrl,
            item?.avatarName || item?.meta || "WME user"
          );
          row.appendChild(rowAvatar);

          const rowText = document.createElement("div");
          rowText.className = "wmeRcFriendsSideNotificationListText";

          const rowTitle = document.createElement("div");
          rowTitle.className = "wmeRcFriendsSideNotificationListTitle";
          rowTitle.textContent = String(item?.title || "Shared pin");
          rowText.appendChild(rowTitle);

          if (item?.meta) {
            const rowMeta = document.createElement("div");
            rowMeta.className = "wmeRcFriendsSideNotificationListMeta";
            rowMeta.textContent = String(item.meta);
            rowText.appendChild(rowMeta);
          }

          if (item?.detail) {
            const rowDetail = document.createElement("div");
            rowDetail.className = "wmeRcFriendsSideNotificationListDetail";
            rowDetail.textContent = String(item.detail);
            rowText.appendChild(rowDetail);
          }

          row.appendChild(rowText);

          if (item?.deletable || item?.selectable) {
            const rowControls = document.createElement("div");
            rowControls.className = "wmeRcFriendsSideNotificationRowControls";

            if (item?.deletable) {
              const deleteButton = document.createElement("button");
              deleteButton.type = "button";
              deleteButton.className = "wmeRcFriendsSideNotificationDelete";
              deleteButton.setAttribute("aria-label", "Decline pin");
              deleteButton.title = "Decline pin";
              deleteButton.innerHTML = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 5.5l9 9M14.5 5.5l-9 9"/></svg>';
              deleteButton.addEventListener("click", (event) => {
                try { event.preventDefault(); event.stopPropagation(); } catch {}
                Promise.resolve()
                  .then(() => item.onDelete?.())
                  .catch((error) => toast(error?.message || "Could not decline pin."));
              });
              rowControls.appendChild(deleteButton);
            }

            if (item?.selectable) {
              const selectButton = document.createElement("button");
              selectButton.type = "button";
              selectButton.className = "wmeRcFriendsSideNotificationSelect" +
                (item?.selected ? " is-selected" : "");
              selectButton.setAttribute("aria-label", item?.selected ? "Deselect pin" : "Select pin");
              selectButton.setAttribute("aria-pressed", item?.selected ? "true" : "false");
              if (item?.selected) {
                selectButton.innerHTML = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5.1 10.4 2.55 2.55L14.9 5.7"/></svg>';
              }
              selectButton.addEventListener("click", (event) => {
                try { event.preventDefault(); event.stopPropagation(); } catch {}
                toggleFriendsPinShareSelection(item?.id);
              });
              rowControls.appendChild(selectButton);
            }

            row.appendChild(rowControls);
          }

          list.appendChild(row);
        }
        content.appendChild(list);
        restoreScrollTop(list, previousListScrollTop);
      }
    };

    handleSenderFilterOutsidePointer = (event) => {
      if (!senderFilterOpen || closed) return;
      const target = event?.target;
      if (target?.closest?.(".wmeRcFriendsSideNotificationSenderFilterWrap")) return;
      senderFilterOpen = false;
      renderContent();
    };
    document.addEventListener("pointerdown", handleSenderFilterOutsidePointer, true);

    const renderActions = () => {
      actionsWrap.replaceChildren();
      for (const action of Array.isArray(currentConfig.actions) ? currentConfig.actions : []) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "wmeRcFriendsSideNotificationBtn" +
          (action.success ? " success" : "") +
          (action.danger ? " danger" : "") +
          (action.primary ? " primary" : "");
        button.textContent = String(action.label || "Open");
        button.disabled = !!action.disabled;
        button.addEventListener("click", (event) => {
          try { event.preventDefault(); event.stopPropagation(); } catch {}
          if (closed || button.disabled) return;
          if (action.closeAfter !== false) finish();
          Promise.resolve()
            .then(() => action.run?.())
            .catch((error) => toast(error?.message || "Could not complete the action."));
        });
        actionsWrap.appendChild(button);
      }

      if (actionsWrap.childElementCount) {
        if (!actionsWrap.isConnected) card.appendChild(actionsWrap);
      } else {
        try { actionsWrap.remove(); } catch {}
      }
    };

    let appliedVariant = notificationVariant;
    const applyConfig = (nextConfig = {}) => {
      if (closed) return;
      const lifecycle = {
        onBeforeClose: currentConfig.onBeforeClose,
        onClose: currentConfig.onClose,
        role: currentConfig.role
      };
      currentConfig = {
        title: "Friends",
        message: "",
        meta: "",
        detail: "",
        senderFilter: null,
        chips: [],
        listEmptyMessage: "",
        list: [],
        actions: [],
        avatarUrl: "",
        avatarName: "",
        icon: "",
        variant: "",
        ...lifecycle,
        ...nextConfig
      };
      if (!currentConfig.senderFilter) senderFilterOpen = false;

      const nextVariant = String(currentConfig.variant || "")
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "");
      if (appliedVariant !== nextVariant) {
        if (appliedVariant) card.classList.remove(`is-${appliedVariant}`);
        if (nextVariant) card.classList.add(`is-${nextVariant}`);
        appliedVariant = nextVariant;
      }

      title.textContent = String(currentConfig.title || "Friends");
      renderFriendsNotificationAvatar(
        icon,
        currentConfig.avatarUrl,
        currentConfig.avatarName || currentConfig.meta || currentConfig.title || "WME user",
        currentConfig.icon || ICONS.user || ICONS.pin || "●"
      );
      renderContent();
      renderActions();
      scheduleFriendsNotificationPositionUpdate();
    };

    closeButton.addEventListener("click", (event) => {
      try { event.preventDefault(); event.stopPropagation(); } catch {}
      finish();
    });

    card.appendChild(header);
    card.appendChild(content);
    stack.appendChild(card);
    applyConfig(currentConfig);

    requestAnimationFrame(() => {
      card.classList.add("is-visible");
      updateFriendsNotificationStackPosition();
    });
    startFriendsNotificationPositionWatcher();
    return { close: finish, update: applyConfig, element: card };
  }

  function makeUniquePinNameForBatch(desiredName, usedNames) {
    const base = String(desiredName ?? "").replace(/\s+/g, " ").trim() || "Pinned place";
    const normalized = (value) => String(value || "").trim().toLowerCase();
    if (!usedNames.has(normalized(base))) {
      usedNames.add(normalized(base));
      return base;
    }
    let index = 2;
    while (index < 10000) {
      const candidate = `${base} (${index})`;
      if (!usedNames.has(normalized(candidate))) {
        usedNames.add(normalized(candidate));
        return candidate;
      }
      index += 1;
    }
    const fallback = `${base} (${Date.now()})`;
    usedNames.add(normalized(fallback));
    return fallback;
  }

  async function deleteFriendsPinSharesAsBatch(shares) {
    const items = Array.isArray(shares) ? shares.filter(Boolean) : [];
    if (!items.length) return;
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    for (let offset = 0; offset < items.length; offset += 450) {
      const chunk = items.slice(offset, offset + 450);
      const batch = friendsDb.batch();
      for (const share of chunk) {
        const id = String(share?.id || "");
        if (!id) continue;
        batch.delete(friendsDb.collection("pinShares").doc(id));
      }
      await batch.commit();
    }
  }

  function removeFriendsPinSharesFromNotification(shares, status) {
    const ids = new Set(
      (Array.isArray(shares) ? shares : [])
        .map((share) => String(share?.id || ""))
        .filter(Boolean)
    );
    if (!ids.size) return;

    for (const id of ids) {
      setFriendsShareStatusGuard(id, status, 30000);
      friendsPinShareNotificationItems.delete(id);
      friendsPinShareSelectedIds.delete(id);
      friendsPinShareKnownIds.delete(id);
    }
    friendsIncomingShares = friendsIncomingShares.map((entry) =>
      ids.has(String(entry?.id || ""))
        ? { ...entry, status, respondedAt: new Date() }
        : entry
    );
    notifyFriendsUi();
    renderFriendsPinShareNotification();
  }

  function restoreFriendsPinShareBatchState(previous) {
    friendsIncomingShares = previous.incomingShares;
    friendsPinShareNotificationItems.clear();
    for (const [id, share] of previous.notificationItems) {
      friendsPinShareNotificationItems.set(id, share);
    }
    friendsPinShareSelectedIds.clear();
    for (const id of previous.selectedIds) friendsPinShareSelectedIds.add(id);
    friendsPinShareKnownIds.clear();
    for (const id of previous.knownIds) friendsPinShareKnownIds.add(id);
    for (const share of previous.items) clearFriendsShareStatusGuard(share?.id);
    notifyFriendsUi();
    renderFriendsPinShareNotification();
  }

  async function acceptSharedPinsBatch(shares) {
    const items = Array.isArray(shares) ? shares.filter(Boolean) : [];
    if (!items.length) throw new Error("Select at least one pin to add.");
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    const previous = {
      items,
      incomingShares: friendsIncomingShares.slice(),
      notificationItems: new Map(friendsPinShareNotificationItems),
      selectedIds: new Set(friendsPinShareSelectedIds),
      knownIds: new Set(friendsPinShareKnownIds),
      pins: loadPins(),
      groups: loadPinGroups()
    };

    const nextPins = previous.pins.slice();
    const usedNames = new Set(
      nextPins
        .map((pin) => String(pin?.name || "").trim().toLowerCase())
        .filter(Boolean)
    );
    const addedIds = [];

    try {
      for (const share of items) {
        const shared = share?.pin || {};
        if (!Number.isFinite(Number(shared.lat)) || !Number.isFinite(Number(shared.lon))) {
          throw new Error("One of the shared pins has invalid coordinates.");
        }
        const id = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
        const name = makeUniquePinNameForBatch(String(shared.name || "Shared pin"), usedNames);
        const groupId = resolveSharedPinGroup(shared.folderName);
        nextPins.push({
          id,
          name,
          color: normalizePinColor(shared.color),
          mapSymbol: "default",
          groupId,
          lon: Number(shared.lon),
          lat: Number(shared.lat),
          zoom: null,
          createdAt: Date.now(),
          reminderAt: null,
          reminderDone: false,
          reminderType: null,
          reminderUnit: null,
          reminderValue: null,
          reminderNote: "",
          note: String(shared.note || "").slice(0, 100),
          hideOnMap: false
        });
        addedIds.push(id);
      }

      savePins(nextPins);
      removeFriendsPinSharesFromNotification(items, "accepted");
      try { renderPinsPanel(true); } catch {}
      try { renderPinsMarkers(true); } catch {}
      if (addedIds.length) {
        try { revealPinInMapPinsPanel(addedIds[addedIds.length - 1], { scroll: true }); } catch {}
      }

      await deleteFriendsPinSharesAsBatch(items);
      for (const share of items) {
        setFriendsShareStatusGuard(share?.id, "accepted", FRIENDS_MUTATION_GUARD_MS);
      }
      for (const senderUid of new Set(items.map((share) => String(share?.fromUid || "")).filter(Boolean))) {
        void signalFriendsRealtimeChange(senderUid, "pin-share-accepted");
      }
    } catch (error) {
      savePinGroups(previous.groups);
      savePins(previous.pins);
      restoreFriendsPinShareBatchState(previous);
      try { renderPinsPanel(true); } catch {}
      try { renderPinsMarkers(true); } catch {}
      throw error;
    }
  }

  async function declineSharedPinsBatch(shares) {
    const items = Array.isArray(shares) ? shares.filter(Boolean) : [];
    if (!items.length) return;
    if (!friendsDb || !friendsAuth) await initFriendsFirebase();
    if (!friendsAuthUser) throw new Error("Friends is not connected.");

    const previous = {
      items,
      incomingShares: friendsIncomingShares.slice(),
      notificationItems: new Map(friendsPinShareNotificationItems),
      selectedIds: new Set(friendsPinShareSelectedIds),
      knownIds: new Set(friendsPinShareKnownIds)
    };

    try {
      removeFriendsPinSharesFromNotification(items, "declined");
      await deleteFriendsPinSharesAsBatch(items);
      for (const share of items) {
        setFriendsShareStatusGuard(share?.id, "declined", FRIENDS_MUTATION_GUARD_MS);
      }
      for (const senderUid of new Set(items.map((share) => String(share?.fromUid || "")).filter(Boolean))) {
        void signalFriendsRealtimeChange(senderUid, "pin-share-declined");
      }
    } catch (error) {
      restoreFriendsPinShareBatchState(previous);
      throw error;
    }
  }

  function getSortedPendingFriendsPinShares() {
    return Array.from(friendsPinShareNotificationItems.entries())
      .map(([id, share]) => ({ ...share, id: String(share?.id || id) }))
      .filter((share) => String(share?.status || "pending") === "pending")
      .sort((a, b) => {
        const aTime = Number(a?.createdAt?.toMillis?.() || a?.createdAt?.seconds * 1000 || 0);
        const bTime = Number(b?.createdAt?.toMillis?.() || b?.createdAt?.seconds * 1000 || 0);
        return aTime - bTime || String(a.id).localeCompare(String(b.id));
      });
  }

  function syncFriendsPinShareSelection(shares) {
    const pendingIds = new Set(
      (Array.isArray(shares) ? shares : [])
        .map((share) => String(share?.id || ""))
        .filter(Boolean)
    );

    for (const id of Array.from(friendsPinShareKnownIds)) {
      if (pendingIds.has(id)) continue;
      friendsPinShareKnownIds.delete(id);
      friendsPinShareSelectedIds.delete(id);
    }

    for (const id of pendingIds) {
      if (friendsPinShareKnownIds.has(id)) continue;
      friendsPinShareKnownIds.add(id);
      friendsPinShareSelectedIds.add(id);
    }
  }

  function friendsPinShareSenderKey(share) {
    const uid = String(share?.fromUid || "").trim();
    if (uid) return `uid:${uid}`;
    const username = String(share?.fromProfile?.wmeUsername || "A friend").trim().toLowerCase();
    return `name:${username || "friend"}`;
  }

  function syncFriendsPinShareSenderFilter(shares) {
    const activeKeys = new Set(
      (Array.isArray(shares) ? shares : [])
        .map((share) => friendsPinShareSenderKey(share))
        .filter(Boolean)
    );

    for (const key of Array.from(friendsPinShareKnownSenderKeys)) {
      if (activeKeys.has(key)) continue;
      friendsPinShareKnownSenderKeys.delete(key);
      friendsPinShareSelectedSenderKeys.delete(key);
    }

    for (const key of activeKeys) {
      if (friendsPinShareKnownSenderKeys.has(key)) continue;
      friendsPinShareKnownSenderKeys.add(key);
      friendsPinShareSelectedSenderKeys.add(key);
    }

    if (activeKeys.size <= 1) {
      friendsPinShareSelectedSenderKeys.clear();
      const onlyKey = activeKeys.values().next().value;
      if (onlyKey) friendsPinShareSelectedSenderKeys.add(onlyKey);
    }
  }

  function toggleFriendsPinShareSenderFilter(senderKey) {
    const key = String(senderKey || "").trim();
    if (!key) return;
    if (friendsPinShareSelectedSenderKeys.has(key)) {
      if (friendsPinShareSelectedSenderKeys.size <= 1) return;
      friendsPinShareSelectedSenderKeys.delete(key);
    } else {
      friendsPinShareSelectedSenderKeys.add(key);
    }
    refreshFriendsPinShareNotification();
  }

  function buildFriendsPinShareNotificationGroups(shares) {
    const groups = new Map();
    for (const share of Array.isArray(shares) ? shares : []) {
      const username = share?.fromProfile?.wmeUsername || "A friend";
      const groupKey = String(share?.fromUid || username || Math.random());
      const pin = share?.pin || {};
      if (!groups.has(groupKey)) {
        groups.set(groupKey, {
          key: groupKey,
          username,
          avatarUrl: share?.fromProfile?.wmeAvatarUrl || "",
          avatarName: username,
          items: []
        });
      }
      groups.get(groupKey).items.push({
        id: String(share?.id || ""),
        title: String(pin.name || "Shared pin"),
        detail: pin.note ? String(pin.note) : "",
        selected: friendsPinShareSelectedIds.has(String(share?.id || ""))
      });
    }
    return Array.from(groups.values()).map((group) => ({
      ...group,
      count: group.items.length,
      selectedCount: group.items.filter((item) => item.selected).length
    }));
  }

  function refreshFriendsPinShareNotification() {
    const shares = getSortedPendingFriendsPinShares();
    syncFriendsPinShareSelection(shares);
    syncFriendsPinShareSenderFilter(shares);
    if (!shares.length) {
      renderFriendsPinShareNotification();
      return;
    }
    if (friendsPinShareNotification?.update) {
      friendsPinShareNotification.update(buildFriendsPinShareNotificationConfig(shares));
    } else {
      renderFriendsPinShareNotification();
    }
  }

  function toggleFriendsPinShareSelection(shareId) {
    const id = String(shareId || "").trim();
    if (!id) return;
    if (friendsPinShareSelectedIds.has(id)) friendsPinShareSelectedIds.delete(id);
    else friendsPinShareSelectedIds.add(id);
    refreshFriendsPinShareNotification();
  }

  function buildFriendsPinShareNotificationConfig(shares) {
    const items = Array.isArray(shares) ? shares.slice() : [];
    const multiple = items.length > 1;

    if (!multiple) {
      const share = items[0] || {};
      const username = share?.fromProfile?.wmeUsername || "A friend";
      const pin = share?.pin || {};
      return {
        variant: "pin-received",
        title: "Pin received",
        message: String(pin.name || "Shared pin"),
        meta: `From ${username}`,
        detail: pin.note ? String(pin.note) : "",
        senderFilter: null,
        chips: [],
        listEmptyMessage: "",
        list: [],
        avatarUrl: share?.fromProfile?.wmeAvatarUrl || "",
        avatarName: username,
        icon: ICONS.mapPin || ICONS.pinEye,
        actions: [
          {
            label: "Decline",
            danger: true,
            closeAfter: false,
            run: () => declineSharedPinsBatch(items)
          },
          {
            label: "Add pin",
            primary: true,
            closeAfter: false,
            run: () => acceptSharedPinsBatch(items)
          }
        ]
      };
    }

    syncFriendsPinShareSelection(items);
    syncFriendsPinShareSenderFilter(items);

    const senderMap = new Map();
    for (const share of items) {
      const key = friendsPinShareSenderKey(share);
      const username = share?.fromProfile?.wmeUsername || "A friend";
      if (!senderMap.has(key)) {
        senderMap.set(key, {
          key,
          username,
          avatarUrl: share?.fromProfile?.wmeAvatarUrl || "",
          avatarName: username,
          count: 0
        });
      }
      senderMap.get(key).count += 1;
    }

    const senders = Array.from(senderMap.values());
    const senderCount = senders.length || 1;
    const hasMultipleSenders = senderCount > 1;
    if (!hasMultipleSenders && senders[0]?.key) {
      friendsPinShareSelectedSenderKeys.clear();
      friendsPinShareSelectedSenderKeys.add(senders[0].key);
    }
    const selectedSenderCount = hasMultipleSenders
      ? senders.filter((sender) => friendsPinShareSelectedSenderKeys.has(sender.key)).length
      : senderCount;
    const visibleItems = hasMultipleSenders
      ? items.filter((share) => friendsPinShareSelectedSenderKeys.has(friendsPinShareSenderKey(share)))
      : items.slice();
    const selectedShares = visibleItems.filter((share) =>
      friendsPinShareSelectedIds.has(String(share?.id || ""))
    );
    const selectedCount = selectedShares.length;
    const addLabel = selectedCount <= 0
      ? "Add selected"
      : selectedCount === visibleItems.length
        ? `Add all ${selectedCount}`
        : `Add ${selectedCount} pin${selectedCount === 1 ? "" : "s"}`;

    return {
      variant: "pin-review",
      title: `${items.length} pins received`,
      message: `${selectedCount}/${visibleItems.length} selected`,
      meta: "",
      detail: "",
      senderFilter: hasMultipleSenders ? {
        label: selectedSenderCount === senderCount
          ? `${senderCount} senders`
          : `${selectedSenderCount} of ${senderCount} senders`,
        senders,
        selectedKeys: Array.from(friendsPinShareSelectedSenderKeys),
        onToggle: (senderKey) => toggleFriendsPinShareSenderFilter(senderKey)
      } : null,
      chips: [`${items.length} pending`],
      listEmptyMessage: hasMultipleSenders ? "No senders selected." : "",
      list: visibleItems.map((share) => {
        const username = share?.fromProfile?.wmeUsername || "A friend";
        const pin = share?.pin || {};
        const shareId = String(share?.id || "");
        return {
          id: shareId,
          title: String(pin.name || "Shared pin"),
          meta: `From ${username}`,
          detail: pin.note ? String(pin.note) : "",
          avatarUrl: share?.fromProfile?.wmeAvatarUrl || "",
          avatarName: username,
          deletable: true,
          onDelete: () => declineSharedPinsBatch([share]),
          selectable: true,
          selected: friendsPinShareSelectedIds.has(shareId)
        };
      }),
      avatarUrl: "",
      avatarName: "Friends",
      icon: ICONS.mapPin || ICONS.pinEye,
      actions: [
        {
          label: "Decline all",
          danger: true,
          closeAfter: false,
          run: () => declineSharedPinsBatch(items)
        },
        {
          label: addLabel,
          primary: true,
          disabled: selectedCount <= 0,
          closeAfter: false,
          run: () => acceptSharedPinsBatch(selectedShares)
        }
      ]
    };
  }

  function renderFriendsPinShareNotification() {
    const shares = getSortedPendingFriendsPinShares();
    syncFriendsPinShareSelection(shares);
    syncFriendsPinShareSenderFilter(shares);

    if (!shares.length) {
      friendsPinShareSelectedIds.clear();
      friendsPinShareKnownIds.clear();
      friendsPinShareSelectedSenderKeys.clear();
      friendsPinShareKnownSenderKeys.clear();
      const old = friendsPinShareNotification;
      friendsPinShareNotification = null;
      friendsActiveNotifications.delete(friendsNotificationKey("pin-share", "batch"));
      if (old?.close) old.close();
      return;
    }

    const config = buildFriendsPinShareNotificationConfig(shares);
    if (friendsPinShareNotification?.update) {
      friendsPinShareNotification.update(config);
      return;
    }

    let handle = null;
    handle = showFriendsSideNotification({
      ...config,
      onBeforeClose: () => {
        if (friendsPinShareNotification !== handle) return;
        friendsPinShareNotification = null;
        friendsPinShareNotificationItems.clear();
        friendsPinShareSelectedIds.clear();
        friendsPinShareKnownIds.clear();
        friendsPinShareSelectedSenderKeys.clear();
        friendsPinShareKnownSenderKeys.clear();
        friendsActiveNotifications.delete(friendsNotificationKey("pin-share", "batch"));
      },
      onClose: () => scheduleFriendsNotificationPositionUpdate()
    });
    friendsPinShareNotification = handle;
    friendsActiveNotifications.set(
      friendsNotificationKey("pin-share", "batch"),
      { ...handle, type: "pin-share", id: "batch" }
    );
  }

  function processFriendsNotificationQueue() {
    while (friendsNotificationQueue.length) {
      const item = friendsNotificationQueue.shift();

      if (item?.type === "pin-share") {
        const id = String(item?.id || "");
        if (id && !friendsPinShareNotificationItems.has(id)) {
          friendsPinShareNotificationItems.set(id, item.data);
        }
        continue;
      }

      const key = friendsNotificationKey(item?.type, item?.id);
      if (!item?.id || friendsActiveNotifications.has(key)) continue;

      const finish = () => {
        friendsActiveNotifications.delete(key);
        scheduleFriendsNotificationPositionUpdate();
      };

      let handle = null;

      if (item.type === "friend-request") {
        const request = item.data;
        const username = request?.fromProfile?.wmeUsername || "A WME user";

        handle = showFriendsSideNotification({
          variant: "friend-request",
          role: "alert",
          title: "New friend request",
          message: username,
          meta: "Wants to connect with you",
          avatarUrl: request?.fromProfile?.wmeAvatarUrl || "",
          avatarName: username,
          icon: ICONS.user || ICONS.friends || ICONS.person,
          actions: [
            {
              label: "Decline",
              danger: true,
              run: () => updateFriendRequestStatus(request.id, "declined")
            },
            {
              label: "Accept",
              success: true,
              run: () => updateFriendRequestStatus(request.id, "accepted")
            }
          ],
          onClose: finish
        });
      }

      if (handle) friendsActiveNotifications.set(key, { ...handle, type: item.type, id: String(item.id) });
    }

    if (friendsPinShareNotificationItems.size) renderFriendsPinShareNotification();
  }

