  function measureRcDropdownWidth(options, minWidth = 112, maxWidth = 420) {
    const labels = (Array.isArray(options) ? options : []).map((opt) => String(opt?.label ?? opt?.text ?? ''));
    let widest = 0;
    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.font = '650 12px "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif';
        for (const label of labels) widest = Math.max(widest, ctx.measureText(label).width);
      }
    } catch {}
    if (!widest) widest = Math.max(0, ...labels.map((label) => label.length * 6.8));
    // Longest label + active strip, gaps, check column, row padding and borders.
    // Keep only the space the actual option layout needs.
    return Math.max(minWidth, Math.min(maxWidth, Math.ceil(widest + 66)));
  }

  function fitRcDropdownMenu(menu, anchor, options = [], opts = {}) {
    if (!menu || !anchor) return;
    ensureRcDropdownAndPinsContextStyles();
    const pad = Number(opts.viewportPadding ?? 8);
    const vw = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
    const vh = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
    const maxWidth = Math.max(96, Math.min(Number(opts.maxWidth || 420), vw - pad * 2));
    const width = Math.min(maxWidth, Number(opts.width || measureRcDropdownWidth(options, Number(opts.minWidth || 112), maxWidth)));
    const maxHeight = Math.max(96, Math.min(Number(opts.maxHeight || 280), vh - pad * 2));

    menu.style.visibility = 'hidden';
    menu.style.opacity = '1';
    menu.style.pointerEvents = 'none';
    menu.style.position = 'fixed';
    menu.style.left = '-9999px';
    menu.style.top = '-9999px';
    menu.style.right = 'auto';
    menu.style.boxSizing = 'border-box';
    menu.style.setProperty('--wmeRcDropdownMeasuredWidth', `${Math.round(width)}px`);
    menu.style.setProperty('width', `${Math.round(width)}px`, 'important');
    menu.style.setProperty('min-width', `${Math.round(width)}px`, 'important');
    menu.style.setProperty('max-width', `${Math.round(width)}px`, 'important');
    menu.style.maxHeight = `${Math.round(maxHeight)}px`;
    menu.style.overflowX = 'hidden';
    menu.style.overflowY = menu.scrollHeight > maxHeight ? 'auto' : 'visible';
    menu.style.animation = 'none';
    menu.style.transition = 'none';
    menu.style.transform = 'none';

    const rect = anchor.getBoundingClientRect();
    const measured = menu.getBoundingClientRect();
    let left = opts.align === 'left' ? rect.left : rect.right - measured.width;
    if (left < pad) left = pad;
    if (left + measured.width > vw - pad) left = Math.max(pad, vw - pad - measured.width);
    let top = rect.bottom + Number(opts.gap ?? 6);
    if (top + measured.height > vh - pad) {
      const above = rect.top - Number(opts.gap ?? 6) - measured.height;
      top = above >= pad ? above : Math.max(pad, vh - pad - measured.height);
    }
    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.visibility = 'visible';
    menu.style.pointerEvents = 'auto';
  }

  function createRcDropdown(options, currentValue, onChange) {
    ensureRcDropdownAndPinsContextStyles();
    let optionList = Array.isArray(options) ? options.slice() : [];
    let value = currentValue;
    let menu = null;
    const menuListeners = [];

    const wrap = document.createElement('div');
    wrap.className = 'wmeRcSelect';

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'wmeRcSelectBtn';
    wrap.appendChild(btn);

    const getLabel = (v) => optionList.find((o) => String(o.value) === String(v))?.label || String(v ?? '');
    const applyPreferredWidth = () => {
      const preferredWidth = measureRcDropdownWidth(optionList);
      wrap.style.setProperty('--wmeRcSelectPreferredWidth', `${preferredWidth}px`);
      wrap.dataset.preferredWidth = String(preferredWidth);
      return preferredWidth;
    };
    const syncButton = () => {
      btn.textContent = getLabel(value);
      applyPreferredWidth();
    };

    const cleanupMenuListeners = () => {
      while (menuListeners.length) {
        try { menuListeners.pop()(); } catch {}
      }
    };
    const bindMenuListener = (target, type, handler, opts) => {
      try {
        target.addEventListener(type, handler, opts);
        menuListeners.push(() => { try { target.removeEventListener(type, handler, opts); } catch {} });
      } catch {}
    };
    const closeMenu = () => {
      cleanupMenuListeners();
      try { menu?.remove(); } catch {}
      menu = null;
      wrap.setAttribute('data-open', '0');
    };
    const onDocDown = (event) => {
      if (!menu) return;
      if (wrap.contains(event.target) || menu.contains(event.target)) return;
      closeMenu();
    };
    const applyMenuTheme = () => {
      if (!menu) return null;
      const palette = getWindowsCompactPalette();

      menu.classList.toggle('theme-light', !!palette.isLight);
      menu.classList.toggle('theme-dark', !palette.isLight);

      menu.style.setProperty('--wmeRcCompactBg', palette.bg);
      menu.style.setProperty('--wmeRcCompactFg', palette.fg);
      menu.style.setProperty('--wmeRcCompactMuted', palette.muted);
      menu.style.setProperty('--wmeRcCompactMutedSoft', palette.mutedSoft);
      menu.style.setProperty('--wmeRcCompactBorder', palette.border);
      menu.style.setProperty('--wmeRcCompactBorderStrong', palette.borderStrong);
      menu.style.setProperty('--wmeRcCompactSurface', palette.surface);
      menu.style.setProperty('--wmeRcCompactSurface2', palette.surface2);
      menu.style.setProperty('--wmeRcCompactHover', palette.hover);
      menu.style.setProperty('--wmeRcCompactPressed', palette.pressed);
      menu.style.setProperty('--wmeRcCompactSelected', palette.selected);

      return palette;
    };
    const rebuildMenu = () => {
      if (!menu) return;
      menu.innerHTML = '';
      for (const opt of optionList) {
        const active = String(opt.value) === String(value);
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'wmeRcSelectOpt wmeRcUnifiedDropdownItem wmeRcPinSetDropdownItem' + (active ? ' is-active' : '');
        item.setAttribute('role', 'option');
        item.setAttribute('aria-selected', active ? 'true' : 'false');

        const activeStrip = document.createElement('span');
        activeStrip.className = 'wmeRcPinSetDropdownActiveStrip';
        activeStrip.style.opacity = active ? '1' : '0';

        const label = document.createElement('span');
        label.className = 'wmeRcPinSetDropdownLabel wmeRcDropdownText';
        label.textContent = String(opt.label ?? '');

        const check = document.createElement('span');
        check.className = 'wmeRcPinSetDropdownCheck';
        check.style.opacity = active ? '1' : '0';
        check.innerHTML = `<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5.5 10.25 3 3 6-6.25"></path></svg>`;

        item.appendChild(activeStrip);
        item.appendChild(label);
        item.appendChild(check);
        item.addEventListener('click', (event) => {
          event.preventDefault();
          event.stopPropagation();
          const oldValue = value;
          value = opt.value;
          syncButton();
          closeMenu();
          try { onChange?.(opt.value, btn, { oldValue, option: opt, dropdown: wrap }); } catch {}
        });
        menu.appendChild(item);
      }
    };
    const positionMenu = () => {
      if (!menu) return;

      const matchTrigger =
        !!wrap.closest?.('.wmeRcBackupLocalControl') ||
        wrap.classList.contains('wmeRcMatchTriggerWidth');

      const triggerWidth = Math.max(
        1,
        Math.round(btn.getBoundingClientRect().width || wrap.getBoundingClientRect().width || 0)
      );

      fitRcDropdownMenu(menu, btn, optionList, {
        width: matchTrigger ? triggerWidth : measureRcDropdownWidth(optionList),
        maxHeight: 280,
        align: matchTrigger ? 'left' : 'right'
      });
    };
    const openMenu = () => {
      if (menu) return;
      menu = document.createElement('div');
      menu.className = 'wmeRcSelectMenu windows-design wmeRcUnifiedDropdownMenu wmeRcSoundMenuPortal wmeRcPinSetDropdownMenu';
      if (wrap.closest?.('.wmeRcBackupLocalControl') || wrap.classList.contains('wmeRcMatchTriggerWidth')) {
        menu.classList.add('wmeRcMatchTriggerMenu');
      }
      menu.setAttribute('role', 'listbox');
      menu.style.visibility = 'hidden';
      menu.style.transition = 'none';
      menu.style.animation = 'none';

      // Important: apply the final light/dark class and palette before rows are
      // built and before the portal is inserted. This prevents a dark-to-light
      // transition flash on first paint.
      applyMenuTheme();
      rebuildMenu();

      document.body.appendChild(menu);
      wrap.setAttribute('data-open', '1');
      positionMenu();
      bindMenuListener(document, 'pointerdown', onDocDown, true);
      bindMenuListener(window, 'resize', positionMenu, { passive: true });
      bindMenuListener(window, 'scroll', positionMenu, true);
      const wheel = (event) => {
        if (!menu || menu.scrollHeight <= menu.clientHeight + 1) return;
        event.preventDefault();
        event.stopPropagation();
        menu.scrollTop += Number(event.deltaY) || 0;
      };
      bindMenuListener(menu, 'wheel', wheel, { passive: false });
    };

    btn.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (menu) closeMenu(); else openMenu();
    });

    wrap.setOptions = (nextOptions, nextValue = value) => {
      optionList = Array.isArray(nextOptions) ? nextOptions.slice() : [];
      value = nextValue;
      syncButton();
      if (menu) {
        rebuildMenu();
        positionMenu();
      }
    };
    wrap.setValue = (nextValue, emit = false) => {
      const oldValue = value;
      value = nextValue;
      syncButton();
      if (menu) {
        rebuildMenu();
        positionMenu();
      }
      if (emit) {
        const opt = optionList.find((o) => String(o.value) === String(nextValue));
        try { onChange?.(nextValue, btn, { oldValue, option: opt, dropdown: wrap }); } catch {}
      }
    };
    wrap.getValue = () => value;
    wrap.closeMenu = closeMenu;
    wrap.openMenu = openMenu;
    syncButton();
    return wrap;
  }

  function getPinFolderDropdownOptions(includeCreate = true) {
    const groups = loadPinGroups();
    const options = groups.map((group) => {
      const gid = normalizeGroupId(group?.id);
      let label = String(group?.name || (gid === 'default' ? '(no folder)' : 'Folder'));
      if (group?.isSubfolder) {
        const parent = groups.find((candidate) => String(candidate?.id || '') === String(group?.parentId || ''));
        label = parent ? `${parent.name || 'Folder'} → ${label}` : label;
      }
      return { value: gid, label };
    });
    if (includeCreate) options.push({ value: '__new__', label: '+ New folder' });
    return options;
  }

  function createPinFolderDropdown(initialGroupId, onChanged, opts = {}) {
    let selected = normalizeGroupId(initialGroupId || 'default');
    const includeCreate = opts.includeCreate !== false;
    const picker = createRcDropdown(getPinFolderDropdownOptions(includeCreate), selected, (nextValue) => {
      if (nextValue === '__new__') {
        picker.setValue(selected, false);
        openGroupNameModal({
          title: 'New folder',
          placeholder: 'Name',
          okText: 'Create',
          onSubmit: (name, emoji) => {
            const id = createPinGroup(name, emoji);
            selected = normalizeGroupId(id);
            picker.setOptions(getPinFolderDropdownOptions(includeCreate), selected);
            try { onChanged?.(selected); } catch {}
          }
        });
        return;
      }
      selected = normalizeGroupId(nextValue);
      try { onChanged?.(selected); } catch {}
    });
    picker.classList.add('wmeRcFolderDropdown');
    picker.refreshFolders = () => picker.setOptions(getPinFolderDropdownOptions(includeCreate), selected);
    picker.getSelectedGroupId = () => selected;
    return picker;
  }

function gmSharedGet(key, fallback = null) {
  try {
    if (typeof GM_getValue === 'function') return GM_getValue(key, fallback);
  } catch {}
  return fallback;
}

function gmSharedSet(key, value) {
  try {
    if (typeof GM_setValue === 'function') {
      GM_setValue(key, value);
      return true;
    }
  } catch {}
  return false;
}

function gmSharedListen(key, handler) {
  try {
    if (typeof GM_addValueChangeListener === 'function') {
      return GM_addValueChangeListener(key, (_name, oldValue, newValue, remote) => {
        try { handler(newValue, oldValue, !!remote); } catch {}
      });
    }
  } catch {}
  return null;
}

function gmSharedUnlisten(id) {
  try {
    if (id != null && typeof GM_removeValueChangeListener === 'function') GM_removeValueChangeListener(id);
  } catch {}
}

/*
 * Cross-origin settings synchronization.
 * Production and beta WME have separate localStorage containers, while
 * Tampermonkey's GM storage is shared by this userscript across both hosts.
 * Pin/folder records keep using their dedicated merge engine; this layer is
 * only for preferences and UI state.
 */
const SHARED_SETTINGS_EXCLUDED_KEYS = new Set([
  CHANGELOG_SEEN_KEY,
  SHARED_PINS_STATE_KEY,
  SHARED_PINS_LOCK_KEY,
  SHARED_SETTINGS_STATE_KEY,
  SHARED_SETTINGS_LOCK_KEY,
  GOOGLE_DRIVE_CLOUD_LAST_APPLIED_KEY,
  GOOGLE_DRIVE_LOCAL_CHANGE_TS_KEY,
  `${SCRIPT_ID}:pinnedPlaces:v1`,
  `${SCRIPT_ID}:pinGroups:v1`,
  `${SCRIPT_ID}:pinGroupUi:v1`,
  `${SCRIPT_ID}:pinSyncTombstones:v1`,
  `${SCRIPT_ID}:pinGroupUiSyncUpdatedAt:v1`,
  `${SCRIPT_ID}:pinGroupOrderSyncUpdatedAt:v1`,
  `${SCRIPT_ID}:advancedClosuresOriginalIcon:v2`,
]);

let _sharedSettingsListenerId = null;
let _sharedSettingsApplying = false;
let _sharedSettingsPublishTimer = null;
let _sharedSettingsStoragePatched = false;
let _sharedSettingsNativeSetItem = null;
let _sharedSettingsNativeRemoveItem = null;
const _sharedSettingsPending = new Map();
const _sharedSettingsLocalMeta = new Map();

function isSharedUserSettingKey(rawKey) {
  const key = String(rawKey || '');
  if (!key) return false;
  if (key === 'wme_rc_permalink_settings_v1') return true;
  if (!key.startsWith(`${SCRIPT_ID}:`)) return false;
  return !SHARED_SETTINGS_EXCLUDED_KEYS.has(key);
}

function normalizeSharedSettingsState(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  const entries = {};
  const inputEntries = src.entries && typeof src.entries === 'object' ? src.entries : {};
  for (const [key, rawEntry] of Object.entries(inputEntries)) {
    if (!isSharedUserSettingKey(key) || !rawEntry || typeof rawEntry !== 'object') continue;
    const updatedAt = Math.max(0, Number(rawEntry.updatedAt) || 0);
    const deleted = rawEntry.deleted === true;
    entries[key] = {
      value: deleted ? null : String(rawEntry.value ?? ''),
      deleted,
      updatedAt,
      source: String(rawEntry.source || ''),
    };
  }
  return {
    version: 1,
    entries,
    updatedAt: Math.max(0, Number(src.updatedAt) || 0),
    source: String(src.source || ''),
  };
}

function collectLocalSharedSettings() {
  const values = new Map();
  try {
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (!isSharedUserSettingKey(key)) continue;
      values.set(String(key), localStorage.getItem(key));
    }
  } catch {}
  return values;
}

function queueSharedSettingMutation(rawKey, rawValue, deleted = false) {
  if (_sharedSettingsApplying) return;
  const key = String(rawKey || '');
  if (!isSharedUserSettingKey(key)) return;
  const updatedAt = Date.now();
  const entry = {
    value: deleted ? null : String(rawValue ?? ''),
    deleted: !!deleted,
    updatedAt,
    source: RC_INSTANCE_ID,
  };
  _sharedSettingsLocalMeta.set(key, updatedAt);
  _sharedSettingsPending.set(key, entry);
  try { if (_sharedSettingsPublishTimer) clearTimeout(_sharedSettingsPublishTimer); } catch {}
  _sharedSettingsPublishTimer = setTimeout(() => {
    _sharedSettingsPublishTimer = null;
    flushSharedSettingsPending().catch(() => {});
  }, 120);
}

async function flushSharedSettingsPending() {
  if (!_sharedSettingsPending.size) return;
  const batch = new Map(_sharedSettingsPending);
  _sharedSettingsPending.clear();

  let acquired = false;
  try { acquired = await acquireSharedLease(SHARED_SETTINGS_LOCK_KEY, 7000); } catch {}
  if (!acquired) {
    for (const [key, entry] of batch) {
      const existing = _sharedSettingsPending.get(key);
      if (!existing || Number(entry.updatedAt) >= Number(existing.updatedAt)) _sharedSettingsPending.set(key, entry);
    }
    try { if (_sharedSettingsPublishTimer) clearTimeout(_sharedSettingsPublishTimer); } catch {}
    _sharedSettingsPublishTimer = setTimeout(() => {
      _sharedSettingsPublishTimer = null;
      flushSharedSettingsPending().catch(() => {});
    }, 300);
    return;
  }

  try {
    const state = normalizeSharedSettingsState(gmSharedGet(SHARED_SETTINGS_STATE_KEY, null));
    let newest = state.updatedAt;
    for (const [key, entry] of batch) {
      const previous = state.entries[key];
      if (!previous || Number(entry.updatedAt) >= Number(previous.updatedAt)) {
        state.entries[key] = entry;
        newest = Math.max(newest, Number(entry.updatedAt) || 0);
      }
    }
    state.updatedAt = newest || Date.now();
    state.source = RC_INSTANCE_ID;
    if (!gmSharedSet(SHARED_SETTINGS_STATE_KEY, state)) throw new Error('Shared settings write failed');
  } catch {
    for (const [key, entry] of batch) {
      const existing = _sharedSettingsPending.get(key);
      if (!existing || Number(entry.updatedAt) >= Number(existing.updatedAt)) _sharedSettingsPending.set(key, entry);
    }
  } finally {
    try { releaseSharedLease(SHARED_SETTINGS_LOCK_KEY); } catch {}
  }

  if (_sharedSettingsPending.size && !_sharedSettingsPublishTimer) {
    _sharedSettingsPublishTimer = setTimeout(() => {
      _sharedSettingsPublishTimer = null;
      flushSharedSettingsPending().catch(() => {});
    }, 220);
  }
}

function refreshUiAfterSharedSettingsApply(changedKeys) {
  if (!changedKeys || !changedKeys.size) return;
  try {
    if (changedKeys.has(ENABLED_SETTING_KEY)) {
      enabled = localStorage.getItem(ENABLED_SETTING_KEY) !== '0';
      document.querySelectorAll('#wmeRcSideSwitch').forEach((sw) => {
        try {
          sw.classList.toggle('is-on', enabled);
          sw.setAttribute('aria-pressed', enabled ? 'true' : 'false');
        } catch {}
      });
      if (tinyFallbackToggleEl) {
        tinyFallbackToggleEl.querySelector('.wmeRcTinyDot')?.classList.toggle('off', !enabled);
        const txt = tinyFallbackToggleEl.querySelector('.wmeRcTinyTxt');
        if (txt) txt.textContent = enabled ? 'Right-click: ON' : 'Right-click: OFF';
      }
    }
  } catch {}
  try {
    const side = document.querySelector('.wmeRcSideWrap');
    if (side && typeof side._wmeRcRefresh === 'function') side._wmeRcRefresh();
  } catch {}
  try { renderPinsPanel(true); } catch {}
  try { renderPinsMarkers(true); } catch {}
  try { applyReminderNoticePosition(); } catch {}
  try { applyWindowsCompactRootPalette(); } catch {}
  try {
    document.dispatchEvent(new CustomEvent('wmeRcSettingsSynced', {
      detail: { keys: [...changedKeys] },
    }));
  } catch {}
}

function applySharedSettingsState(raw, initial = false) {
  const state = normalizeSharedSettingsState(raw);
  const changedKeys = new Set();
  if (!state || !state.entries) return changedKeys;
  _sharedSettingsApplying = true;
  try {
    for (const [key, entry] of Object.entries(state.entries)) {
      if (!isSharedUserSettingKey(key)) continue;
      const localTs = Number(_sharedSettingsLocalMeta.get(key) || 0);
      if (!initial && Number(entry.updatedAt) <= localTs) continue;
      const before = localStorage.getItem(key);
      if (entry.deleted) {
        if (before != null) {
          _sharedSettingsNativeRemoveItem.call(localStorage, key);
          changedKeys.add(key);
        }
      } else if (before !== String(entry.value ?? '')) {
        _sharedSettingsNativeSetItem.call(localStorage, key, String(entry.value ?? ''));
        changedKeys.add(key);
      }
      _sharedSettingsLocalMeta.set(key, Number(entry.updatedAt) || Date.now());
    }
  } catch {} finally {
    _sharedSettingsApplying = false;
  }
  if (changedKeys.size) setTimeout(() => refreshUiAfterSharedSettingsApply(changedKeys), 0);
  return changedKeys;
}

function installSharedSettingsStorageBridge() {
  if (_sharedSettingsStoragePatched) return;
  try {
    const proto = Storage.prototype;
    _sharedSettingsNativeSetItem = proto.setItem;
    _sharedSettingsNativeRemoveItem = proto.removeItem;
    proto.setItem = function(key, value) {
      const result = _sharedSettingsNativeSetItem.call(this, key, value);
      try {
        if (this === window.localStorage) queueSharedSettingMutation(key, value, false);
      } catch {}
      return result;
    };
    proto.removeItem = function(key) {
      const result = _sharedSettingsNativeRemoveItem.call(this, key);
      try {
        if (this === window.localStorage) queueSharedSettingMutation(key, null, true);
      } catch {}
      return result;
    };
    _sharedSettingsStoragePatched = true;
  } catch {}
}

function initSharedSettingsSync() {
  try {
    installSharedSettingsStorageBridge();
    if (!_sharedSettingsNativeSetItem || !_sharedSettingsNativeRemoveItem) return;

    const localValues = collectLocalSharedSettings();
    const state = normalizeSharedSettingsState(gmSharedGet(SHARED_SETTINGS_STATE_KEY, null));
    const hasSharedEntries = Object.keys(state.entries).length > 0;

    if (hasSharedEntries) applySharedSettingsState(state, true);

    const now = Date.now();
    for (const [key, value] of localValues) {
      if (hasSharedEntries && state.entries[key]) continue;
      const entry = { value: String(value ?? ''), deleted: false, updatedAt: now, source: RC_INSTANCE_ID };
      _sharedSettingsLocalMeta.set(key, now);
      _sharedSettingsPending.set(key, entry);
    }

    _sharedSettingsListenerId = gmSharedListen(SHARED_SETTINGS_STATE_KEY, (value) => {
      try { applySharedSettingsState(value, false); } catch {}
    });

    if (_sharedSettingsPending.size) {
      setTimeout(() => flushSharedSettingsPending().catch(() => {}), 80);
    }
  } catch {}
}

const DEFAULT_GOOGLE_DRIVE_BACKUP_SETTINGS = Object.freeze({
  automaticBackup: true,
  delayMs: 10000,
  backupStrategy: 'latest-restore',
  cloudSync: true,
  syncOnOpen: true,
  offlineRetry: true,
});

function normalizeGoogleDriveBackupSettings(value) {
  const src = value && typeof value === 'object' ? value : {};
  const allowedDelays = new Set([5000, 10000, 30000, 60000]);
  const allowedStrategies = new Set(['latest', 'every-change', 'latest-restore']);
  const delayMs = Number(src.delayMs);
  const backupStrategy = String(src.backupStrategy || '');
  return {
    automaticBackup: src.automaticBackup !== false,
    delayMs: allowedDelays.has(delayMs) ? delayMs : DEFAULT_GOOGLE_DRIVE_BACKUP_SETTINGS.delayMs,
    backupStrategy: allowedStrategies.has(backupStrategy) ? backupStrategy : DEFAULT_GOOGLE_DRIVE_BACKUP_SETTINGS.backupStrategy,
    cloudSync: src.cloudSync !== false,
    syncOnOpen: src.syncOnOpen !== false,
    offlineRetry: src.offlineRetry !== false,
  };
}

function loadGoogleDriveBackupSettings() {
  try {
    const shared = gmSharedGet(GOOGLE_DRIVE_BACKUP_SETTINGS_SHARED_KEY, null);
    if (shared && typeof shared === 'object') return normalizeGoogleDriveBackupSettings(shared);
  } catch {}
  try {
    return normalizeGoogleDriveBackupSettings(JSON.parse(localStorage.getItem(GOOGLE_DRIVE_BACKUP_SETTINGS_KEY) || '{}'));
  } catch {
    return { ...DEFAULT_GOOGLE_DRIVE_BACKUP_SETTINGS };
  }
}

function saveGoogleDriveBackupSettings(value, opts = {}) {
  const next = normalizeGoogleDriveBackupSettings(value);
  try { localStorage.setItem(GOOGLE_DRIVE_BACKUP_SETTINGS_KEY, JSON.stringify(next)); } catch {}
  if (opts.publish !== false) {
    try { gmSharedSet(GOOGLE_DRIVE_BACKUP_SETTINGS_SHARED_KEY, next); } catch {}
  }
  if (next.automaticBackup && opts.schedule !== false) scheduleAutomaticGoogleDriveBackup('backup-settings');
  if (next.cloudSync && opts.sync !== false) setTimeout(() => runGoogleDriveOpenSync('backup-settings').catch(() => {}), 50);
  return next;
}

async function acquireSharedLease(key, ttlMs = 30000) {
  const now = Date.now();
  const current = gmSharedGet(key, null);
  if (current && current.owner && current.owner !== RC_INSTANCE_ID && Number(current.expiresAt) > now) return false;
  const lease = { owner: RC_INSTANCE_ID, expiresAt: now + Math.max(5000, Number(ttlMs) || 30000) };
  gmSharedSet(key, lease);
  await new Promise(resolve => setTimeout(resolve, 24 + Math.floor(Math.random() * 28)));
  const verify = gmSharedGet(key, null);
  return !!verify && verify.owner === RC_INSTANCE_ID;
}

function releaseSharedLease(key) {
  try {
    const current = gmSharedGet(key, null);
    if (current && current.owner === RC_INSTANCE_ID) gmSharedSet(key, { owner: '', expiresAt: 0 });
  } catch {}
}

function readGoogleDriveSessionAuth() {
  try {
    const token = String(sessionStorage.getItem(GOOGLE_DRIVE_SESSION_TOKEN_KEY) || '');
    const expiresAt = Number(sessionStorage.getItem(GOOGLE_DRIVE_SESSION_EXPIRY_KEY) || 0);
    const scope = String(sessionStorage.getItem(GOOGLE_DRIVE_SESSION_SCOPE_KEY) || '');
    if (token && Number.isFinite(expiresAt) && expiresAt > Date.now() + 15000) return { token, expiresAt, scope };
    sessionStorage.removeItem(GOOGLE_DRIVE_SESSION_TOKEN_KEY);
    sessionStorage.removeItem(GOOGLE_DRIVE_SESSION_EXPIRY_KEY);
    sessionStorage.removeItem(GOOGLE_DRIVE_SESSION_SCOPE_KEY);
  } catch {}
  return { token: '', expiresAt: 0, scope: '' };
}

function saveGoogleDriveSessionAuth(token, expiresAt, scope = '') {
  try {
    if (token && Number(expiresAt) > Date.now()) {
      sessionStorage.setItem(GOOGLE_DRIVE_SESSION_TOKEN_KEY, String(token));
      sessionStorage.setItem(GOOGLE_DRIVE_SESSION_EXPIRY_KEY, String(Number(expiresAt)));
      sessionStorage.setItem(GOOGLE_DRIVE_SESSION_SCOPE_KEY, String(scope || ''));
    } else {
      sessionStorage.removeItem(GOOGLE_DRIVE_SESSION_TOKEN_KEY);
      sessionStorage.removeItem(GOOGLE_DRIVE_SESSION_EXPIRY_KEY);
      sessionStorage.removeItem(GOOGLE_DRIVE_SESSION_SCOPE_KEY);
    }
  } catch {}
}

