  function _syncTimestamp(value, fallback = 0) {
    const n = Number(value);
    return Number.isFinite(n) && n > 0 ? n : Number(fallback) || 0;
  }

  function _syncEntityHash(entity) {
    try {
      const clone = { ...(entity || {}) };
      delete clone._syncUpdatedAt;
      return JSON.stringify(clone);
    } catch { return ''; }
  }

  function _loadPinSyncTombstones() {
    try {
      const raw = JSON.parse(localStorage.getItem(PIN_SYNC_TOMBSTONES_KEY) || '{}');
      return {
        pins: raw && typeof raw.pins === 'object' ? raw.pins : {},
        groups: raw && typeof raw.groups === 'object' ? raw.groups : {}
      };
    } catch { return { pins: {}, groups: {} }; }
  }

  function _savePinSyncTombstones(value) {
    try {
      const now = Date.now();
      const maxAge = 30 * 86400000;
      const clean = { pins: {}, groups: {} };
      for (const kind of ['pins', 'groups']) {
        const src = value && typeof value[kind] === 'object' ? value[kind] : {};
        for (const [id, ts] of Object.entries(src)) {
          const n = _syncTimestamp(ts);
          if (id && n && now - n < maxAge) clean[kind][id] = n;
        }
      }
      localStorage.setItem(PIN_SYNC_TOMBSTONES_KEY, JSON.stringify(clean));
      return clean;
    } catch { return value || { pins: {}, groups: {} }; }
  }

  function _scheduleSharedPinsPublish() {
    if (_syncApplyingRemote) return;
    try { if (_sharedPinsPublishTimer) clearTimeout(_sharedPinsPublishTimer); } catch {}
    _sharedPinsPublishTimer = setTimeout(() => {
      _sharedPinsPublishTimer = null;
      publishSharedPinsState();
    }, 450);
  }

  function publishSharedPinsState() {
    try {
      const snapshot = {
        v: 1,
        origin: RC_INSTANCE_ID,
        updatedAt: Date.now(),
        pins: loadPins().map(p => ({ ...p })),
        groups: loadPinGroups().map(g => ({ ...g })),
        groupUi: { ...loadPinGroupUi() },
        groupUiUpdatedAt: _syncTimestamp(localStorage.getItem(PIN_GROUP_UI_SYNC_TS_KEY)),
        groupOrder: loadPinGroups().map(g => String(g.id)),
        groupOrderUpdatedAt: _syncTimestamp(localStorage.getItem(PIN_GROUP_ORDER_SYNC_TS_KEY)),
        tombstones: _loadPinSyncTombstones()
      };
      gmSharedSet(SHARED_PINS_STATE_KEY, snapshot);
    } catch {}
  }

  function _mergeTimestampMaps(a, b) {
    const out = { ...(a || {}) };
    for (const [id, ts] of Object.entries(b || {})) {
      if (_syncTimestamp(ts) > _syncTimestamp(out[id])) out[id] = _syncTimestamp(ts);
    }
    return out;
  }

  function mergeSharedPinsState(remote) {
    if (!remote || remote.origin === RC_INSTANCE_ID || !Array.isArray(remote.pins) || !Array.isArray(remote.groups)) return false;
    let changed = false;
    const localTombs = _loadPinSyncTombstones();
    const remoteTombs = remote.tombstones && typeof remote.tombstones === 'object'
      ? { pins: remote.tombstones.pins || {}, groups: remote.tombstones.groups || {} }
      : { pins: {}, groups: {} };
    const mergedTombs = {
      pins: _mergeTimestampMaps(localTombs.pins, remoteTombs.pins),
      groups: _mergeTimestampMaps(localTombs.groups, remoteTombs.groups)
    };
    if (JSON.stringify(mergedTombs) !== JSON.stringify(localTombs)) changed = true;

    const localPins = new Map(loadPins().map(p => [String(p.id), { ...p }]));
    for (const raw of remote.pins) {
      if (!raw || !raw.id) continue;
      const id = String(raw.id);
      const remoteTs = _syncTimestamp(raw._syncUpdatedAt, remote.updatedAt);
      const local = localPins.get(id);
      const localTs = _syncTimestamp(local?._syncUpdatedAt);
      const deletedTs = _syncTimestamp(mergedTombs.pins[id]);
      if (remoteTs > Math.max(localTs, deletedTs)) {
        localPins.set(id, { ...raw, id, _syncUpdatedAt: remoteTs });
        changed = true;
      }
    }
    for (const [id, tsRaw] of Object.entries(mergedTombs.pins)) {
      const ts = _syncTimestamp(tsRaw);
      const local = localPins.get(id);
      if (local && ts > _syncTimestamp(local._syncUpdatedAt)) {
        localPins.delete(id);
        changed = true;
      }
    }

    const localGroups = new Map(loadPinGroups().map(g => [String(g.id), { ...g }]));
    for (const raw of remote.groups) {
      if (!raw || !raw.id) continue;
      const id = String(raw.id);
      const remoteTs = _syncTimestamp(raw._syncUpdatedAt, remote.updatedAt);
      const local = localGroups.get(id);
      const localTs = _syncTimestamp(local?._syncUpdatedAt);
      const deletedTs = _syncTimestamp(mergedTombs.groups[id]);
      if (remoteTs > Math.max(localTs, deletedTs)) {
        localGroups.set(id, { ...raw, id, _syncUpdatedAt: remoteTs });
        changed = true;
      }
    }
    for (const [id, tsRaw] of Object.entries(mergedTombs.groups)) {
      if (id === 'default') continue;
      const ts = _syncTimestamp(tsRaw);
      const local = localGroups.get(id);
      if (local && ts > _syncTimestamp(local._syncUpdatedAt)) {
        localGroups.delete(id);
        changed = true;
      }
    }

    const localUiTs = _syncTimestamp(localStorage.getItem(PIN_GROUP_UI_SYNC_TS_KEY));
    const remoteUiTs = _syncTimestamp(remote.groupUiUpdatedAt, remote.updatedAt);
    const useRemoteUi = remote.groupUi && typeof remote.groupUi === 'object' && remoteUiTs > localUiTs;
    if (useRemoteUi) changed = true;

    const localOrderTs = _syncTimestamp(localStorage.getItem(PIN_GROUP_ORDER_SYNC_TS_KEY));
    const remoteOrderTs = _syncTimestamp(remote.groupOrderUpdatedAt, remote.updatedAt);
    const useRemoteOrder = Array.isArray(remote.groupOrder) && remoteOrderTs > localOrderTs;
    if (useRemoteOrder) changed = true;

    if (!changed) return false;
    _syncApplyingRemote = true;
    try {
      _savePinSyncTombstones(mergedTombs);
      let mergedGroupsArray = Array.from(localGroups.values());
      if (useRemoteOrder) {
        const orderIndex = new Map(remote.groupOrder.map((id, index) => [String(id), index]));
        mergedGroupsArray.sort((a, b) => {
          const aid = String(a?.id || '');
          const bid = String(b?.id || '');
          if (aid === 'default') return 1;
          if (bid === 'default') return -1;
          return (orderIndex.has(aid) ? orderIndex.get(aid) : Number.MAX_SAFE_INTEGER) - (orderIndex.has(bid) ? orderIndex.get(bid) : Number.MAX_SAFE_INTEGER);
        });
      }
      savePinGroups(normalizePinGroupOrder(mergedGroupsArray));
      savePins(Array.from(localPins.values()));
      if (useRemoteOrder) localStorage.setItem(PIN_GROUP_ORDER_SYNC_TS_KEY, String(remoteOrderTs));
      if (useRemoteUi) {
        loadPinGroupUi._cache = { ...remote.groupUi };
        localStorage.setItem(PIN_GROUP_UI_KEY, JSON.stringify(loadPinGroupUi._cache));
        localStorage.setItem(PIN_GROUP_UI_SYNC_TS_KEY, String(remoteUiTs));
      }
      _flushPinsSave();
      _refreshMapPinsPanelLive(true);
    } finally {
      _syncApplyingRemote = false;
    }
    // The tab where the edit originated already schedules the Drive upload.
    // Reset this tab's watcher baseline so a remotely applied sync does not
    // create a second sequential upload of the same pin change.
    _automaticDriveBackupLastObservedHash = simpleStringHash(makeAutomaticBackupStateHash());
    setTimeout(() => publishSharedPinsState(), 80);
    return true;
  }

  function initSharedPinsSync() {
    try {
      const initial = gmSharedGet(SHARED_PINS_STATE_KEY, null);
      if (initial) mergeSharedPinsState(initial);
      _sharedPinsListenerId = gmSharedListen(SHARED_PINS_STATE_KEY, (value) => {
        try { mergeSharedPinsState(value); } catch {}
      });
      setTimeout(() => publishSharedPinsState(), 250);
    } catch {}
  }

  function loadPinGroupUi() {
    try {
      if (loadPinGroupUi._cache) return loadPinGroupUi._cache;
      const raw = localStorage.getItem(PIN_GROUP_UI_KEY);
      const obj = JSON.parse(raw || "{}");
      const out = (obj && typeof obj === "object") ? obj : {};
      loadPinGroupUi._cache = out;
      return out;
    } catch {
      loadPinGroupUi._cache = {};
      return {};
    }
  }
  loadPinGroupUi._cache = null;

  function savePinGroupUi(ui) {
    try {
      const out = (ui && typeof ui === "object") ? ui : {};
      loadPinGroupUi._cache = out;
      if (!_syncApplyingRemote) localStorage.setItem(PIN_GROUP_UI_SYNC_TS_KEY, String(Date.now()));

      if (savePinGroupUi._t) clearTimeout(savePinGroupUi._t);
      savePinGroupUi._t = setTimeout(() => {
        try { localStorage.setItem(PIN_GROUP_UI_KEY, JSON.stringify(loadPinGroupUi._cache || {})); } catch {}
        savePinGroupUi._t = null;
        if (!_syncApplyingRemote) {
          _scheduleSharedPinsPublish();
          scheduleAutomaticGoogleDriveBackup('folder-ui-change');
        }
      }, 120);
    } catch {}
  }
  savePinGroupUi._t = null;

  function isGroupCollapsed(gid) {
    try {
      const ui = loadPinGroupUi();
      return !!(ui && ui[String(gid)] && ui[String(gid)].collapsed);
    } catch { return false; }
  }
  function setGroupCollapsed(gid, collapsed) {
    try {
      const id = String(gid);
      const ui = loadPinGroupUi();
      ui[id] = { ...(ui[id] || {}), collapsed: !!collapsed };
      savePinGroupUi(ui);
    } catch {}
  }

  function _uid() {
    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  }

  function loadPinGroups() {
    try {
      if (_pinGroupsMem && Array.isArray(_pinGroupsMem)) return _pinGroupsMem;
      const raw = localStorage.getItem(PIN_GROUPS_KEY);
      _pinGroupsLastJson = (typeof raw === "string") ? raw : _pinGroupsLastJson;
      const arr = JSON.parse(raw || "[]");
      const groups = Array.isArray(arr) ? arr : [];
      if (!groups.some(g => g && g.id === "default")) {
        groups.push({ id: "default", name: "(no folder)", emoji: "" });
      }
      try {
        const def = groups.find(g => g && g.id === "default");
        if (def && (String(def.name || "").trim() === "Default" || !String(def.name || "").trim())) def.name = "(no folder)";
      } catch {}

      const cleanGroups = groups
        .filter(g => g && typeof g.id === "string" && typeof g.name === "string" && g.id.trim())
        .map(g => ({
          id: String(g.id),
          name: String(g.name).trim() || "Group",
          emoji: (typeof g.emoji === "string") ? String(g.emoji) : "",
          parentId: (String(g.id) === "default") ? "" : String(g.parentId || "default").trim() || "default",
          isSubfolder: !!g.isSubfolder,
          _syncUpdatedAt: _syncTimestamp(g._syncUpdatedAt, 1),
        }));

      const byId = new Map(cleanGroups.map(g => [String(g.id), g]));
      const resolveTopLevelGroupId = (gid) => {
        let currentId = String(gid || "default") || "default";
        const seen = new Set();
        while (currentId && currentId !== "default" && !seen.has(currentId)) {
          seen.add(currentId);
          const current = byId.get(currentId);
          if (!current) return "default";
          if (!current.isSubfolder) return current.id;
          currentId = String(current.parentId || "default") || "default";
        }
        return "default";
      };

      const flatGroups = [];
      const seenIds = new Set();
      for (const g of cleanGroups) {
        if (!g) continue;
        if (g.id === "default") {
          if (!seenIds.has("default")) {
            flatGroups.push({ id: "default", name: g.name || "(no folder)", emoji: g.emoji || "", parentId: "", isSubfolder: false, _syncUpdatedAt: _syncTimestamp(g._syncUpdatedAt, 1) });
            seenIds.add("default");
          }
          continue;
        }
        if (g.isSubfolder) continue;
        if (seenIds.has(g.id)) continue;
        flatGroups.push({ ...g, parentId: "default", isSubfolder: false });
        seenIds.add(g.id);
      }
      if (!seenIds.has("default")) flatGroups.push({ id: "default", name: "(no folder)", emoji: "", parentId: "", isSubfolder: false, _syncUpdatedAt: 1 });
      const orderedFlatGroups = normalizePinGroupOrder(flatGroups);

      // Cache groups before touching pins. This breaks the previous
      // loadPins -> normalizeGroupId -> loadPinGroups -> loadPins cycle.
      _pinGroupsMem = orderedFlatGroups;
      _pinGroupSyncBaseline = new Map(orderedFlatGroups.map(g => [String(g.id), { hash: _syncEntityHash(g), updatedAt: _syncTimestamp(g._syncUpdatedAt) }]));

      const migratePins = (pins) => {
        let changed = false;
        const migrated = (Array.isArray(pins) ? pins : []).map((p) => {
          if (!p || typeof p !== "object") return p;
          const oldId = String(p.groupId || "default") || "default";
          const nextId = resolveTopLevelGroupId(oldId);
          if (nextId !== oldId) {
            changed = true;
            return { ...p, groupId: nextId };
          }
          return p;
        });
        return { changed, migrated };
      };

      // Migrate old subfolder/orphaned IDs without calling loadPins while
      // groups are still initializing. This keeps both memory and storage safe.
      try {
        if (_pinsMem && Array.isArray(_pinsMem)) {
          const { changed, migrated } = migratePins(_pinsMem);
          if (changed) savePins(migrated);
        } else {
          const pinsRaw = localStorage.getItem(PIN_KEY);
          const pinsArr = JSON.parse(pinsRaw || "[]");
          if (Array.isArray(pinsArr)) {
            const { changed, migrated } = migratePins(pinsArr);
            if (changed) {
              const json = JSON.stringify(migrated);
              localStorage.setItem(PIN_KEY, json);
              _pinsLastJson = json;
            }
          }
        }
      } catch {}

      const hadSubfolders = cleanGroups.some(g => g && g.id !== "default" && g.isSubfolder);
      if (hadSubfolders) savePinGroups(orderedFlatGroups);
      return _pinGroupsMem;
    } catch {
      _pinGroupsMem = [{ id: "default", name: "(no folder)", emoji: "" }];
      return _pinGroupsMem;
    }
  }

  function savePinGroups(groups) {
    try {
      const now = Date.now();
      const previousOrder = Array.isArray(_pinGroupsMem) ? _pinGroupsMem.map(g => String(g?.id || '')).join('|') : '';
      const incoming = normalizePinGroupOrder(Array.isArray(groups) ? groups : []);
      const next = incoming.map((raw) => {
        const g = { ...(raw || {}) };
        const id = String(g.id || '').trim();
        if (!id) return null;
        const baseline = _pinGroupSyncBaseline.get(id);
        const hash = _syncEntityHash(g);
        const changed = !baseline || baseline.hash !== hash;
        g._syncUpdatedAt = _syncApplyingRemote
          ? _syncTimestamp(g._syncUpdatedAt, now)
          : (changed ? now : _syncTimestamp(g._syncUpdatedAt, baseline?.updatedAt || now));
        return g;
      }).filter(Boolean);

      if (!_syncApplyingRemote) {
        const tombs = _loadPinSyncTombstones();
        const nextIds = new Set(next.map(g => String(g.id)));
        for (const id of _pinGroupSyncBaseline.keys()) {
          if (id !== 'default' && !nextIds.has(id)) tombs.groups[id] = now;
        }
        _savePinSyncTombstones(tombs);
      }

      const nextOrder = next.map(g => String(g?.id || '')).join('|');
      if (!_syncApplyingRemote && previousOrder && previousOrder !== nextOrder) {
        try { localStorage.setItem(PIN_GROUP_ORDER_SYNC_TS_KEY, String(now)); } catch {}
      }
      _pinGroupsMem = next;
      _pinGroupSyncBaseline = new Map(next.map(g => [String(g.id), { hash: _syncEntityHash(g), updatedAt: _syncTimestamp(g._syncUpdatedAt) }]));
      try { _refreshMapPinsPanelLive(true); } catch {}
      if (_pinGroupsSaveTimer) clearTimeout(_pinGroupsSaveTimer);
      _pinGroupsSaveTimer = setTimeout(() => {
        try {
          const json = JSON.stringify(_pinGroupsMem || []);
          if (json !== _pinGroupsLastJson) {
            localStorage.setItem(PIN_GROUPS_KEY, json);
            _pinGroupsLastJson = json;
          }
        } catch {}
        _pinGroupsSaveTimer = null;
        if (!_syncApplyingRemote) {
          _scheduleSharedPinsPublish();
          scheduleAutomaticGoogleDriveBackup('folder-change');
        }
      }, 120);
    } catch {}
  }

  function getGroupName(id) {
    const gid = String(id || "default");
    const groups = loadPinGroups();
    const g = groups.find(x => x && x.id === gid);
    return g ? g.name : (gid === "default" ? "(no folder)" : "Group");
  }

  function setDefaultGroupName(name) {
    const nm = String(name || "").trim() || "(no folder)";
    const groups = loadPinGroups();
    const idx = groups.findIndex(g => g && g.id === "default");
    if (idx >= 0) groups[idx] = { ...groups[idx], name: nm };
    else groups.unshift({ id: "default", name: nm, emoji: "" });
    savePinGroups(groups);
  }

  function normalizeGroupParentId(id) {
    const pid = String(id || "").trim();
    if (!pid || pid === "default") return "default";
    const groups = loadPinGroups();
    return groups.some(g => g && g.id === pid) ? pid : "default";
  }

  function getChildPinGroups(parentId) {
    return [];
  }
  function canCreateAnotherSubfolder(parentId) {
    return false;
  }

  function getDirectSubfolderCount(parentId) {
    return 0;
  }

  function getGroupDepth(groupId) {
    const gid = String(groupId || "default") || "default";
    if (!gid || gid === "default") return 0;
    const groups = loadPinGroups();
    let depth = 0;
    let current = groups.find(g => g && String(g.id) === gid) || null;
    const seen = new Set();
    while (current && current.id && current.id !== "default") {
      const cid = String(current.id);
      if (seen.has(cid)) break;
      seen.add(cid);
      depth += 1;
      const pid = String(current.parentId || "default") || "default";
      if (!pid || pid === "default") break;
      current = groups.find(g => g && String(g.id) === pid) || null;
    }
    return depth;
  }

  function canCreateSubfolderAtParent(parentId) {
    return false;
  }


  function normalizeGroupId(id) {
    const gid = String(id || "default") || "default";
    const groups = loadPinGroups();
    if (groups.some(g => g && g.id === gid)) return gid;
    return "default";
  }

  function getCurrentGroupFilter() {
    try {
      const v = localStorage.getItem(PIN_GROUP_FILTER_KEY);
      if (!v || v === "all") return "all";
      return normalizeGroupId(v);
    } catch {
      return "all";
    }
  }

  function setCurrentGroupFilter(id) {
    try {
      const v = (id == null || id === "all") ? "all" : normalizeGroupId(id);
      localStorage.setItem(PIN_GROUP_FILTER_KEY, v);
    } catch {}
  }

  function getLastGroup() {
    try {
      const v = localStorage.getItem(PIN_LAST_GROUP_KEY);
      if (!v) return "default";
      return normalizeGroupId(v);
    } catch { return "default"; }
  }

  function setLastGroup(id) {
    try { localStorage.setItem(PIN_LAST_GROUP_KEY, normalizeGroupId(id)); } catch {}
  }

  function createPinGroup(name, emoji) {
    const nm = String(name || "").trim();
    if (!nm) return "default";
    const groups = loadPinGroups();
    const id = _uid();
    groups.push({ id, name: nm, emoji: (typeof emoji === 'string') ? emoji : '' });
    savePinGroups(groups);
    return id;
  }


function getNextPinNumber(pins) {
  let max = 0;
  try {
    for (const p of (pins || [])) {
      const name = String(p && p.name ? p.name : "");
      const m = /^Pin\s*#\s*(\d+)/i.exec(name);
      if (m) {
        const n = Number(m[1]) || 0;
        if (n > max) max = n;
      }
    }
  } catch {}
  return max + 1;
}


