function getLiveSelectedPinIds() {
  const existing = new Set(loadPins().map((pin) => String(pin?.id || "")).filter(Boolean));
  for (const id of Array.from(pinsMultiSelected)) {
    if (!existing.has(String(id))) pinsMultiSelected.delete(String(id));
  }
  if (pinsMultiSelected.size === 0) pinsMultiSelectionActive = false;
  return Array.from(pinsMultiSelected);
}

function syncPinsMultiSelectionDom() {
  try {
    if (!pinsPanelEl) return;
    pinsPanelEl.querySelectorAll(".wmeRcPinRow[data-pin-id]").forEach((row) => {
      const selected = pinsMultiSelected.has(String(row.dataset.pinId || ""));
      row.classList.toggle("is-multi-selected", selected);
      const box = row.querySelector(".wmeRcPinSelectBox");
      if (box) box.classList.toggle("on", selected);
    });
  } catch {}
}

function togglePinMultiSelection(pinId) {
  const id = String(pinId || "");
  if (!id) return;
  if (pinsMultiSelected.has(id)) pinsMultiSelected.delete(id);
  else pinsMultiSelected.add(id);
  // The selection process exists only while at least one pin remains selected.
  pinsMultiSelectionActive = pinsMultiSelected.size > 0;
  syncPinsMultiSelectionDom();
}

function clearPinMultiSelection(stopProcess = true) {
  const hadSelection = pinsMultiSelected.size > 0;
  pinsMultiSelected.clear();
  if (stopProcess) pinsMultiSelectionActive = false;
  if (hadSelection) syncPinsMultiSelectionDom();
}

function ensurePinsMultiSelectionOutsideDismiss() {
  if (pinsMultiSelectionOutsideBound) return;
  pinsMultiSelectionOutsideBound = true;
  document.addEventListener("pointerdown", (event) => {
    try {
      if (!pinsMultiSelectionActive && !pinsMultiSelected.size) return;
      const target = event && event.target;
      if (pinsPanelEl && target && pinsPanelEl.contains(target)) return;
      clearPinMultiSelection(true);
    } catch {}
  }, true);
}
