  function playReminderSoundOnce(soundId, opts = {}) {
    const nowMs = Date.now();
    const force = opts && opts.force === true;
    if (!force && (nowMs - lastBellAt < 900)) return;
    lastBellAt = nowMs;

    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;

      const ctx = playReminderSoundOnce._ctx || (playReminderSoundOnce._ctx = new AudioCtx());
      try { if (ctx.state === "suspended") ctx.resume(); } catch {}

      const id = normalizeReminderSoundId((typeof soundId === "string" ? soundId : "") || getReminderSoundId());
      if (id === "mute") return;

      const t0 = ctx.currentTime + 0.012;
      const master = ctx.createGain();
      master.gain.setValueAtTime(0.72, t0);
      master.connect(ctx.destination);

      const tone = (freq, offset, duration, peak = 0.12, type = "sine", endFreq = null) => {
        const startAt = t0 + Math.max(0, Number(offset) || 0);
        const dur = Math.max(0.06, Number(duration) || 0.3);
        const gain = ctx.createGain();
        const osc = ctx.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(Math.max(40, Number(freq) || 440), startAt);
        if (Number.isFinite(Number(endFreq)) && Number(endFreq) > 0) {
          try { osc.frequency.exponentialRampToValueAtTime(Number(endFreq), startAt + dur); } catch {}
        }
        gain.gain.setValueAtTime(0.0001, startAt);
        gain.gain.exponentialRampToValueAtTime(Math.max(0.001, peak), startAt + Math.min(0.018, dur * 0.12));
        gain.gain.exponentialRampToValueAtTime(0.0001, startAt + dur);
        osc.connect(gain);
        gain.connect(master);
        osc.start(startAt);
        osc.stop(startAt + dur + 0.03);
      };

      const bell = (base, offset = 0, duration = 0.85, peak = 0.11) => {
        tone(base, offset, duration, peak, "sine", base * 0.985);
        tone(base * 1.5, offset + 0.004, duration * 0.72, peak * 0.46, "sine", base * 1.47);
        tone(base * 2.01, offset + 0.008, duration * 0.48, peak * 0.22, "triangle", base * 1.96);
      };

      switch (id) {
        case "bright":
          bell(1046.5, 0, 0.52, 0.10);
          tone(1568, 0.03, 0.38, 0.035, "sine", 1480);
          break;
        case "double":
          bell(880, 0, 0.55, 0.105);
          bell(1046.5, 0.29, 0.62, 0.10);
          break;
        case "warm":
          bell(523.25, 0, 1.18, 0.12);
          tone(659.25, 0.05, 0.96, 0.055, "sine", 640);
          break;
        case "glass":
          tone(1318.5, 0, 0.72, 0.09, "sine", 1240);
          tone(1975.5, 0.006, 0.54, 0.045, "sine", 1840);
          tone(2637, 0.012, 0.36, 0.022, "sine", 2440);
          break;
        case "pulse":
          tone(659.25, 0, 0.22, 0.09, "sine", 622);
          tone(698.46, 0.24, 0.22, 0.08, "sine", 659);
          tone(783.99, 0.48, 0.30, 0.085, "sine", 740);
          break;
        case "attention":
          bell(659.25, 0, 0.48, 0.105);
          bell(783.99, 0.34, 0.62, 0.11);
          break;
        case "radar":
          tone(1568, 0, 0.48, 0.085, "sine", 1046.5);
          tone(1046.5, 0.27, 0.42, 0.045, "sine", 783.99);
          break;
        case "gentle":
        default:
          bell(659.25, 0, 0.82, 0.10);
          bell(783.99, 0.18, 0.72, 0.075);
          break;
      }
    } catch {}
  }


