  function showPinSendNotification(config = {}) {
    try {
      const sent = Math.max(0, Number(config.sent || 0));
      const failed = Math.max(0, Number(config.failed || 0));
      const recipient = String(config.recipient || "").trim();
      const recipients = Array.isArray(config.recipients)
        ? config.recipients.map((value) => String(value || "").trim()).filter(Boolean)
        : [];
      const errorMessage = String(config.error?.message || config.error || "").trim();
      const total = sent + failed;
      const isSuccess = sent > 0 && failed === 0;
      const isPartial = sent > 0 && failed > 0;

      let title = "Pin not sent";
      let message = errorMessage || "The pin could not be sent.";
      let meta = "Nothing was delivered.";
      let icon = ICONS.send || ICONS.mapPin || ICONS.friends;

      if (isSuccess) {
        title = sent === 1 ? "Pin sent" : "Pins sent";
        if (recipient) {
          message = sent === 1
            ? `Sent to ${recipient}`
            : `${sent} pins sent to ${recipient}`;
        } else if (recipients.length === 1) {
          message = `Sent to ${recipients[0]}`;
        } else {
          message = `Sent to ${sent} ${sent === 1 ? "friend" : "friends"}`;
        }
        meta = "Delivered successfully.";
        icon = ICONS.check || icon;
      } else if (isPartial) {
        title = "Pin partially sent";
        message = `${sent} sent · ${failed} failed`;
        meta = errorMessage || `Completed ${sent} of ${total} deliveries.`;
      }

      const handle = showFriendsSideNotification({
        title,
        icon,
        message,
        meta,
        detail: (!isSuccess && errorMessage && errorMessage !== message) ? errorMessage : ""
      });
      const lifetime = isSuccess ? 3000 : 5200;
      setTimeout(() => {
        try { handle?.close?.(); } catch {}
      }, lifetime);
      return handle;
    } catch (error) {
      try { console.error(`${SCRIPT_NAME}: pin-send notification failed`, error); } catch {}
      return null;
    }
  }


