function applySolidDangerButtonBehavior(button) {
  if (!button || button.dataset.wmeRcSolidDangerBound === "1") return button;
  button.dataset.wmeRcSolidDangerBound = "1";

  const paint = (state = "base") => {
    const color = state === "hover"
      ? "#df372a"
      : state === "active"
        ? "#d53225"
        : "#d92d20";

    try {
      button.style.setProperty("background", color, "important");
      button.style.setProperty("background-color", color, "important");
      button.style.setProperty("background-image", "none", "important");
      button.style.setProperty("border", "0", "important");
      button.style.setProperty("border-color", "transparent", "important");
      button.style.setProperty("color", "#ffffff", "important");
      button.style.setProperty("-webkit-text-fill-color", "#ffffff", "important");
      button.style.setProperty("box-shadow", "none", "important");
      button.style.setProperty("text-shadow", "none", "important");
      button.style.setProperty("filter", "none", "important");
      button.style.setProperty("transform", "none", "important");
    } catch {}
  };

  paint("base");
  button.addEventListener("pointerenter", () => paint("hover"));
  button.addEventListener("pointerleave", () => paint("base"));
  button.addEventListener("pointerdown", () => paint("active"));
  button.addEventListener("pointerup", () => paint("hover"));
  button.addEventListener("pointercancel", () => paint("base"));
  button.addEventListener("blur", () => paint("base"));
  return button;
}

