function updatePin(pinId, patch) {
  const pins = loadPins();
  const i = pins.findIndex((p) => p.id === String(pinId));
  if (i < 0) return;
  pins[i] = { ...pins[i], ...patch };
  try {
    if (patch && Object.prototype.hasOwnProperty.call(patch, 'reminderAt')) {
      clearFiredKeysForPin(pinId);
    } else if (patch && patch.reminderDone === false) {
      clearFiredKeysForPin(pinId);
    }
  } catch {}

  savePins(pins);
  try {
    const p = pins.find(x => x && x.id === String(pinId));
    if (p) scheduleReminderTimer(p);
    else clearReminderTimer(pinId);
  } catch {}
  renderPinsPanel();
  try { renderPinsMarkers(); } catch {}
  try {
    const preview = _wmeRcPinNotePreviewEl;
    if (preview && String(preview.dataset.pinId || "") === String(pinId) && preview.classList.contains("show")) {
      const latestNote = getPinPanelPreviewNote(pinId);
      if (latestNote) showPinNotePreview(pinId);
      else hidePinNotePreview(0);
    }
  } catch {}
  startReminderLoop();
}

