  function selectEntireStreetByName(segId) {
    const targetName = getStreetNameForSegmentId(segId);
    if (!targetName || String(targetName).startsWith("(")) {
      toast("This segment has no usable street name.");
      closeAllMenus();
      return;
    }

    const targetKey = normalizeStreetNameForSelection(targetName);
    const matchIds = [];

    for (const segment of getAllLoadedSegmentsW()) {
      const id = segIdFromW(segment);
      if (!Number.isFinite(id)) continue;
      const candidateName = getStreetNameForSegmentId(id);
      if (normalizeStreetNameForSelection(candidateName) === targetKey) {
        matchIds.push(id);
      }
    }

    const uniqueIds = [...new Set(matchIds)];
    if (!uniqueIds.length) {
      toast(`No loaded segments found for “${targetName}”.`);
      closeAllMenus();
      return;
    }

    setSelectionToSegmentIds(uniqueIds);
    toast(`Selected ${uniqueIds.length} loaded segment${uniqueIds.length === 1 ? "" : "s"} named “${targetName}”.`);
    closeAllMenus();
  }

