  function normalizeNativeActionText(value) {
    return String(value || "")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }

  function getDeepNativeRoots() {
    const roots = [document];
    const seen = new Set();
    for (let i = 0; i < roots.length; i++) {
      const root = roots[i];
      if (!root || seen.has(root)) continue;
      seen.add(root);
      let nodes = [];
      try { nodes = Array.from(root.querySelectorAll("*")); } catch {}
      for (const node of nodes) {
        try {
          if (node.shadowRoot && !seen.has(node.shadowRoot)) roots.push(node.shadowRoot);
        } catch {}
      }
    }
    return Array.from(seen);
  }

  function deepNativeQueryAll(selector) {
    const out = [];
    const seen = new Set();
    for (const root of getDeepNativeRoots()) {
      let nodes = [];
      try { nodes = Array.from(root.querySelectorAll(selector)); } catch {}
      for (const node of nodes) {
        if (!node || seen.has(node)) continue;
        seen.add(node);
        out.push(node);
      }
    }
    return out;
  }

  function getDeepNativeElementText(el) {
    if (!el) return "";
    const parts = [];
    const add = (value) => {
      const text = String(value || "").trim();
      if (text) parts.push(text);
    };
    try {
      add(el.getAttribute?.("aria-label"));
      add(el.getAttribute?.("title"));
      add(el.getAttribute?.("name"));
      add(el.getAttribute?.("icon"));
      add(el.getAttribute?.("data-icon"));
      add(el.getAttribute?.("data-testid"));
      add(el.getAttribute?.("id"));
      add(el.className?.baseVal ?? el.className);
      add(el.innerText);
      add(el.textContent);
    } catch {}
    try {
      if (el.shadowRoot) {
        add(el.shadowRoot.textContent);
        for (const node of el.shadowRoot.querySelectorAll("[aria-label],[title],[name],[icon],[data-icon],[data-testid],wz-icon,i,svg")) {
          add(node.getAttribute?.("aria-label"));
          add(node.getAttribute?.("title"));
          add(node.getAttribute?.("name"));
          add(node.getAttribute?.("icon"));
          add(node.getAttribute?.("data-icon"));
          add(node.getAttribute?.("data-testid"));
          add(node.textContent);
          add(node.className?.baseVal ?? node.className);
        }
      }
    } catch {}
    return normalizeNativeActionText(parts.join(" "));
  }

  function isVisibleNativeActionElement(el) {
    try {
      if (!el || !el.isConnected || el.closest?.(".wmeRcMenu, .wmeRcModal, .wmeRcSegmentPropertiesPanel")) return false;
      const style = getComputedStyle(el);
      if (style.display === "none" || style.visibility === "hidden" || Number(style.opacity) === 0) return false;
      const rect = el.getBoundingClientRect();
      return rect.width > 4 && rect.height > 4 && rect.bottom >= 0 && rect.right >= 0 && rect.top <= innerHeight && rect.left <= innerWidth;
    } catch {
      return false;
    }
  }

  function getComposedNativeParent(node) {
    if (!node) return null;
    try { if (node.parentElement) return node.parentElement; } catch {}
    try {
      const root = node.getRootNode?.();
      if (root && root.host) return root.host;
    } catch {}
    return null;
  }

  function getNativeClickableElement(el) {
    if (!el) return null;
    const selector = "button,a,[role='button'],[role='menuitem'],[role='option'],wz-button,wz-icon-button,wz-menu-button,wz-menu-item,wz-list-item";
    let current = el;
    for (let depth = 0; current && depth < 10; depth++, current = getComposedNativeParent(current)) {
      try {
        const inner = current.shadowRoot?.querySelector?.("button,a,[role='button'],[role='menuitem'],[role='option']");
        if (inner) return inner;
      } catch {}
      try { if (current.matches?.(selector)) return current; } catch {}
    }
    return el;
  }

  function clickNativeElement(el) {
    const clickable = getNativeClickableElement(el);
    if (!clickable) return false;
    try { clickable.focus?.({ preventScroll: true }); } catch {}
    try {
      clickable.click();
      return true;
    } catch {}
    try {
      const rect = clickable.getBoundingClientRect?.();
      const clientX = rect ? rect.left + rect.width / 2 : 0;
      const clientY = rect ? rect.top + rect.height / 2 : 0;
      const NativeMouseEvent = UW?.MouseEvent || MouseEvent;
      for (const type of ["mousedown", "mouseup", "click"]) {
        clickable.dispatchEvent(new NativeMouseEvent(type, {
          bubbles: true,
          cancelable: true,
          composed: true,
          button: 0,
          buttons: type === "mousedown" ? 1 : 0,
          clientX,
          clientY,
        }));
      }
      return true;
    } catch {}
    return false;
  }


  function dispatchPhysicalNativeClick(el) {
    const original = getNativeClickableElement(el) || el;
    if (!original) return false;

    let target = original;
    try {
      const rect = original.getBoundingClientRect();
      const x = rect.left + rect.width / 2;
      const y = rect.top + rect.height / 2;

      // Descend through open shadow roots so the real clickable child receives
      // the pointer sequence instead of only the outer web-component host.
      let rootNode = document;
      for (let depth = 0; depth < 8; depth++) {
        const hit = rootNode.elementFromPoint?.(x, y);
        if (!hit) break;
        if (isRcOwnedNativeElement(hit)) {
          target = original;
          break;
        }
        target = hit;
        if (!hit.shadowRoot) break;
        rootNode = hit.shadowRoot;
      }

      if (isRcOwnedNativeElement(target)) return false;
      try { target.focus?.({ preventScroll: true }); } catch {}

      const NativeMouseEvent = UW?.MouseEvent || MouseEvent;
      const NativePointerEvent = UW?.PointerEvent || NativeMouseEvent;
      const common = {
        bubbles: true,
        cancelable: true,
        composed: true,
        clientX: x,
        clientY: y,
        button: 0,
      };

      for (const type of ["pointerover", "pointerenter", "pointermove"]) {
        target.dispatchEvent(new NativePointerEvent(type, {
          ...common,
          pointerType: "mouse",
          buttons: 0,
        }));
      }
      for (const type of ["mouseover", "mouseenter", "mousemove"]) {
        target.dispatchEvent(new NativeMouseEvent(type, {
          ...common,
          buttons: 0,
        }));
      }
      target.dispatchEvent(new NativePointerEvent("pointerdown", {
        ...common,
        pointerType: "mouse",
        buttons: 1,
      }));
      target.dispatchEvent(new NativeMouseEvent("mousedown", {
        ...common,
        buttons: 1,
      }));
      target.dispatchEvent(new NativePointerEvent("pointerup", {
        ...common,
        pointerType: "mouse",
        buttons: 0,
      }));
      target.dispatchEvent(new NativeMouseEvent("mouseup", {
        ...common,
        buttons: 0,
      }));
      target.dispatchEvent(new NativeMouseEvent("click", {
        ...common,
        buttons: 0,
      }));
      return true;
    } catch {}

    try {
      original.click();
      return true;
    } catch {}
    return false;
  }

  function getVisibleNativeClickableSet(aliases) {
    return new Set(getVisibleNativeActionCandidates(aliases).map(row => row.clickable));
  }

  async function waitForNewVisibleNativeAction(aliases, baseline, attempts = 18, delayMs = 55) {
    for (let attempt = 0; attempt < attempts; attempt++) {
      const rows = getVisibleNativeActionCandidates(aliases)
        .filter(row => !baseline.has(row.clickable))
        .sort((a, b) => {
          const aExact = aliases.some(alias =>
            normalizeNativeActionText(row.text) === normalizeNativeActionText(alias)
          ) ? 1 : 0;
          const bExact = aliases.some(alias =>
            normalizeNativeActionText(row.text) === normalizeNativeActionText(alias)
          ) ? 1 : 0;
          return bExact - aExact || b.score - a.score;
        });
      if (rows[0]) return rows[0];
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;
  }

  async function closeNativeLauncherWithoutEscape(launcher) {
    if (!launcher) return;
    try {
      const expanded = String(launcher.getAttribute?.("aria-expanded") || "").toLowerCase();
      if (expanded === "true") {
        dispatchPhysicalNativeClick(launcher);
        await new Promise(resolve => setTimeout(resolve, 45));
      }
    } catch {}
  }

  function getRegisteredNativeCreateShortcut(kind) {
    try {
      const actions = UW?.W?.accelerators?.Actions;
      if (!actions) return null;

      const key = String(kind || "").toLowerCase();
      const aliases = nativeCreateToolAliases(key);
      const conflicts = ["road", "pedestrian", "roundabout", "junctionbox", "mapnote"]
        .filter(other => other !== key);

      let best = null;
      let bestScore = -Infinity;

      for (const [actionName, action] of Object.entries(actions)) {
        const text = getNativeAcceleratorActionText(actionName, action);
        if (!text || !aliases.some(alias => nativeTextMatchesAlias(text, alias))) continue;

        const hasConflict = conflicts.some(other =>
          nativeCreateToolAliases(other).some(alias => nativeTextMatchesAlias(text, alias))
        );
        if (hasConflict) continue;

        const raw = action?.shortcut ?? action?.key ?? action?.hotkey;
        let shortcut = null;

        if (typeof raw === "string" && raw.trim()) {
          const value = raw.trim();
          const char = value.length === 1 ? value : "";
          shortcut = {
            key: char || value,
            code: char && /^[a-z]$/i.test(char) ? `Key${char.toUpperCase()}` : value,
            keyCode: char ? char.toUpperCase().charCodeAt(0) : 0,
            altKey: false,
            ctrlKey: false,
            metaKey: false,
            shiftKey: false,
          };
        } else if (raw && typeof raw === "object") {
          const keyValue = String(raw.key || "").trim();
          const codeValue = String(raw.code || "").trim();
          const keyCodeValue = Number(raw.keyCode || raw.which || 0);
          if (keyValue || codeValue || keyCodeValue) {
            shortcut = {
              key: keyValue || (
                keyCodeValue >= 65 && keyCodeValue <= 90
                  ? String.fromCharCode(keyCodeValue).toLowerCase()
                  : ""
              ),
              code: codeValue || (
                keyCodeValue >= 65 && keyCodeValue <= 90
                  ? `Key${String.fromCharCode(keyCodeValue)}`
                  : ""
              ),
              keyCode: keyCodeValue || (
                keyValue.length === 1 ? keyValue.toUpperCase().charCodeAt(0) : 0
              ),
              altKey: !!raw.altKey,
              ctrlKey: !!raw.ctrlKey,
              metaKey: !!raw.metaKey,
              shiftKey: !!raw.shiftKey,
            };
          }
        }

        if (!shortcut || (!shortcut.key && !shortcut.code && !shortcut.keyCode)) continue;

        let score = 0;
        if (aliases.some(alias => normalizeNativeActionText(text) === normalizeNativeActionText(alias))) score += 420;
        if (/\b(draw|insert|create|add|new)\b|σχεδ|δημιουργ|εισαγωγ|προσθήκ/i.test(text)) score += 180;
        score -= Math.max(0, text.length - 45);

        if (score > bestScore) {
          bestScore = score;
          best = shortcut;
        }
      }

      return bestScore >= 150 ? best : null;
    } catch {
      return null;
    }
  }

  function dispatchRegisteredNativeShortcut(shortcut) {
    if (!shortcut) return false;
    try {
      const doc = UW?.document || document;
      const active = doc.activeElement;
      if (active && (
        /^(input|textarea|select)$/i.test(String(active.tagName || "")) ||
        active.isContentEditable
      )) {
        try { active.blur(); } catch {}
      }

      const target = doc.body || doc.documentElement || doc;
      const NativeKeyboardEvent = UW?.KeyboardEvent || KeyboardEvent;
      const common = {
        key: shortcut.key || "",
        code: shortcut.code || "",
        keyCode: Number(shortcut.keyCode || 0),
        which: Number(shortcut.keyCode || 0),
        charCode: 0,
        bubbles: true,
        cancelable: true,
        composed: true,
        repeat: false,
        altKey: !!shortcut.altKey,
        ctrlKey: !!shortcut.ctrlKey,
        metaKey: !!shortcut.metaKey,
        shiftKey: !!shortcut.shiftKey,
      };

      try { target.focus?.({ preventScroll: true }); } catch {}

      for (const type of ["keydown", "keypress", "keyup"]) {
        const event = new NativeKeyboardEvent(type, common);
        for (const [prop, value] of [
          ["keyCode", common.keyCode],
          ["which", common.which],
        ]) {
          try {
            Object.defineProperty(event, prop, {
              configurable: true,
              get: () => value,
            });
          } catch {}
        }
        target.dispatchEvent(event);
      }
      return true;
    } catch {
      return false;
    }
  }

  async function activateNativeCreateViaObservedMenu(kind) {
    const key = String(kind || "").toLowerCase();
    const targetAliases = nativeCreateToolAliases(key);
    const targetBaseline = getVisibleNativeClickableSet(targetAliases);

    // Map note has its own native toolbar launcher in current WME builds.
    // Prefer that visible native button before opening the general Create menu.
    if (key === "mapnote") {
      const directCandidates = getVisibleNativeActionCandidates(targetAliases)
        .filter(row =>
          !isRcOwnedNativeElement(row.el) &&
          !isRcOwnedNativeElement(row.clickable)
        )
        .sort((a, b) => {
          const ar = a.rect;
          const br = b.rect;
          const aSmall = ar.width <= 90 && ar.height <= 70 ? 1 : 0;
          const bSmall = br.width <= 90 && br.height <= 70 ? 1 : 0;
          return bSmall - aSmall || b.score - a.score;
        });

      const direct = directCandidates[0];
      if (direct && dispatchPhysicalNativeClick(direct.el)) {
        return true;
      }
    }

    const roadsAliases = nativeRoadsCategoryAliases();
    const roadsBaseline = getVisibleNativeClickableSet(roadsAliases);
    const launchers = getNativeCreateLauncherCandidates();

    for (const launcher of launchers) {
      const currentTargetBaseline = new Set([
        ...targetBaseline,
        ...getVisibleNativeClickableSet(targetAliases),
      ]);
      const currentRoadsBaseline = new Set([
        ...roadsBaseline,
        ...getVisibleNativeClickableSet(roadsAliases),
      ]);

      // Some WME menu buttons open on hover.
      hoverNativeElement(launcher);
      await new Promise(resolve => setTimeout(resolve, 120));

      let target = await waitForNewVisibleNativeAction(
        targetAliases,
        currentTargetBaseline,
        3,
        50
      );
      if (target) {
        if (isNativeElementDisabled(target.el)) {
          await closeNativeLauncherWithoutEscape(launcher);
          toast(`The WME ${nativeCreateDisplayName(key)} tool is currently disabled.`);
          return true;
        }
        return dispatchPhysicalNativeClick(target.el);
      }

      // Others require an actual pointer sequence, not HTMLElement.click().
      dispatchPhysicalNativeClick(launcher);
      await new Promise(resolve => setTimeout(resolve, 120));

      target = await waitForNewVisibleNativeAction(
        targetAliases,
        currentTargetBaseline,
        4,
        55
      );
      if (target) {
        if (isNativeElementDisabled(target.el)) {
          await closeNativeLauncherWithoutEscape(launcher);
          toast(`The WME ${nativeCreateDisplayName(key)} tool is currently disabled.`);
          return true;
        }
        return dispatchPhysicalNativeClick(target.el);
      }

      if (key !== "mapnote") {
        const roads = await waitForNewVisibleNativeAction(
          roadsAliases,
          currentRoadsBaseline,
          5,
          55
        );

        if (roads) {
          hoverNativeElement(roads.el);
          await new Promise(resolve => setTimeout(resolve, 130));

          target = await waitForNewVisibleNativeAction(
            targetAliases,
            currentTargetBaseline,
            5,
            55
          );

          if (!target) {
            dispatchPhysicalNativeClick(roads.el);
            target = await waitForNewVisibleNativeAction(
              targetAliases,
              currentTargetBaseline,
              10,
              60
            );
          }

          if (target) {
            if (isNativeElementDisabled(target.el)) {
              await closeNativeLauncherWithoutEscape(launcher);
              toast(`The WME ${nativeCreateDisplayName(key)} tool is currently disabled.`);
              return true;
            }
            return dispatchPhysicalNativeClick(target.el);
          }
        }
      }

      await closeNativeLauncherWithoutEscape(launcher);
    }

    return false;
  }

  function nativeCreateAliases(kind) {
    const key = String(kind || "").toLowerCase();
    if (key === "road") return ["roads", "road", "segment", "segments", "δρόμοι", "δρόμος"];
    if (key === "pedestrian") return ["pedestrian path", "pedestrian paths", "footpath", "footpaths", "μονοπάτι πεζών", "πεζόδρομος"];
    if (key === "roundabout") return ["roundabout", "roundabouts", "κυκλικός κόμβος"];
    if (key === "junctionbox") return ["junction box", "junction boxes", "junctionbox", "πλαίσιο διασταύρωσης", "κουτί διασταύρωσης"];
    if (key === "mapnote") return ["map note", "map notes", "map comment", "map comments", "note", "notes", "comment", "comments", "σημείωση χάρτη", "σημειώσεις χάρτη", "σχόλιο χάρτη", "σχόλια χάρτη", "σημείωση", "σχόλιο"];
    return [];
  }

  function nativeCreateDisplayName(kind) {
    const key = String(kind || "").toLowerCase();
    if (key === "road") return "Road";
    if (key === "pedestrian") return "Pedestrian path";
    if (key === "roundabout") return "Roundabout";
    if (key === "junctionbox") return "Junction box";
    if (key === "mapnote") return "Map note";
    return String(kind || "tool");
  }

  function nativeRoadsCategoryAliases() {
    return ["roads", "δρόμοι"];
  }

  function nativeCreateRootLabelGroups() {
    return [
      nativeRoadsCategoryAliases(),
      ["place", "places", "χώρος", "μέρος"],
      ["hazard", "hazards", "κίνδυνος"],
      ["house number", "house numbers", "αριθμός οικίας"],
      nativeCreateAliases("mapnote"),
      ["restricted area", "restricted areas", "περιορισμένη περιοχή"],
      ["community schedule", "community schedules"]
    ];
  }

  function nativeRoadsSubmenuLabelGroups() {
    return [
      nativeCreateAliases("road"),
      nativeCreateAliases("pedestrian"),
      nativeCreateAliases("roundabout"),
      nativeCreateAliases("junctionbox")
    ];
  }

  function getNativeHumanActionText(el) {
    if (!el) return "";
    const parts = [];
    const add = (value) => {
      const valueText = String(value || "").replace(/\s+/g, " ").trim();
      if (valueText && valueText.length <= 240) parts.push(valueText);
    };
    try {
      add(el.getAttribute?.("aria-label"));
      add(el.getAttribute?.("title"));
      add(el.getAttribute?.("alt"));
      add(el.innerText);
      if (!el.innerText) add(el.textContent);
    } catch {}
    try {
      if (el.shadowRoot) {
        add(el.shadowRoot.querySelector?.("[aria-label]")?.getAttribute?.("aria-label"));
        add(el.shadowRoot.querySelector?.("[title]")?.getAttribute?.("title"));
        add(el.shadowRoot.innerText || el.shadowRoot.textContent);
      }
    } catch {}
    const normalized = normalizeNativeActionText(parts.join(" "));
    if (!normalized) return "";
    const words = normalized.split(" ");
    const compact = [];
    for (const word of words) {
      if (!compact.length || compact[compact.length - 1] !== word) compact.push(word);
    }
    return compact.join(" ");
  }

  function nativeTextMatchesAlias(text, alias) {
    const value = normalizeNativeActionText(text);
    const wanted = normalizeNativeActionText(alias);
    if (!value || !wanted) return false;
    if (value === wanted) return true;
    if (value.length > Math.max(92, wanted.length + 58)) return false;
    const escaped = wanted.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    try { return new RegExp(`(?:^|\\s)${escaped}(?:\\s|$)`, "i").test(value); } catch {}
    return value.includes(wanted);
  }

  function nativeTextIsCompactAlias(text, aliases) {
    const value = normalizeNativeActionText(text);
    if (!value) return false;
    for (const alias of aliases || []) {
      const wanted = normalizeNativeActionText(alias);
      if (!wanted || !nativeTextMatchesAlias(value, wanted)) continue;
      if (value === wanted) return true;
      const extra = value
        .replace(wanted, " ")
        .replace(/\b(chevron|arrow|right|forward|expand|more|menu|info|information|disabled|lock|locked|icon)\b/g, " ")
        .replace(/[^\p{L}\p{N}]+/gu, " ")
        .replace(/\s+/g, " ")
        .trim();
      if (!extra || extra.split(" ").length <= 1) return true;
    }
    return false;
  }


  function isRcOwnedNativeElement(node) {
    let current = node;
    for (let depth = 0; current && depth < 28; depth++) {
      try {
        const id = String(current.id || "");
        const className = String(current.className?.baseVal ?? current.className ?? "");
        const scriptOwner = String(current.getAttribute?.("data-wme-rc-owner") || "");
        if (
          /^wmeRc/i.test(id) ||
          /\bwmeRc[A-Za-z0-9_-]*/.test(className) ||
          scriptOwner === SCRIPT_ID ||
          current === pinsPanel
        ) {
          return true;
        }
      } catch {}
      current = getComposedNativeParent(current);
    }
    return false;
  }

  function isNativeElementDisabled(el) {
    const clickable = getNativeClickableElement(el);
    for (const node of [el, clickable]) {
      if (!node) continue;
      try {
        if (node.disabled === true) return true;
        if (String(node.getAttribute?.("aria-disabled") || "").toLowerCase() === "true") return true;
        if (node.hasAttribute?.("disabled")) return true;
        if (/\b(disabled|is-disabled)\b/i.test(String(node.className?.baseVal ?? node.className ?? ""))) return true;
      } catch {}
    }
    return false;
  }

  function getVisibleNativeActionCandidates(aliases) {
    const wanted = (aliases || []).map(normalizeNativeActionText).filter(Boolean);
    if (!wanted.length) return [];
    const selector = [
      '[role="menuitem"]',
      '[role="option"]',
      '[role="button"]',
      'wz-menu-item',
      'wz-list-item',
      'wz-button',
      'wz-icon-button',
      'wz-menu-button',
      'button',
      'a',
      'li',
      '[tabindex]'
    ].join(',');
    const rows = [];
    const seen = new Set();
    for (const el of deepNativeQueryAll(selector)) {
      if (!isVisibleNativeActionElement(el)) continue;
      const clickable = getNativeClickableElement(el);
      if (
        !clickable ||
        seen.has(clickable) ||
        isRcOwnedNativeElement(el) ||
        isRcOwnedNativeElement(clickable)
      ) continue;
      const humanText = getNativeHumanActionText(el);
      if (!wanted.some(alias => nativeTextMatchesAlias(humanText, alias))) continue;
      const rect = el.getBoundingClientRect();
      let score = 0;
      if (wanted.some(alias => humanText === alias)) score += 180;
      if (el.matches?.('[role="menuitem"],[role="option"],wz-menu-item,wz-list-item')) score += 85;
      if (rect.width >= 70 && rect.width <= 430) score += 22;
      if (rect.height >= 22 && rect.height <= 72) score += 24;
      score -= Math.min(40, Math.max(0, humanText.length - 30) / 2);
      seen.add(clickable);
      rows.push({ el, clickable, rect, text: humanText, score });
    }
    rows.sort((a, b) => b.score - a.score || a.rect.width * a.rect.height - b.rect.width * b.rect.height);
    return rows;
  }

  function getVisibleNativeCompactActionCandidates(aliases) {
    return getVisibleNativeActionCandidates(aliases).filter(row => nativeTextIsCompactAlias(row.text, aliases));
  }

  function isComposedDescendantOf(node, ancestor) {
    if (!node || !ancestor) return false;
    let current = node;
    for (let depth = 0; current && depth < 24; depth++, current = getComposedNativeParent(current)) {
      if (current === ancestor) return true;
    }
    return false;
  }

  function getComposedAncestors(node, maxDepth = 14) {
    const out = [];
    let current = node;
    for (let depth = 0; current && depth < maxDepth; depth++) {
      current = getComposedNativeParent(current);
      if (!current || current === document.documentElement || current === document.body) break;
      out.push(current);
    }
    return out;
  }

  function getNativeContainerSignature(el) {
    const parts = [];
    const add = value => {
      const v = String(value || "").trim();
      if (v) parts.push(v);
    };
    try {
      add(el.tagName);
      add(el.id);
      add(el.className?.baseVal ?? el.className);
      add(el.getAttribute?.("role"));
      add(el.getAttribute?.("aria-label"));
      add(el.getAttribute?.("data-testid"));
    } catch {}
    return normalizeNativeActionText(parts.join(" "));
  }

  function isPlausibleNativePopupContainer(el, minHeight = 90, maxHeight = 760) {
    try {
      if (!el || !el.isConnected) return false;
      const rect = el.getBoundingClientRect();
      if (rect.width < 145 || rect.width > 520 || rect.height < minHeight || rect.height > maxHeight) return false;
      if (rect.width * rect.height > 340000) return false;
      const sig = getNativeContainerSignature(el);
      if (/\b(layer|layers|sidebar|side-panel|drawer|navigation-drawer|map-layer|layer-switcher)\b/i.test(sig)) return false;
      const style = getComputedStyle(el);
      const role = String(el.getAttribute?.("role") || "").toLowerCase();
      const popupish = ["absolute", "fixed"].includes(style.position) || /menu|listbox|dialog/.test(role) || /menu|popover|popup|overlay/.test(sig);
      return popupish || rect.width <= 360;
    } catch {
      return false;
    }
  }

  function countExactGroupsInside(container, groups) {
    let count = 0;
    const matched = [];
    for (let i = 0; i < groups.length; i++) {
      const rows = getVisibleNativeCompactActionCandidates(groups[i]);
      const hit = rows.find(row => isComposedDescendantOf(row.el, container) || isComposedDescendantOf(row.clickable, container));
      if (hit) {
        count++;
        matched.push({ index: i, row: hit });
      }
    }
    return { count, matched };
  }

  function findNativeCreateRootDescriptor() {
    const groups = nativeCreateRootLabelGroups();
    const roadsRows = getVisibleNativeCompactActionCandidates(groups[0]);
    let best = null;
    let bestScore = -Infinity;

    for (const roadsRow of roadsRows) {
      const ancestors = getComposedAncestors(roadsRow.el, 16);
      for (let depth = 0; depth < ancestors.length; depth++) {
        const container = ancestors[depth];
        if (!isPlausibleNativePopupContainer(container, 160, 760)) continue;
        const matches = countExactGroupsInside(container, groups);
        if (matches.count < 5) continue;
        if (!matches.matched.some(m => m.index === 0)) continue;

        const rect = container.getBoundingClientRect();
        const sig = getNativeContainerSignature(container);
        let score = matches.count * 180;
        if (/menu|popover|popup|overlay/.test(sig)) score += 120;
        if (String(container.getAttribute?.("role") || "").toLowerCase() === "menu") score += 140;
        score -= depth * 9;
        score -= Math.max(0, rect.width - 330) * 0.2;
        score -= Math.max(0, rect.height - 430) * 0.08;
        if (score > bestScore) {
          bestScore = score;
          best = { row: roadsRow.el, clickable: roadsRow.clickable, container, rect, score };
        }
      }
    }
    return best;
  }

  async function waitForNativeCreateRootMenu(attempts = 16, delayMs = 65) {
    for (let i = 0; i < attempts; i++) {
      const descriptor = findNativeCreateRootDescriptor();
      if (descriptor) return descriptor;
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;
  }

  function hoverNativeElement(el) {
    const target = getNativeClickableElement(el) || el;
    if (!target) return false;
    try {
      const rect = target.getBoundingClientRect?.();
      const clientX = rect ? rect.left + rect.width / 2 : 0;
      const clientY = rect ? rect.top + rect.height / 2 : 0;
      const NativeMouseEvent = UW?.MouseEvent || MouseEvent;
      const NativePointerEvent = UW?.PointerEvent || NativeMouseEvent;
      for (const type of ["pointerover", "pointerenter"]) {
        target.dispatchEvent(new NativePointerEvent(type, {
          bubbles: type === "pointerover",
          cancelable: true,
          composed: true,
          pointerType: "mouse",
          clientX,
          clientY,
        }));
      }
      for (const type of ["mouseover", "mouseenter", "mousemove"]) {
        target.dispatchEvent(new NativeMouseEvent(type, {
          bubbles: type !== "mouseenter",
          cancelable: true,
          composed: true,
          clientX,
          clientY,
        }));
      }
      return true;
    } catch {}
    return false;
  }

  function getExplicitCreateSignal(el) {
    const clickable = getNativeClickableElement(el) || el;
    const parts = [];
    const add = value => {
      const v = String(value || "").trim();
      if (v) parts.push(v);
    };
    for (const node of [el, clickable]) {
      if (!node) continue;
      try {
        add(node.getAttribute?.("aria-label"));
        add(node.getAttribute?.("title"));
        add(node.getAttribute?.("name"));
        add(node.getAttribute?.("icon"));
        add(node.getAttribute?.("data-icon"));
        add(node.getAttribute?.("data-testid"));
        add(node.id);
        add(node.className?.baseVal ?? node.className);
      } catch {}
      try {
        if (node.shadowRoot) {
          for (const child of node.shadowRoot.querySelectorAll('[aria-label],[title],[name],[icon],[data-icon],[data-testid],wz-icon')) {
            add(child.getAttribute?.("aria-label"));
            add(child.getAttribute?.("title"));
            add(child.getAttribute?.("name"));
            add(child.getAttribute?.("icon"));
            add(child.getAttribute?.("data-icon"));
            add(child.getAttribute?.("data-testid"));
          }
        }
      } catch {}
    }
    return normalizeNativeActionText(parts.join(" "));
  }

  function scoreNativeCreateLauncher(el, allowPositionalFallback = false) {
    if (!isVisibleNativeActionElement(el)) return -Infinity;
    const clickable = getNativeClickableElement(el);
    if (!clickable) return -Infinity;
    const signal = getExplicitCreateSignal(el);
    const rect = clickable.getBoundingClientRect();
    const positive = /(?:^|[\s_-])(add|create|new|plus|draw)(?:[\s_-]|$)|add[-_ ]?(feature|object)|create[-_ ]?(feature|object)|προσθήκη|δημιουργία/i;
    const strong = /(?:^|[\s_-])(add|create|plus)(?:[\s_-]|$)/i;
    const negative = /(?:^|[\s_-])(layer|layers|map[-_ ]?layer|search|zoom|gps|location|help|chat|inbox|setting|settings|preference|preferences|permalink|fullscreen|refresh|pin)(?:[\s_-]|$)/i;
    if (negative.test(signal)) return -Infinity;

    let score = 0;
    if (strong.test(signal)) score += 420;
    else if (positive.test(signal)) score += 260;
    else if (!allowPositionalFallback) return -Infinity;

    try {
      const popup = String(clickable.getAttribute?.("aria-haspopup") || el.getAttribute?.("aria-haspopup") || "").toLowerCase();
      if (popup === "menu" || popup === "true") score += 120;
    } catch {}
    if (rect.width >= 20 && rect.width <= 76 && rect.height >= 20 && rect.height <= 76) score += 55;

    try {
      const mapRect = sdk?.Map?.getMapViewportElement?.()?.getBoundingClientRect?.() || getMapContainerEl()?.getBoundingClientRect?.();
      if (mapRect) {
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        const inside = cx >= mapRect.left && cx <= mapRect.right && cy >= mapRect.top && cy <= mapRect.bottom;
        if (!inside) return -Infinity;
        if (cx <= mapRect.left + Math.min(250, mapRect.width * 0.32)) score += 95;
        if (cy <= mapRect.top + Math.min(250, mapRect.height * 0.40)) score += 70;
        if (allowPositionalFallback && cx > mapRect.left + 300) return -Infinity;
      }
    } catch {}
    return score;
  }

  function getNativeCreateLauncherCandidates() {
    const explicitSelector = [
      '[aria-label*="create" i]', '[aria-label*="add" i]',
      '[title*="create" i]', '[title*="add" i]',
      '[name*="create" i]', '[name*="add" i]',
      '[icon*="add" i]', '[data-icon*="add" i]',
      '[data-testid*="create" i]', '[data-testid*="add" i]',
      '[id*="create" i]', '[id*="add" i]',
      'wz-menu-button', 'wz-icon-button', 'button[aria-haspopup="menu"]', '[role="button"][aria-haspopup="menu"]'
    ].join(',');
    const rows = [];
    const seen = new Set();

    const pushCandidate = (el, fallback) => {
      if (!el || isRcOwnedNativeElement(el)) return;
      const clickable = getNativeClickableElement(el);
      if (
        !clickable ||
        isRcOwnedNativeElement(clickable) ||
        seen.has(clickable) ||
        !isVisibleNativeActionElement(clickable)
      ) return;
      const score = scoreNativeCreateLauncher(el, fallback);
      if (!Number.isFinite(score) || score < 35) return;
      seen.add(clickable);
      rows.push({ el: clickable, score, signal: getExplicitCreateSignal(el) });
    };

    for (const el of deepNativeQueryAll(explicitSelector)) pushCandidate(el, false);

    // WME occasionally strips the accessible name from the add button. In that case,
    // test only small menu buttons in the map’s top-left control cluster. A strict
    // popup signature check below prevents Layers or another sidebar being accepted.
    const fallbackSelector = 'wz-menu-button,wz-icon-button,button,[role="button"]';
    for (const el of deepNativeQueryAll(fallbackSelector)) pushCandidate(el, true);

    rows.sort((a, b) => b.score - a.score);
    return rows.slice(0, 24).map(row => row.el);
  }

  function dispatchNativeEscape() {
    try {
      const NativeKeyboardEvent = UW?.KeyboardEvent || KeyboardEvent;
      for (const type of ["keydown", "keyup"]) {
        (UW?.document || document).dispatchEvent(new NativeKeyboardEvent(type, {
          key: "Escape",
          code: "Escape",
          keyCode: 27,
          which: 27,
          bubbles: true,
          cancelable: true,
          composed: true,
        }));
      }
    } catch {}
  }

  async function closeRejectedNativeLauncher(launcher) {
    try {
      const expanded = String(launcher?.getAttribute?.("aria-expanded") || "").toLowerCase();
      if (expanded === "true") clickNativeElement(launcher);
    } catch {}
    dispatchNativeEscape();
    await new Promise(resolve => setTimeout(resolve, 55));
  }

  async function openNativeCreateRootMenu() {
    const alreadyOpen = findNativeCreateRootDescriptor();
    if (alreadyOpen) return alreadyOpen;

    const candidates = getNativeCreateLauncherCandidates();
    for (const launcher of candidates) {
      if (!clickNativeElement(launcher)) continue;
      const descriptor = await waitForNativeCreateRootMenu(10, 55);
      if (descriptor) return descriptor;
      await closeRejectedNativeLauncher(launcher);
    }

    try {
      console.debug(`[${SCRIPT_NAME}] Legacy native Create detector did not resolve a menu. Candidates tested:`, candidates.map(el => ({
        tag: el?.tagName,
        signal: getExplicitCreateSignal(el),
        ariaLabel: el?.getAttribute?.('aria-label'),
        title: el?.getAttribute?.('title'),
        testId: el?.getAttribute?.('data-testid'),
      })));
    } catch {}
    return null;
  }

  function findNativeRoadsSubmenuDescriptor(kind, rootDescriptor) {
    const groups = nativeRoadsSubmenuLabelGroups();
    const targetIndex = kind === "road" ? 0 : kind === "pedestrian" ? 1 : kind === "roundabout" ? 2 : 3;
    const targetRows = getVisibleNativeCompactActionCandidates(groups[targetIndex]);
    const rootClickable = getNativeClickableElement(rootDescriptor?.row);
    const rootPanelRect = rootDescriptor?.container?.getBoundingClientRect?.() || rootDescriptor?.rect || null;
    let best = null;
    let bestScore = -Infinity;

    for (const row of targetRows) {
      if (row.clickable === rootClickable) continue;
      const ancestors = getComposedAncestors(row.el, 14);
      for (let depth = 0; depth < ancestors.length; depth++) {
        const container = ancestors[depth];
        if (!isPlausibleNativePopupContainer(container, 90, 520)) continue;
        const matches = countExactGroupsInside(container, groups);
        if (matches.count < 3) continue;
        const rect = container.getBoundingClientRect();
        if (rootPanelRect) {
          const toRight = rect.left >= rootPanelRect.left + Math.min(95, rootPanelRect.width * 0.34);
          const overlapsVertically = rect.bottom >= rootPanelRect.top - 30 && rect.top <= rootPanelRect.bottom + 30;
          if (!toRight || !overlapsVertically) continue;
        }
        let score = matches.count * 200;
        const sig = getNativeContainerSignature(container);
        if (/menu|popover|popup|overlay/.test(sig)) score += 100;
        if (String(container.getAttribute?.("role") || "").toLowerCase() === "menu") score += 120;
        score -= depth * 8;
        score -= Math.max(0, rect.width - 330) * 0.25;
        if (score > bestScore) {
          bestScore = score;
          best = { row: row.el, clickable: row.clickable, container, rect, score };
        }
      }
    }
    return best;
  }

  async function waitForNativeRoadToolItem(kind, rootDescriptor, attempts = 18, delayMs = 60) {
    for (let i = 0; i < attempts; i++) {
      const descriptor = findNativeRoadsSubmenuDescriptor(kind, rootDescriptor);
      if (descriptor) return descriptor;
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;
  }



  function nativeCreateToolAliases(kind) {
    const key = String(kind || "").toLowerCase();
    if (key === "road") return ["road", "segment", "δρόμος"];
    if (key === "pedestrian") return nativeCreateAliases("pedestrian");
    if (key === "roundabout") return nativeCreateAliases("roundabout");
    if (key === "junctionbox") return nativeCreateAliases("junctionbox");
    if (key === "mapnote") return nativeCreateAliases("mapnote");
    return nativeCreateAliases(key);
  }

  function getVisibleNativeCreateRootEvidence() {
    const groups = nativeCreateRootLabelGroups();
    const evidence = [];
    for (let index = 0; index < groups.length; index++) {
      const hit = getVisibleNativeActionCandidates(groups[index])[0];
      if (hit) evidence.push({ index, row: hit });
    }
    return evidence;
  }

  async function waitForVisibleNativeCreateRoot(attempts = 12, delayMs = 55) {
    for (let attempt = 0; attempt < attempts; attempt++) {
      const evidence = getVisibleNativeCreateRootEvidence();
      if (evidence.length >= 2 || evidence.some(item => item.index === 0)) return evidence;
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return [];
  }

  async function openNativeCreateRootLoose() {
    const existing = getVisibleNativeCreateRootEvidence();
    if (existing.length >= 2 || existing.some(item => item.index === 0)) {
      return { launcher: null, evidence: existing };
    }

    const candidates = getNativeCreateLauncherCandidates();
    for (const launcher of candidates) {
      if (!clickNativeElement(launcher)) continue;

      const evidence = await waitForVisibleNativeCreateRoot(10, 55);
      if (evidence.length >= 2 || evidence.some(item => item.index === 0)) {
        return { launcher, evidence };
      }

      await closeRejectedNativeLauncher(launcher);
    }

    return null;
  }

  async function waitForVisibleNativeTool(aliases, excludedClickables = new Set(), attempts = 16, delayMs = 55) {
    for (let attempt = 0; attempt < attempts; attempt++) {
      const rows = getVisibleNativeActionCandidates(aliases)
        .filter(row => !excludedClickables.has(row.clickable))
        .sort((a, b) => {
          const aExact = aliases.some(alias => normalizeNativeActionText(rowText(a)) === normalizeNativeActionText(alias)) ? 1 : 0;
          const bExact = aliases.some(alias => normalizeNativeActionText(rowText(b)) === normalizeNativeActionText(alias)) ? 1 : 0;
          return bExact - aExact || b.score - a.score;
        });
      if (rows[0]) return rows[0];
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;

    function rowText(row) {
      return row?.text || getNativeHumanActionText(row?.el);
    }
  }

  async function activateNativeCreateViaLooseMenu(kind) {
    const root = await openNativeCreateRootLoose();
    if (!root) return false;

    const key = String(kind || "").toLowerCase();

    if (key === "mapnote") {
      const target = await waitForVisibleNativeTool(nativeCreateToolAliases(key), new Set(), 14, 55);
      if (!target) {
        dispatchNativeEscape();
        return false;
      }
      if (isNativeElementDisabled(target.el)) {
        dispatchNativeEscape();
        toast(`The WME ${nativeCreateDisplayName(key)} tool is currently disabled.`);
        return true;
      }
      return clickNativeElement(target.el);
    }

    const roadsRows = getVisibleNativeActionCandidates(nativeRoadsCategoryAliases())
      .sort((a, b) => b.score - a.score);
    const roads = roadsRows[0];
    if (!roads) {
      dispatchNativeEscape();
      return false;
    }

    const excluded = new Set([roads.clickable]);
    hoverNativeElement(roads.el);
    await new Promise(resolve => setTimeout(resolve, 90));

    let target = await waitForVisibleNativeTool(nativeCreateToolAliases(key), excluded, 5, 55);
    if (!target) {
      clickNativeElement(roads.el);
      target = await waitForVisibleNativeTool(nativeCreateToolAliases(key), excluded, 16, 60);
    }

    if (!target) {
      dispatchNativeEscape();
      return false;
    }

    if (isNativeElementDisabled(target.el)) {
      dispatchNativeEscape();
      toast(`The WME ${nativeCreateDisplayName(key)} tool is currently disabled.`);
      return true;
    }

    return clickNativeElement(target.el);
  }

  function getNativeAcceleratorActionText(actionName, action) {
    const parts = [];
    const add = (value) => {
      const text = String(value || "").replace(/\s+/g, " ").trim();
      if (text) parts.push(text);
    };

    add(actionName);
    if (typeof action === "string") add(action);
    add(action?.id);
    add(action?.name);
    add(action?.description);
    add(action?.title);
    add(action?.group);

    try {
      const locale = UW?.I18n?.locale;
      const groups = UW?.I18n?.translations?.[locale]?.keyboard_shortcuts?.groups;
      const group = groups?.[action?.group];
      const members = group?.members;
      add(group?.description);
      add(members?.[actionName]);
      add(members?.[action?.id]);
    } catch {}

    return normalizeNativeActionText(parts.join(" "));
  }

  function getNativeCreateActionPatterns(kind) {
    const key = String(kind || "").toLowerCase();
    if (key === "road") {
      return [
        /(?:create|add|draw|insert|new)[-_ ]*(?:road|segment)/i,
        /(?:road|segment)[-_ ]*(?:create|add|draw|insert|new)/i,
      ];
    }
    if (key === "pedestrian") {
      return [
        /(?:create|add|draw|insert|new)[-_ ]*(?:pedestrian|footpath|foot|walking|walkway)/i,
        /(?:pedestrian|footpath|walking|walkway)[-_ ]*(?:path|road|segment|create|add|draw|insert)/i,
      ];
    }
    if (key === "roundabout") return [/roundabout/i];
    if (key === "junctionbox") return [/junction[-_ ]*box/i, /junctionbox/i];
    if (key === "mapnote") {
      return [
        /map[-_ ]*(?:note|comment)/i,
        /(?:note|comment)[-_ ]*map/i,
        /(?:create|add|new)[-_ ]*(?:note|comment)/i,
      ];
    }
    return [];
  }

  function getNativeCreateActionCollections(accelerators) {
    const out = [];
    for (const candidate of [
      accelerators?.Actions,
      accelerators?.actions,
      accelerators?._actions,
      accelerators?.actionMap,
    ]) {
      if (!candidate || typeof candidate !== "object" || out.includes(candidate)) continue;
      out.push(candidate);
    }
    return out;
  }

  function invokeNativeAcceleratorAction(accelerators, actionName, action) {
    const ids = Array.from(new Set([
      actionName,
      action?.id,
      action?.event,
      action?.eventName,
      action?.action,
      action?.actionName,
    ].map(value => String(value || "").trim()).filter(Boolean)));

    const events = accelerators?.events;
    for (const id of ids) {
      try {
        if (typeof events?.triggerEvent === "function") {
          events.triggerEvent(id);
          return true;
        }
      } catch {}
      try {
        if (typeof events?.trigger === "function") {
          events.trigger(id);
          return true;
        }
      } catch {}
      try {
        if (typeof events?.emit === "function") {
          events.emit(id);
          return true;
        }
      } catch {}

      for (const method of ["triggerAction", "executeAction", "runAction", "execute", "run", "trigger"]) {
        try {
          if (typeof accelerators?.[method] === "function") {
            accelerators[method](id);
            return true;
          }
        } catch {}
      }
    }

    for (const method of ["trigger", "callback", "execute", "run", "handler", "action"]) {
      try {
        if (typeof action?.[method] === "function") {
          action[method]();
          return true;
        }
      } catch {}
    }

    if (typeof action === "function") {
      try {
        action();
        return true;
      } catch {}
    }

    return false;
  }

  function triggerNativeWmeCreateAccelerator(kind) {
    try {
      const accelerators = UW?.W?.accelerators;
      if (!accelerators) return false;

      const targetKind = String(kind || "").toLowerCase();
      const aliases = nativeCreateToolAliases(targetKind);
      const patterns = getNativeCreateActionPatterns(targetKind);
      const collections = getNativeCreateActionCollections(accelerators);

      let best = null;
      let bestScore = -Infinity;

      for (const actions of collections) {
        for (const [actionName, action] of Object.entries(actions)) {
          const text = getNativeAcceleratorActionText(actionName, action);
          const actionIdText = normalizeNativeActionText([
            actionName,
            typeof action === "string" ? action : "",
            action?.id,
            action?.name,
            action?.event,
            action?.eventName,
            action?.action,
            action?.actionName,
          ].filter(Boolean).join(" "));

          let score = 0;

          for (const pattern of patterns) {
            if (pattern.test(actionIdText)) score += 900;
            if (pattern.test(text)) score += 500;
          }

          for (const alias of aliases) {
            if (!nativeTextMatchesAlias(text, alias) && !nativeTextMatchesAlias(actionIdText, alias)) continue;
            const wanted = normalizeNativeActionText(alias);
            score += actionIdText === wanted || text === wanted ? 420 : 210;
          }

          const hasCreateVerb =
            /\b(create|add|draw|insert|new|start)\b|σχεδ|δημιουργ|εισαγωγ|προσθήκ|έναρξ/i.test(
              `${actionIdText} ${text}`
            );
          if (hasCreateVerb) score += 180;

          const negativeByKind = {
            road: /\b(roundabout|junction|pedestrian|footpath|walking|map note|map comment)\b/i,
            pedestrian: /\b(roundabout|junction box|map note|map comment)\b/i,
            roundabout: /\b(junction box|pedestrian|map note|map comment)\b/i,
            junctionbox: /\b(roundabout|pedestrian|map note|map comment)\b/i,
            mapnote: /\b(roundabout|junction box|pedestrian|road segment)\b/i,
          }[targetKind];
          if (negativeByKind?.test(`${actionIdText} ${text}`)) score -= 1000;

          if (score > bestScore) {
            bestScore = score;
            best = { actionName, action, text, actionIdText };
          }
        }
      }

      if (!best || bestScore < 400) {
        try {
          console.debug(
            `[${SCRIPT_NAME}] No native accelerator action matched ${nativeCreateDisplayName(targetKind)}.`
          );
        } catch {}
        return false;
      }

      return invokeNativeAcceleratorAction(accelerators, best.actionName, best.action);
    } catch (error) {
      console.warn(
        `[${SCRIPT_NAME}] Could not invoke WME’s native ${nativeCreateDisplayName(kind)} action.`,
        error
      );
      return false;
    }
  }

  function dispatchNativeWmeShortcut(key, code, keyCode) {
    try {
      const doc = UW?.document || document;
      const active = doc.activeElement;
      if (active && (
        /^(input|textarea|select)$/i.test(String(active.tagName || "")) ||
        active.isContentEditable
      )) {
        try { active.blur(); } catch {}
      }

      const target = doc.body || doc.documentElement || doc;
      try {
        if (target instanceof HTMLElement && !target.hasAttribute("tabindex")) {
          target.setAttribute("tabindex", "-1");
          target.dataset.wmeRcTemporaryTabindex = "1";
        }
        target.focus?.({ preventScroll: true });
      } catch {}

      const NativeKeyboardEvent = UW?.KeyboardEvent || KeyboardEvent;
      const common = {
        key,
        code,
        keyCode,
        which: keyCode,
        charCode: 0,
        bubbles: true,
        cancelable: true,
        composed: true,
        repeat: false,
        altKey: false,
        ctrlKey: false,
        metaKey: false,
        shiftKey: false,
      };

      for (const type of ["keydown", "keypress", "keyup"]) {
        const event = new NativeKeyboardEvent(type, common);
        for (const [prop, value] of [["keyCode", keyCode], ["which", keyCode]]) {
          try {
            if (Number(event[prop]) !== Number(value)) {
              Object.defineProperty(event, prop, { configurable: true, get: () => value });
            }
          } catch {}
        }
        target.dispatchEvent(event);
      }

      try {
        if (target?.dataset?.wmeRcTemporaryTabindex === "1") {
          target.removeAttribute("tabindex");
          delete target.dataset.wmeRcTemporaryTabindex;
        }
      } catch {}

      return true;
    } catch (error) {
      console.warn(`[${SCRIPT_NAME}] Could not dispatch WME’s native shortcut.`, error);
      return false;
    }
  }

  async function activateNativeWmeCreateAccelerator(kind) {
    // Prefer WME's registered action so every tool keeps its native snapping,
    // validation, specialised UI, and junction behavior.
    if (triggerNativeWmeCreateAccelerator(kind)) {
      await new Promise(resolve => setTimeout(resolve, 50));
      return true;
    }

    const key = String(kind || "").toLowerCase();
    const shortcut = key === "road"
      ? { key: "i", code: "KeyI", keyCode: 73 }
      : key === "roundabout"
        ? { key: "o", code: "KeyO", keyCode: 79 }
        : key === "junctionbox"
          ? { key: "j", code: "KeyJ", keyCode: 74 }
          : null;

    if (shortcut && dispatchNativeWmeShortcut(shortcut.key, shortcut.code, shortcut.keyCode)) {
      await new Promise(resolve => setTimeout(resolve, 70));
      return true;
    }

    return false;
  }

  async function activateNativeCreateRootItem(kind) {
    const rootDescriptor = await openNativeCreateRootMenu();
    if (!rootDescriptor) return false;

    const aliases = nativeCreateAliases(kind);
    for (let attempt = 0; attempt < 14; attempt++) {
      const candidates = getVisibleNativeCompactActionCandidates(aliases)
        .filter(row => (
          row.el !== rootDescriptor.row &&
          row.clickable !== rootDescriptor.clickable &&
          (
            isComposedDescendantOf(row.el, rootDescriptor.container) ||
            isComposedDescendantOf(row.clickable, rootDescriptor.container)
          )
        ))
        .sort((a, b) => b.score - a.score);

      const hit = candidates[0];
      if (hit) {
        if (isNativeElementDisabled(hit.row)) {
          dispatchNativeEscape();
          toast(`The WME ${nativeCreateDisplayName(kind)} tool is currently disabled.`);
          return true;
        }
        return clickNativeElement(hit.row);
      }
      await new Promise(resolve => setTimeout(resolve, 55));
    }

    dispatchNativeEscape();
    return false;
  }

  async function activateNativeCreateFromToolbar(kind) {
    const rootDescriptor = await openNativeCreateRootMenu();
    if (!rootDescriptor) return false;

    hoverNativeElement(rootDescriptor.row);
    await new Promise(resolve => setTimeout(resolve, 70));
    let toolDescriptor = await waitForNativeRoadToolItem(kind, rootDescriptor, 5, 55);

    if (!toolDescriptor) {
      clickNativeElement(rootDescriptor.row);
      toolDescriptor = await waitForNativeRoadToolItem(kind, rootDescriptor, 18, 60);
    }

    if (!toolDescriptor) {
      dispatchNativeEscape();
      try {
        console.warn(`[${SCRIPT_NAME}] Native Roads submenu did not appear for: ${kind}`, {
          rootText: getNativeHumanActionText(rootDescriptor.row),
          rootContainer: getNativeContainerSignature(rootDescriptor.container),
        });
      } catch {}
      return false;
    }

    if (isNativeElementDisabled(toolDescriptor.row)) {
      dispatchNativeEscape();
      toast(`The WME ${kind === "junctionbox" ? "Junction box" : kind} tool is currently disabled.`);
      return true;
    }

    hoverNativeElement(toolDescriptor.row);
    await new Promise(resolve => setTimeout(resolve, 40));
    return clickNativeElement(toolDescriptor.row);
  }

  function isCancelledNativeDrawError(error) {
    const text = String(error?.message || error || "").toLowerCase();
    return /cancel|aborted|escape|drawing.*stopped/.test(text);
  }

  function selectNewSegmentIds(ids) {
    const uniq = Array.from(new Set((ids || []).map(Number).filter(Number.isFinite)));
    if (!uniq.length) return false;
    try {
      if (typeof sdk?.Editing?.setSelection === "function") {
        sdk.Editing.setSelection({ selection: { ids: uniq, objectType: "segment" } });
        return true;
      }
    } catch {}
    return setSelectionToSegmentIdsSilent(uniq);
  }

  async function activateSdkSegmentDrawTool(kind) {
    const roadType = kind === "pedestrian" ? 5 : 1;
    try {
      if (typeof sdk?.Map?.drawLine !== "function" || typeof sdk?.DataModel?.Segments?.addSegment !== "function") {
        return false;
      }

      // This is the direct drawing flow used by the reference:
      // activate the map line tool, let the editor draw the geometry, then
      // insert a real WME segment and select it so WME opens its own properties.
      const geometry = await sdk.Map.drawLine();
      const coordinates = Array.isArray(geometry?.coordinates) ? geometry.coordinates : [];
      if (coordinates.length < 2) return false;

      const segmentId = Number(sdk.DataModel.Segments.addSegment({ geometry, roadType }));
      if (!Number.isFinite(segmentId)) return false;

      // Selecting the new segment opens WME's normal segment-properties sidebar.
      // Repeat once after the model/UI settles because recent WME builds can
      // briefly clear the selection immediately after addSegment().
      selectNewSegmentIds([segmentId]);
      setTimeout(() => selectNewSegmentIds([segmentId]), 140);
      return true;
    } catch (error) {
      if (!isCancelledNativeDrawError(error)) {
        console.error(`[${SCRIPT_NAME}] SDK segment drawing failed`, error);
        toast(`Could not create the WME ${kind === "pedestrian" ? "pedestrian path" : "road"}.`);
      }
      return isCancelledNativeDrawError(error);
    }
  }

  function distanceMetersBetweenLonLat(a, b) {
    const lat1 = Number(a?.lat);
    const lon1 = Number(a?.lon);
    const lat2 = Number(b?.lat);
    const lon2 = Number(b?.lon);
    if (![lat1, lon1, lat2, lon2].every(Number.isFinite)) return 0;
    const rad = Math.PI / 180;
    const dLat = (lat2 - lat1) * rad;
    const dLon = (lon2 - lon1) * rad;
    const p1 = lat1 * rad;
    const p2 = lat2 * rad;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dLon / 2) ** 2;
    return 6371008.8 * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(Math.max(0, 1 - h)));
  }

  async function activateSdkRoundaboutDrawTool() {
    try {
      if (typeof sdk?.Map?.drawLine !== "function" || typeof sdk?.DataModel?.Segments?.createRoundabout !== "function") return false;
      const geometry = await sdk.Map.drawLine();
      const coords = Array.isArray(geometry?.coordinates) ? geometry.coordinates : [];
      if (coords.length < 2) return false;
      const first = coords[0];
      const last = coords[coords.length - 1];
      const center = { lon: Number(first?.[0]), lat: Number(first?.[1]) };
      const edge = { lon: Number(last?.[0]), lat: Number(last?.[1]) };
      const radius = distanceMetersBetweenLonLat(center, edge);
      if (!Number.isFinite(radius) || radius < 2) {
        toast("Draw a longer radius for the roundabout.");
        return true;
      }
      const ids = sdk.DataModel.Segments.createRoundabout({ center, rx: radius, ry: radius });
      const segmentIds = Array.isArray(ids) ? ids.map(Number).filter(Number.isFinite) : [];
      if (segmentIds.length) selectNewSegmentIds(segmentIds);
      return true;
    } catch (error) {
      if (!isCancelledNativeDrawError(error)) {
        console.error(`[${SCRIPT_NAME}] SDK roundabout drawing failed`, error);
        toast("Could not create the WME roundabout.");
      }
      return isCancelledNativeDrawError(error);
    }
  }

  function stopCreatedRoadPropertiesWatcher() {
    const w = createdRoadPropertiesWatcher;
    createdRoadPropertiesWatcher = null;
    if (!w) return;
    try { clearInterval(w.interval); } catch {}
    try { clearTimeout(w.timeout); } catch {}
    try { document.removeEventListener('pointerdown', w.onPointerDown, true); } catch {}
    try { document.removeEventListener('dblclick', w.onFinishGesture, true); } catch {}
    try { document.removeEventListener('keydown', w.onKeyDown, true); } catch {}
  }

  function armCreatedRoadPropertiesWatcher(previousIds = []) {
    stopCreatedRoadPropertiesWatcher();
    const before = new Set((previousIds || []).map(Number).filter(Number.isFinite));
    const watcher = {
      lastActivity: Date.now(),
      lastSignature: '',
      stableSince: 0,
      opened: false,
      interval: null,
      timeout: null,
      onPointerDown: null,
      onFinishGesture: null,
      onKeyDown: null,
    };

    const getNewSelection = () => {
      const selected = selectedSegmentIds();
      if (!selected.length) return [];
      const fresh = selected.filter(id => !before.has(Number(id)));
      return fresh.length ? fresh : (before.size === 0 ? selected : []);
    };

    const openWhenReady = (force = false) => {
      if (watcher.opened) return false;
      const ids = getNewSelection();
      if (!ids.length) return false;
      const signature = ids.slice().sort((a, b) => a - b).join(',');
      const now = Date.now();
      if (signature !== watcher.lastSignature) {
        watcher.lastSignature = signature;
        watcher.stableSince = now;
        if (!force) return false;
      }
      const stableFor = now - watcher.stableSince;
      const idleFor = now - watcher.lastActivity;
      if (!force && (stableFor < 3500 || idleFor < 3500)) return false;
      watcher.opened = true;
      stopCreatedRoadPropertiesWatcher();
      setTimeout(() => {
        const current = selectedSegmentIds();
        const freshCurrent = current.filter(id => !before.has(Number(id)));
        const finalIds = freshCurrent.length ? freshCurrent : ids;
        if (finalIds.length) openSegmentPropertiesPanel(finalIds);
      }, force ? 320 : 120);
      return true;
    };

    watcher.onPointerDown = (event) => {
      if (event.button == null || event.button === 0) {
        if (Number.isFinite(event.clientX) && Number.isFinite(event.clientY) && isMapClick(event.clientX, event.clientY)) {
          watcher.lastActivity = Date.now();
        }
      }
    };
    watcher.onFinishGesture = (event) => {
      if (Number.isFinite(event.clientX) && Number.isFinite(event.clientY) && !isMapClick(event.clientX, event.clientY)) return;
      watcher.lastActivity = Date.now() - 2000;
      setTimeout(() => openWhenReady(true), 220);
    };
    watcher.onKeyDown = (event) => {
      if (event.key === 'Enter') {
        watcher.lastActivity = Date.now() - 2000;
        setTimeout(() => openWhenReady(true), 220);
      } else if (event.key === 'Escape') {
        stopCreatedRoadPropertiesWatcher();
      }
    };

    document.addEventListener('pointerdown', watcher.onPointerDown, true);
    document.addEventListener('dblclick', watcher.onFinishGesture, true);
    document.addEventListener('keydown', watcher.onKeyDown, true);
    watcher.interval = setInterval(() => openWhenReady(false), 300);
    watcher.timeout = setTimeout(stopCreatedRoadPropertiesWatcher, 120000);
    createdRoadPropertiesWatcher = watcher;
  }

  async function activateNativeWmeCreateTool(kind, clientX, clientY) {
    closeAllMenus();
    await new Promise(resolve => setTimeout(resolve, 55));

    const key = String(kind || "").toLowerCase();

    // Trigger WME's native action directly. This does not depend on the user's
    // keyboard shortcut and keeps the real WME drawing/editing behavior.
    if (triggerNativeWmeCreateAccelerator(key)) {
      await new Promise(resolve => setTimeout(resolve, 70));
      return;
    }

    // Use the shortcut currently registered by WME when it is exposed.
    const registeredShortcut = getRegisteredNativeCreateShortcut(key);
    if (registeredShortcut && dispatchRegisteredNativeShortcut(registeredShortcut)) {
      await new Promise(resolve => setTimeout(resolve, 80));
      return;
    }

    // Fall back to WME's real visible Create controls.
    const activatedByMenu = await activateNativeCreateViaObservedMenu(key);
    if (activatedByMenu) return;

    // These defaults are retained only as a final compatibility fallback.
    const defaultShortcut = key === "road"
      ? { key: "i", code: "KeyI", keyCode: 73 }
      : key === "roundabout"
        ? { key: "o", code: "KeyO", keyCode: 79 }
        : key === "junctionbox"
          ? { key: "j", code: "KeyJ", keyCode: 74 }
          : null;

    if (defaultShortcut && dispatchRegisteredNativeShortcut(defaultShortcut)) {
      await new Promise(resolve => setTimeout(resolve, 80));
      return;
    }

    toast(`Could not activate WME’s native ${nativeCreateDisplayName(key)} tool.`);
  }

  function buildWindowsCompactCreateSubmenu(clientX, clientY) {
    return [
      { label: withIcon(ICONS.road, "Road"), onClick: () => activateNativeWmeCreateTool('road', clientX, clientY) },
      { label: withIcon(ICONS.pedestrian, "Pedestrian path"), onClick: () => activateNativeWmeCreateTool('pedestrian', clientX, clientY) },
      { label: withIcon(ICONS.roundabout, "Roundabout"), onClick: () => activateNativeWmeCreateTool('roundabout', clientX, clientY) },
      { label: withIcon(ICONS.junctionBox, "Junction box"), onClick: () => activateNativeWmeCreateTool('junctionbox', clientX, clientY) },
      { label: withIcon(ICONS.note, "Map note"), sub: "Coming soon", disabled: true, comingSoon: true },
    ];
  }

