  function loadRcUserscriptSettings() {
    try {
      const parsed = JSON.parse(localStorage.getItem(RC_USERSCRIPT_SETTINGS_KEY) || '{}');
      const rawOrder = Array.isArray(parsed?.order) ? parsed.order.map(String) : [];
      const order = [];
      for (const id of [...rawOrder, ...RC_USERSCRIPT_DEFAULT_ORDER]) {
        if (RC_USERSCRIPT_DEFAULT_ORDER.includes(id) && !order.includes(id)) order.push(id);
      }
      const disabled = parsed?.disabled && typeof parsed.disabled === 'object' ? { ...parsed.disabled } : {};
      return { order, disabled };
    } catch {
      return { order: [...RC_USERSCRIPT_DEFAULT_ORDER], disabled: {} };
    }
  }

  function saveRcUserscriptSettings(value) {
    const next = value && typeof value === 'object' ? value : loadRcUserscriptSettings();
    try { localStorage.setItem(RC_USERSCRIPT_SETTINGS_KEY, JSON.stringify(next)); } catch {}
  }

  function isRcUserscriptEnabled(id) {
    const sid = String(id || '');
    return loadRcUserscriptSettings().disabled[sid] !== true;
  }

  function setRcUserscriptEnabled(id, enabledValue) {
    const sid = String(id || '');
    if (!sid) return;
    const cfg = loadRcUserscriptSettings();
    if (enabledValue) delete cfg.disabled[sid];
    else cfg.disabled[sid] = true;
    saveRcUserscriptSettings(cfg);
  }

  function resetRcUserscriptOrder() {
    const cfg = loadRcUserscriptSettings();
    cfg.order = [...RC_USERSCRIPT_DEFAULT_ORDER];
    saveRcUserscriptSettings(cfg);
  }

  function moveRcUserscriptBeforeOrAfter(draggedId, targetId, after) {
    const cfg = loadRcUserscriptSettings();
    const order = cfg.order.filter((id) => id !== draggedId);
    const idx = order.indexOf(targetId);
    order.splice(idx < 0 ? order.length : idx + (after ? 1 : 0), 0, draggedId);
    cfg.order = order;
    saveRcUserscriptSettings(cfg);
  }

  function sortUserscriptEntries(entries) {
    const order = loadRcUserscriptSettings().order;
    const rank = new Map(order.map((id, i) => [id, i]));
    return (entries || []).slice().sort((a, b) => (rank.get(a.id) ?? 999) - (rank.get(b.id) ?? 999));
  }

