  function bindAdvancedClosuresWindowsTabs(dialog) {
    if (!dialog) return;
    const tabs = dialog.querySelector('.wmeac-nav-tabs');
    if (!tabs) return;
    tabs.setAttribute('role', 'tablist');
    const sync = () => {
      const links = Array.from(tabs.querySelectorAll(':scope > li > a[data-toggle="tab"]'));
      links.forEach((link) => {
        const active = !!link.closest('li')?.classList.contains('active');
        link.classList.toggle('is-active', active);
        link.setAttribute('aria-selected', active ? 'true' : 'false');
        link.setAttribute('role', 'tab');
      });
      dialog.classList.toggle('wmeRcAcSectionOpen', !!tabs.querySelector(':scope > li.active'));
    };
    sync();
    if (dialog.dataset.wmeRcWindowsTabsBound === '1') return;
    dialog.dataset.wmeRcWindowsTabsBound = '1';
    tabs.addEventListener('click', () => {
      requestAnimationFrame(sync);
      setTimeout(sync, 0);
      setTimeout(sync, 80);
    });
  }

  function syncAdvancedClosuresUi(root = document) {
    const light = (typeof getResolvedRcMenuTheme === 'function' ? getResolvedRcMenuTheme() : 'dark') === 'light';
    let dialogs = [];
    try {
      if (root?.matches?.('#wmeac-add-advanced-closure-dialog')) dialogs.push(root);
      dialogs.push(...Array.from(root?.querySelectorAll?.('#wmeac-add-advanced-closure-dialog') || []));
    } catch {}
    dialogs = Array.from(new Set(dialogs));
    for (const dialog of dialogs) {
      try {
        dialog.classList.toggle('wmeRcAcThemeLight', light);
        dialog.classList.toggle('wmeRcAcThemeDark', !light);
        bindAdvancedClosuresWindowsTabs(dialog);
      } catch {}
    }
  }

