  let rcReducedMotionObserver = null;

  function syncRcReducedMotionScope(enabled) {
    const selector = '.wmeRcMenu,.wmeRcPins,.wmeRcPinsBubble,.wmeRcPinsPanel,.wmeRcNotice,.wmeRcModal,.wmeRcModalBackdrop,.wmeRcToast,.wmeRcFriendsNotificationStack,.wmeRcFriendsSideNotification,.wmeRcPinHitBubble,.wmeRcPinHitPopup,.wmeRcTinyToggle,.wmeRcSideWrap,.wmeRcSidePanel,.wmeRcSelectMenu';
    try {
      document.querySelectorAll(selector).forEach((el) => {
        try { el.classList.toggle('wmeRcReducedMotionScope', !!enabled); } catch {}
      });
    } catch {}
    try {
      if (!rcReducedMotionObserver) {
        rcReducedMotionObserver = new MutationObserver((mutations) => {
          const active = !!loadPermalinkSettings().reducedMotion;
          for (const m of mutations) {
            for (const n of Array.from(m.addedNodes || [])) {
              if (!n || n.nodeType !== 1) continue;
              try {
                if (n.matches && n.matches(selector)) n.classList.toggle('wmeRcReducedMotionScope', active);
                if (n.querySelectorAll) n.querySelectorAll(selector).forEach((el) => el.classList.toggle('wmeRcReducedMotionScope', active));
              } catch {}
            }
          }
        });
        rcReducedMotionObserver.observe(document.documentElement || document.body, { childList: true, subtree: true });
      }
    } catch {}
  }

